CREATE TABLE IF NOT EXISTS legal_documents (
  id TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  "originalTitle" TEXT,
  "documentType" TEXT NOT NULL CHECK ("documentType" IN ('constitution','act','regulation','schedule_only')),
  "yearBs" NUMERIC NOT NULL,
  "yearAd" NUMERIC NOT NULL,
  "totalPages" INTEGER NOT NULL CHECK ("totalPages" >= 0),
  nodes JSONB NOT NULL
);

INSERT INTO legal_documents (id,title,"originalTitle","documentType","yearBs","yearAd","totalPages",nodes) VALUES (
  $LEGAL_83f35e1ef362eb$doc_national_penal_code_2074_2017$LEGAL_83f35e1ef362eb$,
  $LEGAL_83f35e1ef362eb$The National Penal (Code) Act, 2017$LEGAL_83f35e1ef362eb$,
  NULL,
  $LEGAL_83f35e1ef362eb$act$LEGAL_83f35e1ef362eb$,
  2074,
  2017,
  200,
  $LEGAL_83f35e1ef362eb${"id":"doc_national_penal_code_2074_2017","title":"The National Penal (Code) Act, 2017","originalTitle":null,"documentType":"act","yearBs":2074,"yearAd":2017,"totalPages":200,"nodes":[{"tier":1,"nodeType":"preamble","identifier":"Preamble","title":"Introductory matter","content":"Revised\nThe National Penal (Code) Act, 2017\nDate of Authentication:\n16 October 2017\nAct number 36 of the year 2017\nAn Act Made To Amend And Consolidate Laws In Force Relating To\nCriminal Offences\nPreamble:\nWhereas, it is expedient to provide for a tim ely code on criminal\noffences, by amending and consolidating the laws in force relating to\ncriminal offences, in order to uphold morality, decency, etiquette,\nconvenience, economic interest of the public, by maintaining law and order\nin the country, mainta in harmonious relationship and peace among various\nreligious and cultural communities, and prevent and control criminal\noffences;\nNow, therefore, the Legislature -Parliament referred to in clause (1)\nof Article 296 of the Constitution of Nepal has enacted this Act.\nPart -1\nGeneral Provisions","children":[]},{"tier":1,"nodeType":"chapter","identifier":"Chapter-1","title":null,"content":"Preliminary","children":[{"tier":2,"nodeType":"rule","identifier":"1","title":"Short title and commencement","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"This Act may be cited as the\n\"National Penal (Code) Act, 2017\".","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"It shall commence on 17 August 2018 (first day of the month\nof Bhadra of the year 2075).","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"2","title":"Extra-territorial application of the Act","content":"Any person who commits any\nof the following offences outside Nepal shall be punished under this Act\nas if he or she committed such offence in Nepal:\n(a) Any offence under Chapter 1 of Part 2 except Section\n54,\n(b) Any offence under Chapter 17 of Part 2 committed by\nkidnapping any person from Nepal,\n(c) Any offence under Sections 167, 276 and 279,\n(d) Any offence under Chapters 22 and 23 of Part 2\ncommitted with intent to bring into use in or import into\nNepal,\n(e) Any offence under this Act committed in the course of\ndischarging duties of any position in the Government of\nNepal, State Government or Local L evel or a body\ncorporate under full or majority ownership or control of\nthe Government of Nepal, State Governme nt or L ocal\nLevel.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"Any person who commits an offence under this Act on board\nan aircraft or ship registered in Nepal while it is outside Nepal shall be\npunished under this Act as if he or she committed the offence in Nepal.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"Any Nepali citizen who commits any of the following\noffences against a Nepali citizen outside Nepal shall be punished under this\nAct as if he or she committed the offence in Nepal:\n(a) Murder, or attempt to, abetment of, or conspiracy to,\nmurder,\n(b) Abandonment of the helpless person,\n(c) Grievous hurt,\n(d) Kidnapping, hostage-taking or illegal detention,\n(e) Rape or incest,\n(f) Criminal mischief against the Government of Nepal,\nState Government or Local Level or a body corporate\nunder full or majority ownership or control of the\nGovernment of Nepal, State Government or Local\nLevel, extortion, criminal breach of trust, forgery, theft,\ndeception, robbery or criminal misappropriation of\nproperty,\n(g) Offence under Section 158,\n(h) Offences relating to marriage under Chapter -11 of Part\n2,\n(i) Food and drug adulteration with the intention of\nimporting into Nepal,\n(j) Offences relating to medical treatment under Sections\n231, 232 and 233,\n(k) Offence under Chapter-2 of Part 3.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"3","title":"Definitions","content":"Unless the subject or the context otherwise requires, in\nthis Act,-\n(a) “court” means the Supreme Court, High Court or\nDistrict Court, and this term also includes a court, other\njudicial body or authority authorized by law to proceed\nand adjudicate any specific types of criminal offences,\n(b) “harbor” means sup plying any person with food, drink,\nshelter, money, in-kind, clothes, arms, ammunition or\nmeans of transport, or helping or otherwise assisting a ny\nperson to evade apprehension,\n(c) “offence” means an act punishable by this Act or law,\n(d) “law” means law for the time being in force,\n(e) “act” means a series of acts, and this term also includes\nomission to do an act required by law to be done or\ncommission of an act prohibited by law,\n(f) \"grave offence\" means an offence punishable by a\nsentence of imprison ment for a term of more than three\nbut less than ten years,\n(e) \"heinous offence\" means an offence punishable by\nimprisonment for life or for a term of more than ten\nyears,\n(f) \"body\" means the body of a human being,\n(g) “judge” means the authority of a co urt who proceeds,\nhears and adjudicates a case, and this term also includes\nany authority authorized to proceed, hear and adjudicate\nany specific type of criminal cases,\n(h) “public servant” means any of the following persons:","children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"a person elected, nominat ed or appointed to any\noffice with public accountability pursuant to the\nConstitution or other law,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"a person appointed to the service of the\nGovernment of Nepal or State Government or any\nother government service pursuant to law or a\ncontract,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"a pe rson elected, nominated or appointed to any\noffice of a Local Level or District Assembly or a\nperson appointed in any manner to the service of\nsuch Level or District Assembly,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"an office-bearer of a body corporate under full or\nmajority ownership or con trol of the Government\nof Nepal, State Government or Local Level or a\nperson appointed to the service of such body, or","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"a person otherwise appointed to, or holding, a ny\noffice with public accountability.\n(i) “Local Level” means a Village Body (Gownpalika) or\nMunicipality,\n(j) “body corporate” means a body established by any law\nor registered in accordance with law,\n(k) “Constitution” means the Constitution of Nepal,\n(l) “public document” means any of the following\ndocuments:","children":[]},{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"a document passed by the Legislature,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"a document recording official acts performed by\nthe President pursuant to the Constitution,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"a book, record or other document issued by the\nGovernment of Nepal, State Government or Local\nLevel or offices under the Government of Nepal,\nState Government or Local Level or\nConstitutional Body or office -bearer, court or\nbody established by an Act or Order, office of a\nbody corporate under full or majority ownership\nor control of the Government of Nepal or\nmaintained in the archive of such offices,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"a judgment, decision or order made by a court.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"4","title":"Generally applicable principles and provisions","content":"The principles\nand provisions referred to in Chapters -2, 3, 4 and 5 of Part 1 of this\nAct shall generally apply to the offences under this Act and other\nActs.","children":[]},{"tier":2,"nodeType":"rule","identifier":"5","title":"Application of special Act","content":"Where a special Act defines a specific\nact as a separate offence and provides punishment for it, that Act\nshall apply to such offence.","children":[]}]},{"tier":1,"nodeType":"chapter","identifier":"Chapter- 2","title":null,"content":"General Principles of Criminal Justice","children":[{"tier":2,"nodeType":"rule","identifier":"6","title":"Lawful act not to be offence","content":"No act required by law to be done or\nexcused by law shall be considered to be an offence.","children":[]},{"tier":2,"nodeType":"rule","identifier":"7","title":"Not punishment except in accordance with law","content":"No person shall\nbe liable to punishment for doing an act not punished by law nor\nshall a person be subjected to punishment which is heavier than the\none prescribed by law in force when the offence was committed.","children":[]},{"tier":2,"nodeType":"rule","identifier":"8","title":"Act done by mistake of fact not to be offence","content":"No act done by a\nperson who is, or who by reason of a mistake of fact, in good faith\nbelieves that he or she is bound by law to do that act or that such act\nis excused by law shall be considered to be an offence.\nProvided that no act done in ignorance of law shall be\nexcused.","children":[]},{"tier":2,"nodeType":"rule","identifier":"9","title":"No punishment again for the same offense","content":"No person shall be\nprosecuted in a court and punished again for the same offence.","children":[]},{"tier":2,"nodeType":"rule","identifier":"10","title":"No deprivation of fair trial","content":"No person shall be deprived of fair trial\nin proceedings by a competent court or judicial authority.","children":[]},{"tier":2,"nodeType":"rule","identifier":"11","title":"No compulsion to testify against oneself","content":"No person accused of an\noffence shall be compelled to testify against himself or herself.","children":[]},{"tier":2,"nodeType":"rule","identifier":"12","title":"Presumption of innocence until proven guilty","content":"A person accused\nof an offence shall be presumed innocent until proved guilty of that\noffence.","children":[]},{"tier":2,"nodeType":"rule","identifier":"13","title":"Act of a child not to be offence","content":"No act done by a child below ten\nyears of age shall be considered to be an offence.","children":[]},{"tier":2,"nodeType":"rule","identifier":"14","title":"Act of a person of unsound mind not to be offence","content":"No act done\nby a person who, at the time of doing it, by reason of unsoundness of\nmind, is incapable of knowing the nature, characteristic, fault or\nconsequence of such act, shall be considered to be an offence.","children":[]},{"tier":2,"nodeType":"rule","identifier":"15","title":"Act done by consent not to be offence","content":"Except where done with the\nintention of causing death or grievous hurt or with the knowledge\nthat it is likely to cause death or grievous hurt, no act done by a\nperson by obtaining consent of a person above eighteen years of age\nwhich causes any harm to the person who has given such consent\nshall be considered to be an offence.","children":[]},{"tier":2,"nodeType":"rule","identifier":"16","title":"Act done for benefit by consent not to be offence","content":"No act done by\na person in good faith and with due care for the benefit of another\nperson by consent of that other person which causes harm to that\nperson who has given such consent shall be considered to be an\noffence.","children":[]},{"tier":2,"nodeType":"rule","identifier":"17","title":"Act done for benefit by consent of guardian not t o be offence","content":"No\nact done in good faith and with due care for the benefit of a person\nbelow eighteen years of age, or of unsoundness of mind due to\nmental illness, by his or her guardian or another person by consent of\nthe guardian, which causes harm to that person shall be considered to\nbe an offence.\nProvided that except where done for the purpose of preventing\ndeath or grievous hurt, no person who does an act with the\nknowledge that it is likely to cause death or grievous hurt shall be\ndispensed with criminal liability.","children":[]},{"tier":2,"nodeType":"rule","identifier":"18","title":"Act done for benefit without consent not to be offence","content":"Where any\nact must be done immediately for the benefit of a person, and such\nperson is, for any reason, not in a position to give consent\nimmediately or has no guardian from whom it is possible to obtain\nconsent on such person's behalf immediately, such act done in good\nfaith and with due care for the benefit of that person without his or\nher consent, which causes harm or injury to that person, shall not be\nconsidered to be an offence.\nExplanation: For the purposes of Sections 16 and 17, and this\nSection, the term “benefit” does not mean:","children":[{"tier":3,"nodeType":"clause","identifier":"(a)","title":null,"content":"a pecuniary benefit,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(b)","title":null,"content":"an act done with intent to cause death, or without any\nreasonable cause, a grievous hurt.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"19","title":"To be considered an of fence even committed by consent","content":"Notwithstanding anything contained in Section 15,16 or 17, where\nany act referred to in any of those Sections is considered to be\nanother offence under law, such act shall be considered to be an\noffence even if it is done by consent.","children":[]},{"tier":2,"nodeType":"rule","identifier":"20","title":"Consent","content":"Consent may be expressed orally or in writing or by\ngesture or conduct.\nProvided that consent given in any of the following\ncircumstances shall not be considered to be consent:","children":[{"tier":3,"nodeType":"clause","identifier":"(a)","title":null,"content":"Where the consent is given by a person under a\nmistake of fact or fear or threat of any kind of\ninjury or harm and the doer of the act in\npursuance of such consent knows, or has reason\nto believe, that the consent was so given,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(b)","title":null,"content":"Where the consent is given by a person who,\nbeing of unsound mind due to me ntal illness, is\nunable to understand characteristic, fault and\nconsequence of the consent given by him or her\nwhen he or she was in a state of unsoundness of\nmind,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(c)","title":null,"content":"Where the consent is given by a child below\neighteen years of age,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(d)","title":null,"content":"Where the consen t is given under undue\ninfluence.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"21","title":"Harm caused by communication made in good faith not to be","content":"offence: No information or communication of any matter made in\ngood faith shall be considered to be an offence by reason of any harm\nto the person to whom it is made, if it is made for the benefit of that\nperson.","children":[]},{"tier":2,"nodeType":"rule","identifier":"22","title":"Act compelled by fear, threat not to be offence","content":"No act done by a\nperson who is compelled to do it by fear or threat exerted or made by\nanother person carrying a deadly weapon or toxic or explosive\nsubstance that the other person would kill or cause grievous hurt to\nthat person or his or her close relative if that person does not do that\nact immediately and there is a reasonable cause to apprehend that it\nwould cause death or grievous injury to that p erson or close relative if\nsuch act is not done immediately shall be considered to be an offence.\nProvided that such act shall be considered to be an offence if:\n(a) Death or grievous hurt is caused,\n(b) Rape is committed,\n(c) An offence against the State is committed, or\n(d) The doer of such act pla ced himself or herself in such\nsituation of fear or threat, of his or he r own accord or as\na result of any thing done by himself or herself.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who causes the offence to be committed by\nexerting fear or threat under sub-section (1) shall be punished by law\nas if he or she committed the offence by himself or herself.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"23","title":"Act done in good faith to prevent other harm, injury not to be","content":"offence: Any act done by a person shall not be considered to be an\noffence merely by reason of its being done with the knowledge that it\nis likely to cause harm, injury, if it be done without any criminal\nintent to cause harm, injury, and in good faith for the purpose of\npreventing or avoiding possible great harm, injury to l ife, person or\nproperty and it was so imminent that greater harm, injury than such\nact was likely to result in would be caused to the life, person or\nproperty of him or her or any one else if such act was not done\nimmediately.","children":[]},{"tier":2,"nodeType":"rule","identifier":"24","title":"Act done for private def ence not considered to be offence","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"Any act done in the exercise of the right of private defence subject to\nthis Chapter shall not be considered to be an offence.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"Every person has a right to defend the body, life or\nproperty of his or her own or of any other person against any illegal\nharm.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"The right of private defence under this Section shall be\nexercised only when there is a reasonable apprehension or reasonable\ncause to believe that the body, life or property of his or her own or of\nany other person cannot be defended against any illegal harm unless\nany act is done immediately.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"25","title":"Restriction on the exercise of right of private defense","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"Notwithstanding anything contained in Section 24, the right of\nprivate defen se is not available in the f ollowing circumstances or\nagainst the following acts:\n(a) Where there is time to have or likely to have recourse\nto the protection of public authority immediately to\ndefend the body or property of any one against illegal\nharm at the time of causing such harm,\n(b) Where harm caused to the body or property of a person\nwas so caused by reason that the harm doer was\nprovoked by such person himself or herself,\n(c) Where a public servant does an act in good faith in\npursuance of a judgment or order of a court,\n(d) Where a public servant does an act in good faith in the\nexercise of his or her official power,\n(e) Where any act is done by a person in pursuance of a\ndirection given in good faith by a public servant in the\nexercise of his or her official power.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"Notwithstanding anything contained in sub -section (1),\na person shall not be deprive d of the right of private defens e in the\nfollowing circumstances:\n(a) Where that person does not know or have a\nreasonable reason to believe that the doer of the act\nreferred to in clause (c) of sub-section (1) is a public\nservant and he or she is doing the act in pursuance of\nthe judgment or order of a court or the doer does not\ndisclose his or her identity or produce the authority\nunder which he or she acts even if so demanded,\n(b) Where there is no reasonable reason to know or\nbelieve that the doer of the act referred to in clause\n(d) of sub-section (1) is a public servant,\n(e) Where there is no reasonable re ason to know or\nbelieve that the doer of the act referred to in cla use\n(e) of sub -section (1) is doing such act by the\ndirection of a public servant or the doer does not\nstate that authority under which he or she acts or\ndoes not produce the authority under which he or she\nacts even if so demanded.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"While exercising th e right of private defenc e under\nSection 24 or this Section, more force than reasonably necessary for\nsuch defence cannot be used.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"26","title":"No right to cause death","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"In exercising the right of private\ndefence pursuant to this Chapter, no one shall have the r ight to cause\na person’s death.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"Notwithstanding anything contained in sub -section (1),\nif any act done in the exercise of the right of private defence subject\nto sub -section (3) of Section 25, in any of the following\ncircumstances, causes the death of a person, such act shall not be\nconsidered to be an offence:\n(a) Where there is reasonable cause to believe that an assault on\noneself or another person would cause the death of or\nserious injury or grievous hurt to oneself or another person\nunless instant defence is exercised against such assault,\n(b) Where any act is instantly done by the victim having\nreasonable cause to believe that the assault is made with the\nintention of committing rape or at the time of or after the\ncommission of rape,\n(c) Where hostage-taking or kidnapping is committed with the\nintention of causing death, taking ransom for hostage-taking\nor kidnapping, committing rape, causing grievous hurt,\n(d) Where attempt is made to cause mischief by seizing, using a\ndeadly weapon, setting fire to or using explosive substance\non, any building, tent which is used for human dwelling or\nas the place for worship or pray or the custody of property\nor a means of transport,\n(e) Where it is necessary to defend against robbery,\n(f) Where the circumstance requires an instant retaliation by a\nsecurity personnel deputed by order of the competent\nauthority for the personal security of a person or security of\na property of the Government of Nepal, State Government\nor Local Level or a body corporate under full o r majority\nownership or control of the Government of Nepal, State\nGovernment or Local Level or public property in order to\nprevent an assault made on such person or property.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"27","title":"Act causing slight harm not to be offence","content":"A slight harm not to be\ncomplained of by a person of ordinary sense shall not be considered\nto be an offence.","children":[]},{"tier":2,"nodeType":"rule","identifier":"28","title":"Major liable to punishment for offence caused to be committed","content":"by child: Where an offence is committed by a child upon being\nlured, taught or influenced by a person to do so, su ch person shall be\nliable to punishment as if the offence were committed by himself or\nherself.","children":[]},{"tier":2,"nodeType":"rule","identifier":"29","title":"Criminal intention not to be examined in strict liability offence","content":"In an offence which is a strict liability offence under this Act or the\nlaw, there shall not be examined whether or not the offence was\ncommitted intentionally.","children":[]},{"tier":2,"nodeType":"rule","identifier":"30","title":"Criminal liability for offence committed by body corporate to be","content":"vested on one who commits or causes the commission of the act:\nWhere any firm, company or body corporate commits, or causes the\ncommission of, an act considered to be an offence under this Act or\nlaw, the person who committed , or caused the commission of , such\noffence shall be responsible for such act; and where such person\ncannot be identified, the concerned owners a nd partners who did\nsuch act, in the case of a firm, the director, managing director,\ngeneral manager who did or caused the doing of such act, in the case\nof a company or body corporate, and where even such person cannot\nbe identified, the chief executive of such body shall bear the criminal\nliability.","children":[]},{"tier":2,"nodeType":"rule","identifier":"31","title":"All members to be punished for offence committed by a group","content":"Where an offence is committed by a group of two or more persons,\nall members of the group shall be liable to punishment for such\noffence.","children":[]},{"tier":2,"nodeType":"rule","identifier":"32","title":"Victim of crime to be entitled to obtain information of","content":"proceedings of case and compensation: (1) The victim of crime\nshall have the right to obtain information about the investigation and\nproceedings of the case in which he or she is the victim.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"The victim of crime shall have the right to justice with\nsocial rehabilitation and compensation.","children":[]}]}]},{"tier":1,"nodeType":"chapter","identifier":"Chapter -3","title":null,"content":"Criminal Conspiracy, Attempt, Abetment and Accomplice","children":[{"tier":2,"nodeType":"rule","identifier":"33","title":"Prohibition of criminal conspiracy","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall make a\ncriminal conspiracy.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"Where two or more persons agree to commit, or cause\nthe commission of, an offence, and any act is done by only one or\ntwo of them, they shall be considered to have committed a criminal\nconspiracy.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"A person who commits , or causes the commission of , a\ncriminal conspiracy to commit an offence of heinous or grave nature\nshall, where no provision is made elsewhere in this Act for a separate\npunishment for such conspiracy, be punished as follows:\n(a) Where the offence in pursuance of the criminal\nconspiracy is committed, punishment imposable\nif the offence had been committed,\n(b) Where another offence instead of the offence in\npursuance of the criminal conspiracy is\ncommitted and such other offence is committed in\nthe course of implementation of such conspiracy\nor a s probable consequence thereof, punishment\nspecified for that offence,\n(c) Where any offence in addition to the offence in\npursuance of the criminal conspiracy is also\ncommitted and such offence is also committed in\nthe course of implementation of su ch conspiracy\nor as a probable consequence thereof, additional\npunishment also for such offence,\n(d) Where the offence of criminal conspiracy is yet to\nbe completed, one half of the punishment\nspecified for that offence.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"34","title":"Prohibition of attempt to commit offence","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall make\nattempt to commit an offence.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"Even if it is impossible for an offence to be committed\nfor which attempt is made, attempt shall be considered to have been\ncommitted.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"Except as otherwise provided elsewhere in thi s Act, a\nperson who attempts, or causes attempt , to commit an offence shall\nbe punished with one half of the punishment specified for such\noffence.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"35","title":"Prohibition of abetment","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall abet another person to\ncommit an offence.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"For the p urposes of sub -section (1), where a person\ninstigates another person to commit an offence, the person is\nconsidered to have abetted.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"The abettor shall be liable to the separate punishment, if\nany, provided for in this Act, and to the following p unishment if such\nseparate punishment is not so provided for:\n(a) Where the offence is committed in pursuance of the\nabetment, the punishment imposable as if he or she had\ncommitted the offence,\n(b) Where the offence is yet to be committed in pursuance\nof the abetment, one half of the punishment specified\nfor such offence.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"Where an offence is abetted but a different offence is\ncommitted by the abetted person, and that offence was committed\nunder the influence of the instigation or was a probable cons equence of\nthe abetment, the abettor shall be liable to punishment as if he or she\nhad committed such offence as well.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"36","title":"Not to be accomplice","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No pers on shall become an accomplice to\nany offence.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who, with the intention of committi ng an\noffence, aids in the commission of such offence or other offence or\nwho hides the offender or helps the offender to escape after the\ncommission of the offence or who provides means to commit, or causes\nthe commission of, the offense or otherwise assi sts in the commission\nof the offence shall be deemed to be an accomplice.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"An accomplice shall be punished as follows:\n(a) A person who, with participation in a criminal\nconspiracy, commits an offence, provides means\nor place to commit the offence, or deprives the\nperson against whom the offence is committed of\nthe right of private defence or who orders or\nadvises to commit the offence, shall be punished\nas if he or she had committed such offence,\n(b) For an accomplice other than one referred to in\nclause (a), punishment not exceeding one half of\nthe punishment imposable for the commission of\nsuch offence according to the degree of his or her\ninvolvement in that act.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"37","title":"Statute of limitation to be applicable","content":"The statute of limitation\nprovided for in this Act for making a compliant in relation to an\noffence shall also be applicable to the conspiracy, abetment ,\naccomplice of, or attempt to, such offence.","children":[]}]},{"tier":1,"nodeType":"chapter","identifier":"Chapter-4","title":null,"content":"Gravity of Offence Aggravating and Mitigating Factors","children":[{"tier":2,"nodeType":"rule","identifier":"38","title":"Factors aggravating the gravity of offence","content":"For the purposes of\nthis Act, the following factors, if exist, shall be considered as\naggravating the gravity of an offence:","children":[{"tier":3,"nodeType":"clause","identifier":"(a)","title":null,"content":"The offence was committed against the President or\nHead of Government or head of a foreign State,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(b)","title":null,"content":"The offence was committed in presence of the President\nor Head of Government or head of a foreign State,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(c)","title":null,"content":"The offence was committed by the breach of trust,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(d)","title":null,"content":"The offence was committed by taking benefit of or\nabusing a public office,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(e)","title":null,"content":"The offence was committed with the intention of\nobstructing a person holding a public office in\ndischarging his or her official duty or to cause such\nperson to commit an illegal act,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(f)","title":null,"content":"The offence was committed in any government office,\npublic office or religious place,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(g)","title":null,"content":"The offence was committed by five or more persons\naffiliated in a group,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(h)","title":null,"content":"The offence was committed by taking advantage of the\ndisturbance of public peace or landslide, flood,\nearthquake or natural calamity of similar nature or\noutbreak of epi demic, starvation or occurrence of any\nother crisis of similar nature,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(i)","title":null,"content":"The offence was committed by carrying or using an arm\nor toxic or explosive substance or supplying electricity\nor using an electronic device or with the aid of a person\ncarrying an arm, toxic or explosive substance,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(j)","title":null,"content":"The offence was committed again by an offender\nalready sentenced to imprisonment,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(k)","title":null,"content":"The offence was committed by being allured of any\nremuneration or assurance or benefit,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(l)","title":null,"content":"The offence was committed against a per son under\none’s own protection or control or against the property\nunder one’s own custody,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(m)","title":null,"content":"The offence was committed by subjecting any one to\ntorture, cruel, inhumane or degrading treatment,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(n)","title":null,"content":"More than one offence were committed on a single\noccasion,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(o)","title":null,"content":"The offence was committe d against more than one\nperson on a single occasion,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(p)","title":null,"content":"The offence was committed by kidnapping any one or\ntaking any one hostage,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(q)","title":null,"content":"T he offence was committed against a person under\ndetention, custody, imprisonment or control,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(r)","title":null,"content":"The offence was committed by one who has a duty to\nprovide security to any person against that person,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(s)","title":null,"content":"The offence was committed with the intention of\ndestroying the identity of any caste, race or group\n(genocide),","children":[]},{"tier":3,"nodeType":"clause","identifier":"(t)","title":null,"content":"The offence was commit ted with the intention of\ncausing hatred against any caste, race, religious or\ncultural community,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(u)","title":null,"content":"The offence committed was a crime against humanity,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(v)","title":null,"content":"The offence was committed in a planned or organized\nmanner,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(w)","title":null,"content":"The offence was committed against an elderly person\nabove seventy-five years of age or a person being of\nunsound mind by reason of physical or mental illness or\na person incapable of defending himself or herself\nbecause of disability, or a child,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(x)","title":null,"content":"The offence was committed by a person deputed in\nrescue work in cases of motor vehicle , aircraft accident\nor natural calamity while being engaged in such rescue\nwork,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(y)","title":null,"content":"The offence was another offence committed by the same\noffender against the person who had already become a\nvictim of an offence.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"39","title":"Factors mitigating the gravity of offence","content":"For the purposes of this\nAct, the following factors, if exist, shall be considered as mitigating\nthe gravity of an offence:","children":[{"tier":3,"nodeType":"clause","identifier":"(a)","title":null,"content":"The offender is below eighteen years or above seventy-\nfive years of age,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(b)","title":null,"content":"The offender had no intention to commit the offence,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(c)","title":null,"content":"The person against whom the offence was committed\nhad, immediately before the commission of the offence,\nprovoked or given threat to the offender,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(d)","title":null,"content":"The offence was committ ed instantly as a retaliation\nagainst any grave offence committed against the offender\nor any of his or her close relatives,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(e)","title":null,"content":"The offender voluntarily confessed the offence or\nexpressed a remorse therefor,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(f)","title":null,"content":"The offender surrendered himself or herself to the\nconcerned authority,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(g)","title":null,"content":"The offender, having confessed the offence committed by\nhim or her, has already provided or agreed to pay\ncompensation to the victim,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(h)","title":null,"content":"The offender has diminished capacity because of\nphysical, mental ability or disability,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(i)","title":null,"content":"The extent o f loss or harm caused to the victim and the\nsociety being insignificant,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(j)","title":null,"content":"The offender rendered assistance in judicial process by\ntelling the truth to the court,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(k)","title":null,"content":"The offender has confessed the guilt and committed not\nto commit any criminal offence in the future,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(l)","title":null,"content":"The offence was committed under other's instigation or\npressure.","children":[]}]}]},{"tier":1,"nodeType":"chapter","identifier":"Chapter-5","title":null,"content":"Provisions Relating to Punishment and Interim Relief","children":[{"tier":2,"nodeType":"rule","identifier":"40","title":"Types of punishment","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"The punishments for the offences set\nforth in this Act shall be as follows:\n(a) Imprisonment for life,\n(b) Imprisonment,\n(c) Fine,\n(d) Imprisonment and fine,\n(e) Compensation,\n(f) Imprisonment for the failure to pay a fine or\ncompensation,\n(g) Community service in lieu of imprisonment.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"Where any law provides for the sentence of confiscation\nof property for any offence, such sentence of confiscation shall not\nbe imposed for that offence, after the commencement of this Act.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"Notwithstanding anything contained in this Section, no\nsentence of fine of less than one rupee and of impri sonment for a\nterm of less than one day shall be imposed.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"41","title":"Imprisonment for life","content":"Notwithstanding anything contained\nelsewhere in this Act, in imposing a sentence of imprisonment on an\noffender for the following offence, the offender shall be subjected to\nimprisonment for the whole of his or her natural life:","children":[{"tier":3,"nodeType":"clause","identifier":"(a)","title":null,"content":"Murder with cruelty, torture or inhumane conduct,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(b)","title":null,"content":"Murder by hijacking or exploding an aircraft,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(c)","title":null,"content":"Murder by kidnapping or taking hostage,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(d)","title":null,"content":"Murder by poisoning publicly consumable bevera ges\nor food,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(e)","title":null,"content":"Genocide (destroying the identity of any caste, race or\ngroup) or offence committed with the objective of\ncommitting genocide,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(f)","title":null,"content":"Murder with rape.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"42","title":"Computation of imprisonment for life","content":"Except in the circumstance\nreferred to in Se ction 41, the sentence of imprisonment for life shall\nbe so computed that its term is twenty-five years.","children":[]},{"tier":2,"nodeType":"rule","identifier":"43","title":"One and half punishment for consolidated/integrated offence","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"Where a person, at the time of judgment by a court, is convicted of\nmore than one offence on a single occasion or different offences on\ndifferent occasions, such person shall be deemed to have committed\na consolidated offence.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"The offender who commits a consolidated offence\nreferred to in sub-section (1) shall be sentenced for the o ffence\npunishable by the maximum punishment and to additional\npunishment of one half of that punishment specified for such\noffence.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"44","title":"Additional punishment for offender of heinous crime and","content":"recidivist: (1) If a person who was sentenced for an y offence\ncommits another heinous or grave offence before the expiry of a\nperiod of five years after the date on which he or she completed the\nservice of that sentence or was granted pardon, he or she shall be\nconsidered to be a recidivist.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A recidivist shall be liable to a punishment that is up to\ndouble the punishment imposable for the last offence committed by\nhim or her.\nProvided that this Section shall not apply to an offender who\nhas been sentenced to imprisonment for life pursuant to Section 41.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"45","title":"Punishment imposable on children","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"A person who commits an\nact constituting an offence under the law shall not be liable to any\npunishment if that person has not attained ten years of age at the time\nof the commission of such act.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"In imposing the punishm ent of imprisonment on a\nperson who is ten years of age or above ten but below fourteen years\nof age, such person may be sentenced to imprisonment for a\nmaximum of six months or sent to a reform home for a maximum of\none year in lieu of such imprisonment.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"Where a person who is fourteen years of age or above\nfourteen but below sixteen years of age commits any offence\npunishable by imprisonment, such person shall be liable to half the\npunishment imposable by law on a person who has attained majority.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"Where a person who is sixteen years of age or above\nsixteen but below eighteen years of age commits any offence\npunishable by imprisonment, such person shall be liable to two -\nthirds of the punishment imposable by law on a person who has\nattained majority.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"46","title":"Imprisonment for fine","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"Any offender who is unable to pay a\nfine imposed on him or her may be subjected to imprisonment.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"The term of imprisonment under sub-section (1) shall be\ndetermined as follows:\n(a) In determining the sentence of impriso nment in\ndefault of payment of a fine for an offence\npunishable by both imprisonment and fine, the\nterm of imprisonment shall be so determined as\nnot to exceed ten years.\n(b) Where an offence is punishable by either\nimprisonment or fine or with both, in wh ich the\noffender is sentenced to a fine only, in\ndetermining the sentence of imprisonment in\ndefault of payment of such fine, the term of\nimprisonment shall be so determined as not to\nexceed one half of the maximum term of\nimprisonment that can be imposed for such\noffence,\n(c) Where an offence is punishable by fine only, in\nwhich the offender is sentenced to a fine, in\ndetermining the sentence of imprisonment in\ndefault of payment of such fine, the term of\nimprisonment shall be so determined as not to\nexceed two years.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"Notwithstanding anything contained in sub -section (2),\nthe following provisions shall apply to the imposition of a sentence\nof imprisonment for non-payment of a fine on a child below eighteen\nyears of age:\n(a) In the event of non -payment of a fine for an\noffence punishable by fine only or by either fine\nor imprisonment, the child shall not be subjected\nto imprisonment and the fine shall be remitted.\n(b) Where an offence is punishable by imprisonment\nor fine or both, in which the offender is sentenced\nto a fine only, in determining the sentence of\nimprisonment in default of payment of such fine,\nthe term of imprisonment shall be so determined\nas not to exceed three months.\n(c) In determining the sentence of imprisonment\npursuant to sub -section (2) to be imposed on a\nperson who is above fourteen but below eighteen\nyears of age, the term of imprisonment shall be so\ndetermined as not to exceed half the sentence of\nimprisonment imposable on a person above\neighteen years of age.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"47","title":"Remission of sentence","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"Where any offender, upon having\nconfessed the offence committed by him or her, has assisted in the\ncollection of evidence, apprehension of other accused person or gang\nor accomplice thereof, in relation to such offence or assisted the\ninvestigating or prosecuting authority or the court, a maximum of\nfifty percent of the sentence imposable under law for such offence\nmay be remitted.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"Notwithstanding anything contained in sub -section (1),\nthe following offender shall not be entitled to the r emission of\nsentence:\n(a) One who has once obtained remission under sub -\nsection (1),\n(b) One who has been convicted of any offence\npunishable by imprisonment, and a period of\nthree years has not lapsed since the completion of\nservice of the sentence of imprisonment,\n(c) One who has once been sentenced for any offence\nof the same nature as in which the remission of\nsentence is sought.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"In granting a remission of punishment pursuant to sub -\nsection (1), regard shall be had to, inter alia , at which stage o f\ninvestigation or trial the accused has confessed the offence and in\nwhat circumstances he or she has made such confession.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"48","title":"Power of court to order interim compensation","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"Notwithstanding anything contained elsewhere in thi s Act, where it\nis necessa ry to immediately provide medical treatment or\ncompensation or any type of relief amount to a person who has\nbecome victim of an offence in consequence of its commission or a\nperson who is dependent on him or her, the court may order the\nperson accused of such offence to provide medical treatment or pay\nan interim compensation or relief amount to such person.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"Where an order is made pursuant to sub -section (1), the\nperson so accused shall immediately provide such compensation or\namount to the victim or person dependent on him or her.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"Where the accused is unable to provide the\ncompensation or amount pursuant to sub -section (2) in accordance\nwith the order referred to in sub-section (1), the court shall order that\nthe compensation or amount be provided to the victim or person\ndependent on him or her from the victim relief fund established\npursuant to the laws in force related to the determination and\nexecution of sentences for criminal offence s, and the amount so\nprovided shall be recovered from such acc used person and\nreimbursed into such fund.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"Where a person who has paid compensation or relief\namount pursuant to this Section is acquitted of the charge by the\njudgment of the court, the person who has received such\ncompensation or relief amount shall , within thirty-five days of such\nacquittal, return such amount to such person or to the victim relief\nfund referred to in sub-section (3).","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"Where such person does not return such amount within\nthe period referred to in sub-section (4), the court shall cause such\namount to be recovered from any assets of such person within thirty-\nfive days of such acquittal.\nPart-2\nCriminal Offences","children":[]}]}]},{"tier":1,"nodeType":"chapter","identifier":"Chapter-1","title":null,"content":"Offences against the State","children":[{"tier":2,"nodeType":"rule","identifier":"49","title":"Prohibition of undermining sovereignty, integrity or national","content":"unity: (1) N o person shall, with the intention of undermining the\nindependence, sovereignty, geographical or territorial integrity or\nnational unity of Nepal, collect persons, arm s and ammunitions,\nbuild any armed military or paramilitary organization or attempt to\ncommit such act.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"No person shall make, or cause to be made, any kind of\nconspiracy, in association with any foreign state, government or\norganized force, to undermine the independence, sovereignty,\ngeographical or territorial integrity or national unity of Nepal.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"No person shall abet the commission of the offence\nunder sub-section (1) or (2).","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"No person shall commit, or cause to be committed, any\nact that gives rise to hatred, enmity or contempt on grounds of class,\nrace, religion, region, commun ity or similar other ground, which is\nlikely to jeopardize the sovereignty , geographical or territorial\nintegrity, nationality , national unity, independence, dignity, or\nharmonious relations between federal units, of Nepal or attempt to\ncommit, or abet the commission of, or make conspiracy to commit,\nsuch act, or undermine or cause to be undermined the cordial\nrelations subsisting between different castes, races or communities.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in this Section shall be sentenced to the following\npunishment:\n(a) Imprisonment for life in the case of the offence referred\nto in sub-section (1) or (2),\n(b) Imprisonment for a term not exceeding ten years and a\nfine not exceeding one hundred thousand rupees in th e\ncase of the offence referred to in sub-section (3),\n(c) Imprisonment for a term not exceeding five years and a\nfine not exceeding fifty thousand rupees in the case of\nthe offence referred to in sub-section (4).","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"50","title":"Sedition","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall, with the int ention of overthrowing the\nGovernment of Nepal or the constitutional structure, create any kind\nof disorder by demonstrating or using military, paramilitary or\ncriminal force or form an armed military or paramilitary organization\nor make conspiracy, attempt or incitement to commit such act.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits the offence referred to in sub-\nsection (1) shall be liable to punishment with imprisonment for a\nterm not exceeding twenty-five years.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"No person shall, by words, either spoken or written or\nby figure or signs or otherwise, showing any baseless or\nunsubstantiated matter in relation to the Government of Nepal or any\naction of the Government of Nepal, bring or attempt to bring into\nhatred, enmity or contempt towards the Government of Nepal or\ncause the commission of such act.\nProvided that nothing contained in this sub -section shall be\nconsidered to render any healthy or decent criticism of the\nGovernment of Nepal to be the offence.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"A person who commits the offence referred to in sub-\nsection (3) shall be liable to the sentence of imprisonment for a term\nnot exceeding three years or a fine not exceeding thirty thousand\nrupees.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"51","title":"Prohibition of act against national interest","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No one shall do, or\ncause to be done, any act against national interest.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"For the purpose s of sub -section (1), where any person\ndoes, or causes to be done, any of the following acts, he or she shall\nbe considered to have done an act against national interest:\n(a) To dishonor or degrade or spread hatred or\nenmity against the freedom, sovereignty,\ngeographical or territorial integrity, nationality,\nindependence, self -esteem of, or international\nimage of, Nepal,\n(b) To encroach the international boundary of Nepal,\nor remove or dislocate any boundary pillar,\nexcept in accordance with agreement with a\nneighbouring country, or to so change any\nboundary pillar as to be prejudicial to the\ngeographical or territorial integrity of Nepal.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"Any Nepali player or a group of Nepali players, who\nrepresenting Nepal, plays any match in competition with any player\nor players in Nepal or a foreign country shall not play, or cause to be\nplayed, such match in connivance with or under the influence of any\none in a manner to manipulate a natural result of such match or to\nmake a bet w in or lose , and where any match has been so played,\nthe offence against national interest shall be considered to have been\ncommitted.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"Any person who commits the offence referred to in sub-\nsection (2) or (3) shall be liable to the following punishment:\n(a) A sentence of imprisonment for a term not\nexceeding five years and fine not exceeding fifty\nthousand rupees, in the case of the offence\nreferred to in sub-section (2),\n(b) A sentence of imprisonment for a term not\nexceeding three years and fine not e xceeding\nthirty thousand rupees, in the case of the offence\nreferred to in sub-section (3).","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"Where any person has transacted money in the course of\nthe commission of the offence referred to in sub-section (2) or (3),\nthe amount of money so transacted sh all be forfeited, in addition to\nthe punishment pursuant to sub-section (4).","children":[]},{"tier":3,"nodeType":"clause","identifier":"(6)","title":null,"content":"Any person who orders, directs, abets, incites or\nfacilitates the commission of the offence referred to in sub-section","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"shall be liable to punishment as if that person were the principal\noffender.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(7)","title":null,"content":"Where the offence referred to in sub-section (2) or (3) is\ncommitted by a public office holder or a person representing Nepal,\nwhile in a foreign country, he or she shall be liable to additional\nsentence of imprisonment for a term not exceeding three years.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"52","title":"Prohibition of genocide","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall commit, or cause to be\ncommitted, genocide.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"For the purpose of sub -section (1), any of the following\nacts committed with intent to destroy, in whole or in part, an\nethnical, racial, national or religious group, or any attempt or\nconspiracy to commit such act, shall be considered to be the offence\nof genocide:\n(a) Mass killing of members of such group, in a\nplanned way, at one or several times,\n(b) Causing grievous hurt t o the body of, or causing\nserious bodily or mental harm to, members of\nsuch group, in a planned way, at one or several\ntimes,\n(c) Deliberately inflicting on the group conditions of\nlife, inter alia , the depriving its members of\naccess to essential goods such as water, food, fuel\nand medicine, by hindering the supply or\nmovement of such goods, thereby deliberately\nmaking painful the life of members of such\ngroup, calculated to bring about its physical\ndestruction in whole or in part,\n(d) Forcibly imposing measures on members of such\ngroup intended to prevent births within the group,\nexcept in cases of voluntary use by such members\nof family planning means,\n(e) Forcibly transferring children of such group to\nanother group.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"Any person who commits the offence referred to in sub-\nsection (1) shall be liable to the following punishment:\n(a) Imprisonment for life, in the case of the offence\nreferred to in clause (a),\n(b) Imprisonment for a term not exceeding five years\nand fine not exceeding fifty thousand rupees , in\naddition to the sentence imposable under this Act\nfor grievous hurt or hurt to human body, in the\ncase of the offence referred to in clause (b),\n(c) Imprisonment for a term not exceeding ten years,\nin the case of the offence referred to in clause (c),\n(d) or (e).","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"Where the offence referred to in this Section is\ncommitted in pursuance of order or direction given by a person or\ngroup, whether organized or unorganized, the person, or the\nresponsible person or persons of such group giving such order o r\ndirection shall be liable as the principal offender.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"Where the offence referred to in this Section has been\ncommitted by a group or with the involvement of several persons,\nevery person involved in such offence shall be equally liable as the\noffender.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(6)","title":null,"content":"Where any person who commits the offence referred to\nin this Section is a public office holder, he or she shall not be\nallowed to make a plea that such offence has been committed in the\ncourse of executing a superior order or maintaining law and orde r or\nenforcing law, and that person shall not enjoy any remission or\nwaiver from sentence on the ground that he or she has made such\nplea.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"53","title":"Prohibition of waging war against Nepal or assist the army of a","content":"State at war with Nepal: (1) No person shall wag e or declare to\nwage war against Nepal, by raising arms, or attempt or threat to\nwage such war, or collect arms, ammunition or form a military or\nparamilitary organization with intent to wage war against Nepal.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"No person shall, in any situation whether a state of war\nis declared or not, supply any kind of strategic or military\ninformation or otherwise render assistance to any foreign army\nengaged in war with Nepal or attempt to do so.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"Where a declaration is made by the Government of\nNepal prohibiting the making of relation or transaction with a State\nengaged in war with Nepal, any citizen or corporate body of such\nState or the importing or obtaining of any goods or services of such\nState, no person shall make such relation or transaction with such\nState, citizen or body or import or obtain such goods or services.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) or (2) shall be liable to a\nsentence of imprisonment for life, and a person who commits the\noffence referred to in sub-section (3) shall be liable to a sentence of\nimprisonment for a term not exceeding twenty-five years and a fine\nnot exceeding one hundred thousand rupees.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"54","title":"Prohibition of waging war or insurrection against friendly State","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall, using the territory of Nepal, wage or threaten to\nwage war, by raising arms, or attempt to wage such war or insurrect\nor attempt to insurrect against a State having diplomatic relations\nwith Nepal.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) shall be liable to a sentence of\nimprisonment for a term not exceeding seven years and a fine not\nexceeding seventy thousand rupees.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"55","title":"Prohibition of giving provocation to army or p olice","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No\nperson shall abet or give provocation to the desertion of a soldier,\npolice or armed police personnel or officer in the Nepal Army, Nepal\nPolice or Armed Police Force, Nepal from the Nepal Army, Nepal\nPolice or Armed Police Force, Nepal or abet the breach of di scipline\nby such soldier, police or armed police personnel or attempt to\nseduce such soldier, police or armed police personnel from his or her\nduty, or, knowing or having reason to believe that a soldier, police or\narmed police personnel has so deserted th e Army or Police or Force,\nharbor such deserter.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be\ncommitted the offence referred to in sub-section (1) shall be liable to\na sentence of imprisonment for a term not exceeding ten years and a\nfine not exceeding one hundred thousand rupees.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"56","title":"Prohibition of espionage","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall, with intent to\nundermine the sovereignty, security or geographical or territorial\nintegrity of Nepal or to prejudice the interests of Nepal or with the\nknowledge that such consequ ence is likely, or being induced by any\nforeign country or international organization, supply to any one any\ninformation relating to the military situation, strategic arrangement\nor internal security of Nepal or relating to any matter that must be\nkept con fidential by the Government of Nepal from the political,\neconomic or diplomatic viewpoint or confidential document, or any\nmatter that is confidential or must be kept confidential under law or\nconspire or attempt to commit, or abet the commission of, such act or\ndo any other act with intent to supply such informati on, and a person\nwho commits such act shall be considered to have committed\nespionage.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committed,\nespionage referred to in sub-section (1) shall be liable to punishment\nas follows:\n(a) In the case of a person who commits, or causes to be\ncommitted, espionage in relation to any matter of\nmilitary situation, strategic arrangement or internal\nsecurity of Nepal, a sentence of imprisonment for a term\nnot exceeding twenty-five years,\n(a) In the case of a person who commits, or causes to be\ncommitted, espionage in relation to any matter that must\nbe kept confidential by the Government of Nepal from\nthe political, economic or diplomatic viewpoint or any\nother confiden tial document, that must be kept\nconfidential by the Government of Nepal from the\npolitical, economic or diplomatic viewpoint or any other\nconfidential document, a sentence of imprisonment for a\nterm ranging from five to ten years,\n(c) In the case of a per son who commits, or causes to be\ncommitted, espionage in relation to any matter other\nthan that set forth in clauses (a) and (b), a sentence of\nimprisonment for a term not exceeding five years and a\nfine of fifty thousand rupees,\n(d) In the case of a perso n who, despite the knowledge that\nany one is going to commit espionage, does not give\ninformation thereof to the Government of Nepal, a\nsentence of imprisonment for a term not exceeding one\nyear and a fine of one hundred thousand rupees.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"57","title":"Prohibition of assault on President","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall assassinate\nor attempt to assassinate the President of Nepal.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"No person shall, in any manner, abduct, or cause to be\nabducted, the President of Nepal or take, or cause to be taken, him or\nher hostage.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"No person shall, in any manner, assault, or cause to be\nassaulted, the President of Nepal.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"A person who commits any offence referred to in this\nSection shall be liable to punishment as follows:\n(a) In the case of the offence referred to in sub-\nsection (1), a sentence of imprisonment for life,\n(b) In the case of the offence referred to in sub-\nsection (2), a sentence of imprisonment for a term\nranging from ten to fifteen years,\n(c) In the case of the offence referred to in sub-\nsection (3), a sentence of imprisonment for a term\nranging from five to ten years.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"58","title":"Prohibition of intimidation of President or Parliament","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No\nperson shall intimidate, whether by using any kind of force or not,\nshow fear or terror to, or otherwise overawe the President or\nParliament of Nepal with intent to prevent or restrain the President or\nParliament of Nepal from performing any of the functions required\nto be performed pursuant to the Constitution or law or compel the\nPresident or Parliament of Nepal to perform the functions in any\nspecific manner.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) shall be liable to a sentence of\nimprisonment for a term not exceeding seven years or a fine not\nexceeding seventy thousand rupees or with both.\nExplanation: For the purposes of this Section, the term\n\"Parliament\" means the Federal Parliament and the State Assembly\nunder the Constitution of Nepal, and this term also includes the\nLegislature-Parliament.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"59","title":"Statute of limitation","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No s tatute of limitation shall apply to a\ncomplaint with regard to any of the offences under Sections 49, 50,\n51 52, 53 and 57.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"In the case of the offences under the Sections of this\nChapter, except those Sections set forth in sub -section (1), no\ncomplaint shall be entertained after the expiry of two years of the\ndate of knowledge of the commission of the offence.","children":[]}]}]},{"tier":1,"nodeType":"chapter","identifier":"Chapter-2","title":null,"content":"Offences against Public Tranquility","children":[{"tier":2,"nodeType":"rule","identifier":"60","title":"Prohibition of unlawful assembly","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall be engaged\nin an unlawful assembly.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"An assembly of five or more persons with the objective\nof doing any of the following acts shall be considered to be an\nunlawful assembly:\n(a) By means of force or show of force or show of a\ndeadly weapon:","children":[]},{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"to prevent any public servant from\nexercising the lawful functions or duties,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"to take or obtain possession of anyone’s\nproperty,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"to deprive any person of the enjoyment of\nthe right of way, use of water, public\ntransport or communication or similar\nother utilities,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"to compel any person to do what he or she\nis not legally bound to do or to omit to do\nwhat he or she is legally entitled to do.\n(b) To hinder, resist the execution of any law, or of any\nlegal process,\n(c) To commit any offence punishable by a sentence of\nimprisonment.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"Any pe rson who, with the knowledge that it is an\nunlawful assembly, joins the assembly shall be liable to a sentence of\nimprisonment for a term not exceeding six months and a fine not\nexceeding five thousand rupees where he or she has joined it without\narms, and imprisonment for a term not exceeding one year and a fine\nnot exceeding ten thousand rupees where he or she has joined it with\narms.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"Any person who himself or herself does not join an\nunlawful assembly but hires or otherwise induces or overawes\nanother to join such assembly shall be liable to the sentence referred\nto in sub-section (3) as if he or she himself or herself had joined such\nunlawful assembly.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"61","title":"Prohibition of breach of order issued to prevent or disperse","content":"unlawful assembly: (1) Where a com petent authority makes an\norder to prevent or disperse an unlawful assembly, no person shall\nparticipate or continue in such assembly.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who continues in, participates in, or joins an\nunlawful assembly under sub-section (1) shall be liable to a sentence\nof imprisonment for a term not exceeding one year or a fine not\nexceeding ten thousand rupees or with both.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"62","title":"Every member to be considered to have committed offence","content":"Where any member of an unlawful assembly commits any offence in\nthe achievemen t of the object of such assembly, every member of\nsuch assembly who aids and assists knowingly at the time of the\ncommission of offence shall be considered to have committed the\noffence.","children":[]},{"tier":2,"nodeType":"rule","identifier":"63","title":"Prohibition of rioting","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall commit, or cause to b e\ncommitted, the offence of rioting.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"Where an unlawful assembly or a member thereof uses\nforce or destroys, damages or causes loss to any public or private\nproperty in the course of achievement of the object of such assembly,\nevery member of such assem bly shall be considered to have\ncommitted the offence of rioting.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"Every person who commits the offense referred to in\nsub-section (1) shall be liable to a sentence of imprisonment for a\nterm not exceeding two years and a fine not exceeding twenty\nthousand rupees if he or she is armed with a deadly weapon, and to a\nsentence of imprisonment for a term not exceeding one year and a\nfine not exceeding ten thousand rupees if he or she is not armed with\na deadly weapon.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"64","title":"Prohibition of abetting rioting","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall, with intent to\ncause the commission of rioting or with the knowledge that rioting is\nlikely to be committed, abet the commission of rioting by another\nperson.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who abets under sub-section (1) shall be liable\nto a sentence of imprisonment for a term not exceeding one year, if\nthe offence of rioting is committed, and to a sentence of\nimprisonment for a term not exceeding six months, if the offence of\nrioting is not committed, or to a fine not exceeding five thousand\nrupees or the both sentences.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"65","title":"Prohibition of acts prejudicial to public tranquility","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No\nperson, by words, either spoken or written or by signs or otherwise\nshall do any act which, on the ground of religion, color, caste, race,\ncommunity or language, is prej udicial to harmonious relationship\nbetween people s of different classes, regions or communities of\nNepal.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) shall be liable to a sentence of\nimprisonment for a te rm not exceeding one year and a fine not\nexceeding ten thousand rupees.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"A person who commits the offence referred to in sub-\nsection (1) in any shrine , deity place, place of worship or pray or in\nany assembly engaged in the performance of a religious or cultural\nfestival or ceremony shall be liable to an additional sentence of\nimprisonment for a term not exceeding one year, in addition to the\nsentence referred to in sub-section (2).","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"66","title":"Prohibition of obstructing public servant","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall\nobstruct or attempt to obstruct any public official in the discharg e of\nhis or her duty in endeavo ring to prevent or disperse an unlawful\nassembly or to suppress a riot.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or cause s to be committed, the\noffence referred to in sub-section (1) shall be liable to a sentence of\nimprisonment for a term not exceeding one year or a fine not\nexceeding ten thousand rupees or both sentences.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"67","title":"Prohibition of obstructing movement in public place","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No\nperson, by show of any kind of fear or terr or, shall close the\noperation of a public road, way, rope -way, cable -car, airport,\nrailway, water transportation route, post al and other public service,\nor obstruct, in any way, the movement of pedestrians, motor vehicles\nor animals by obstructing, in any way, a public road, way, rope-way,\ncable-car way, airport, railway or water transportation route or\nimpede or obstruct, in any way, any person in entering into any\npublic place except in accordance with the order of a competent\nauthority under a law.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committed, the\noffence under sub -section (1) shall be liable to a sentence of\nimprisonment for a term not exceeding three years or a fine not\nexceeding thirty thousand rupees or both the sentences.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"68","title":"Prohibition of obstructing public services","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall, by\nshow of any kind of fear or threat, close, or obstruct, in any way, the\noperation of public electricity, telecommunication or other public\nservices of similar nature or public service specified in law.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) shall be liable to a sentence of\nimprisonment for a term not exceeding three years or a fine not\nexceeding thirty thousand rupees.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"69","title":"Prohibition of violating curfew","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall knowingly\nviolate a curfew order imposed by a competent authority under law\nto prevent an unlawful assembly, riot or any other act that breaches\ntranquility.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits the offence referred to in sub-\nsection (1) sh all be liable to a sentence of imprisonment for a term\nnot exceeding one year or a fine not exceed ing ten thousand rupees\nor both the sentences.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"70","title":"Not to spread rumor","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall, with intent to breach\npublic tranquility , commit rioting or unde rmine or jeopardize the\nsovereignty, geographical or territorial integrity of Nepal or\nharmonious relation between different races, castes or communities,\nspread or propagate rumors or hold a procession with slogans, in a\nmanner to provoke any one.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"Any person who commits, or causes to be committed,\nthe offence referred to in sub-section (1) shall be liable to a sentence\nof imprisonment for a term not exceeding one year or a fine not\nexceeding ten thousand rupees or both the sentences.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"71","title":"Prohibition of providing house, land or vehicle for breaching","content":"peace: No person, knowingly or having a reasonable reason to know\nthat another person is going to breach public peace or commit\nrioting, shall provide his or her house, land, vehicle or arm to that\nother person.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"Any person who commits, or causes to be committed,\nthe offence referred to in sub-section (1) shall be liable to a sentence\nof imprisonment for a term not exceeding six months or a fine not\nexceeding five thousand rupees or both the sentences.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"72","title":"Prohibition of holding tourch procession in sensitive public area","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall, with intent to breach public peace, hold any\ntourch procession or assembly or procession carrying a fire or\ninflammable substance in any place specified as the sensi tive public\narea by order of the competent authority in view of the sovereignty,\ngeographical or territorial integrity, security of Nepal or pubic\ntranquility or decency.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits the offence referred to in sub-\nsection (1) shall be liable t o a sentence of imprisonment for a term\nnot exceeding six months or a fine not exceed ing five thousand\nrupees or both the sentences.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"73","title":"Prohibition of destroying or damaging essential commodities","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall, having committed any offence under t his Chapter,\ndestroy, damage or set on fire, or cause to be done so, any\ncommodity which is regarded as an essential commodity under the\nlaw or public or private property or disorder such commodity or\nproperty by himself or herself or cause it to be disord ered by another\nperson, steal such commodity or property or knowingly buy or sell,\nor cause to be bought or sold, any commodity obtained by theft.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits the offence referred to in sub-\nsection (1) shall be liable to an additional sentence of imprisonment\nfor a term not exceeding one year or a fine not exceeding ten\nthousand rupees or both the sentences, in addition to the sentence\nimposable for any offence referred to in this Chapter.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"Where such commodity or property has already been\ndestroyed or damaged from the offence referred to in sub-section (1),\na compensation equal to the claimed amount shall also be recovered\nfrom such person.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"Where the person who has committed the offence\nreferred to in sub-section (1) is identified, such person, and where\nsuch person is not so identified, the person who induces or orders the\ncommission of such act shall be considered to have committed the\noffence.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"74","title":"Statute of limitation","content":"No complaint on an offence under this\nChapter shall lie after th e lapse of three months from the date of\ncommission of such offence.","children":[]}]},{"tier":1,"nodeType":"chapter","identifier":"Chapter-3","title":null,"content":"Offences Relating to Contempt of Authority of Public Servants","children":[{"tier":2,"nodeType":"rule","identifier":"75","title":"Prohibition of obstructing the service of summons, process etc","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall obstru ct in or object to, or cause to be done so,\nthe service of a summons, process, arrest warrant, notice or order\nissued under a law or the making of search, seizure , survey,\nmeasurement or public inquiry or arresting any person in pursuance\nof a warrant.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits the offence referred to in sub-\nsection (1) shall be liable to a sentence of imprisonment for a term\nnot exceeding six months or a fine not exceed ing five thousand\nrupees or both the sentences.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"Where a public servant commits the of fence referred to\nin sub-section (1), he or she shall be liable to an additional sentence\nof imprisonment for a term not exceeding three months.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"76","title":"Prohibition of refusing to receive and returning summons,","content":"process, notice or order: (1) Where a person in w hose name a\nsummons, process, notice, arrest warrant or order has been issued\nunder law is tendered for the service thereof on him or her, such\nperson shall, with mala fide intention, not refuse to receive, and\nreturn, such summons, process, notice or arrest warrant.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits the offence referred to in sub-\nsection (1) shall be liable to a sentence of imprisonment for a term\nnot exceeding three months or a fine not exceed ing five thousand\nrupees or both the sentences.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"77","title":"Prohibition of absc onding to avoid service of summons, process,","content":"notice or order: (1) No person, being legally bound to receive a\nsummons, process, notice, arrest warrant or order issued by the\ncompetent authority, shall abscond, with mala fide intention to avoid\nbeing served with such summons, process, notice, arrest warrant or\norder.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits the offence referred to in sub-\nsection (1) shall be liable to a sentence of imprisonment for a term\nnot exceeding three months or a fine not exceed ing five thousand\nrupees or both the sentences.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"78","title":"Prohibition of tearing out or removing summons, process etc","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall, with mala fide intention, tear out or remove a\nsummons, process, arrest warrant, notice or order affixed to a place\nin accordance with law, until its purpose is served.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) shall be liable to a sentence of\nimprisonment for a term not exceeding six months or a fine not\nexceeding five thousand rupees or both the sentences.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"79","title":"Prohibition of serving process in a false manner","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person\nwho is legally bound to serve, or cause to be served, a process shall\nserve the process in a false manner.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits the offence referred to in sub-\nsection (1) shall be liable to a sentence of imprisonment for a term\nnot exceeding one year or a fine not exceeding ten thousand rupees\nor both the sentences.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"80","title":"Prohibition of omission to produce document","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person who\nis legally bound to produce or deliver up any document to any office,\ncourt or public servant under law shall omit so to produce or deliver\nup such document.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits the offence referred to in sub-\nsection (1) shall be liable to a sentence of imprisonment for a term\nnot excee ding six months or a fine not exceeding five thousand\nrupees or both the sentences.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"81","title":"Prohibition of making false statement by person under oath","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"A person who is bound by law or by an oath to state the truth on any\nsubject to any competent authority or is a public office holder upon\ntaking oath under law shall not, in that capacity, state any false\nstatement.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits the offence referred to in sub-\nsection (1) shall be liable to a sentence of imprisonment for a term\nnot exceeding two years or a fine not exceeding twenty thousand\nrupees or both the sentences.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"82","title":"Prohibition of refusing oath","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person who is present before\nthe competent authority to state the truth on any subject shall refuse\nto take an oath to state the truth on s uch subject when so required to\ntake such oath.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits the offence referred to in sub-\nsection (1) shall be liable to a sentence of imprisonment for a term\nnot exceeding three months or a fine not exceeding five thousand\nrupees or both the sentences.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"83","title":"Prohibition of refusing to answer","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person who is under a\nlegal duty to state the truth on any subject to a competent authority\nshall refuse to answer any question demanded of him or her on such\nsubject by such authority.\nProvided that no person shall be compelled to testify against\nhimself or herself.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits the offence referred to in sub-\nsection (1) shall be liable to a sentence of imprisonment for a term\nnot exceeding six months or a fine not exceeding five thous and\nrupees or both the sentences.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"84","title":"Prohibition of giving false information","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall give\nany false information to any one, with intent to prevent any public\nservant from doing any act which he or she is bound by law to do or\nto cause such public servant to do anything which he or she need not\nor ought not to do.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits the offence referred to in sub-\nsection (1) shall be liable to a sentence of imprisonment for a term\nnot exceeding one year or a fine not exceeding ten thousand rupees\nor both the sentences.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"85","title":"Prohibition of obstructing","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall , by way of\nintimidation or force or in any other way , obstruct or hinder any\npublic servant, who is discharging his or her public duties, in the\ndischarge of such duties.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"No person shall knowingly obstruct or hinder the\nprocess of forfeiture, collection of records, withholding, auction or\nsale of any property being carried out in accordance with law.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"A person who commits the offence referred to in sub-\nsection (1) or (2) shall be liable to a sentence of imprisonment for a\nterm not exceeding one year or a fine not exceeding ten thousand\nrupees or both the sentences.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"86","title":"Prohibition of refusing to render assistance to public servant","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person under a legal duty t o render assistance to a public servant\nin the execution of his or her public duty shall refuse to so render\nsuch assistance.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits the offence referred to in sub-\nsection (1) shall be liable to a sentence of imprisonment for a term\nnot e xceeding six months or a fine not exceeding five thousand\nrupees or both the sentences.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"87","title":"Prohibition of disobedience to order","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall disobey\nan order made by a competent authority in accordance with law, by\nomitting to do anything ought to be done under law or doing\nanything prohibited by law.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits the offence referred to in sub-\nsection (1) shall be liable to a sentence of imprisonment for a term\nnot exceeding six months or a fine not exceeding five thousand\nrupees or both the sentences.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"88","title":"Statute of limitation","content":"No complaint shall lie after the lapse of three\nmonths from the date of knowledge of the commission of any\noffence under Section 78, 80 or 83 and from the date of the\ncommission of any offence under the other Sections of this Chapter.\nChpater-4\nOffences against Public Justice","children":[]},{"tier":2,"nodeType":"rule","identifier":"89","title":"Prohibition of fabricating evidence","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"Except as otherwise\nprovided in this Act, no person shall fabricate evidence, cause any\ncircumstance to exist, forge any document or electroni c record or\nmake any false entry in any document or electronic record, with\nintent to use it in a judicial or other legal proceeding.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) shall be liable to a se ntence of\nimprisonment for a term not exceeding five years and a fine not\nexceeding fifty thousand rupees.\nProvided that where a sentence of imprisonment for life has\nbeen imposed on any person on the basis of such false evidence, the\noffender shall be liable to a sentence of imprisonment for a term not\nexceeding seven years and a fine not exceeding seventy thousand\nrupees.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"Notwithstanding anything contained elsewhere in this\nSection, no sentence shall be so imposed under this Section that the\nsentence is in excess of the maximum sentence that can be imposed\non the offence in relation to which the evidence has been fabricated.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"90","title":"Prohibition of making or issuing false certificate","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person\nwith authority or duty under law to submit, certify, a uthenticate or\nissue a certificate or submit an affidavit in relation to any matter\nshall submit, certify, authenticate or issue such certificate or submit\nsuch affidavit, knowingly setting down a false statement in such\ncertificate or affidavit.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) shall be liable to a sentence of\nimprisonment for a term not exceeding two years and a fine not\nexceeding twenty thousand rupees.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"91","title":"Prohibition of using false evidence or certificate","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person\nshall, knowing that any evidence or certificate is false, use, or cause\nto be used, as true such false evidence or certificate.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) shall be liable to a sentence of\nimprisonment for a term not exceeding three years and a fine not\nexceeding thirty thousand rupees.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"92","title":"Prohibition of destroying document","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person who is under a\nlegal duty to produce any document or electronic record as evidence\nin a judicial or other legal proceeding shall knowingly destroy,\nobliterate, render illegible such document or record, or otherwise\nmake it incapable of being used as evidence.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) shall be liable to a sentence of\nimprisonment for a term not exceeding two years and a fine not\nexceeding twenty thousand rupees.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"No person shall, in contravention of law, knowingly\ndestroy, obliterate, render illegible any document or electronic record\nproduced in any judicial or other legal proceeding or otherwise\nmaking such document or record incapable of being used as evidence\nor cause it to disappear illegally or give it to another person in an\nunauthorized manner.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (3) shall be liable to a sentence of\nimprisonment for a term not exceeding four years and a fine not\nexceeding forty thousand rupees.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"If a public servant commi ts the offence referred to in\nsub-section (1) or (3), he or she shall be liable to double the sentence\nreferred to in that sub-section.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"93","title":"Prohibition of concealing evidence of offence","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall,\nwith intent to protect any offender, conceal or destroy any evidence\nrelating to the offense committed by the offender or render it\nineligible to be used as evidence.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) shall be liable to a sentence of\nimprisonment for a term not exceeding three years and a fine not\nexceeding thirty thousand rupees.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"94","title":"Prohibition of obstructing the giving of information","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No\nperson shall restraint or otherwise obstruct or hinder a person who,\nupon knowing that an offence ha s been committed or is about to be\ncommitted, intends to give information or notice about such offence\nto the police or competent authority.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) shall be liable to a sentence of\nimprisonment for a term not exceeding two years or a fine not\nexceeding twenty thousand rupees or both the sentences.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"95","title":"Prohibition of harboring offender","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall knowingly\nharbor an offender with intent to prevent him or her fr om being\napprehended or save him or her from a lawful sentence.\nExplanation: For the purposes of this Section, the term\n“offender” means a person who is suspected or accused of an offence\nor convicted by a court of such offence.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or cause s to be committed, the\noffence referred to in sub-section (1) shall be liable to the sentence as\nfollows:\n(a) Sentence of imprisonment for a term not exceeding five\nyears and a fine not exceeding fifty thousand rupees\nwhere that person has harb ored the offender of an\noffence punishable by imprisonment for life or\nimprisonment for a term not exceeding twenty years,\n(b) Sentence of imprisonment for a term not exceeding\nthree years and a fine not exceeding thirty thousand\nrupees where that person h as harbored the offender of\nan offence punishable by imprisonment for a term not\nexceeding ten years,\n(c) Sentence of imprisonment or fine not exceeding one\nfourth of the maximum term of imprisonment or amount\nof fine or both the sentences imposable for th e offence\nwhere that person has harbored the offender of the\noffence other than that mentioned in clause (a) or (b).","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"Notwithstanding anything contained in sub -section (1),\nno offence referred to in this Section shall be considered to have\nbeen commit ted where the offender's husband or wife or father,\nmother, son, daughter, elder brother, younger brother, elder sister,\nyounger sister, grand -father, grand -mother, grand -son, grand -\ndaughter, mother -in-law, father -in-law, daughter -in-law or son -in-\nlaw has harbored the offender.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"96","title":"Obligation to give information of commission of offence","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No\nperson under a legal duty to give information regarding any offence\nshall, knowing that such offence has been or is going to be\ncommitted, omit to give information o f such offence or no person\nwho knows the commission of any offence shall intentionally give\nfalse information about that offence.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) shall be liable to a sentence of\nimprisonment for a term not exceeding two years or a fine not\nexceeding twenty thousand rupees or both the sentences.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"97","title":"Prohibition of concealment of property or fraudulent claim to","content":"property: (1) No person shall fraudulently conceal, transfer or\ndeliver to any person, or caused to be concealed, transferred or\ndelivered, any property, or right in such property, wh ich is liable to\nbe forfeited, withheld, auctioned , sold or enforced or inventory of\nwhich is to be taken pursuant to a decision of a court o r competent\nauthority, intending thereby to prevent that property or right from\nbeing so forfeited, withheld, auctioned, sold or enforced or make a\nclaim to such property or right therein.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) shall be liable to a sentence of\nimprisonment for a term not exceeding two years or a fine not\nexceeding twenty thousand rupees or both the sentences.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"98","title":"Prohibition of making false complaint","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall, with\nintent to injure or annoy any person, make a false claim or accusation\nor give false in formation against such person before or to an\nauthority making judicial proceeding.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) shall be liable half the\nmaximum sentence imposable for the offence in respect of which\nsuch false accusation has been made.\nProvided that the provision of this Section shall not apply to\nany case in which the Government of Nepal is plaintiff.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"Where the offence referred to in sub-section (1) has\nresulted in any kind of harm or loss to a person who is a victim of\nsuch offence, compensation for such harm or loss shall be recovered\nfrom the offender to the victim.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"99","title":"Prohibition of making investigation or prosecution maliciously","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No authority responsible by law for making investigation or\nprosecution shall make investigation or prosecution maliciously,\nwith intent to have an innocent person bear liability or to save the\nreal offender.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) shall be liable to a sentence of\nimprisonment for a term not exceeding six months or a fine not\nexceeding five thousand rupees or both the sentences.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"Where any person suffers any kind of harm or loss from\nthe offence referred to in sub-section (1), he or she shall be entitled\nto get compensation from such offender.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"100","title":"Prohibition of failure to appear in violation of terms and","content":"conditions of guarantee: (1) No person wh o has been charged with\nan offence and released on guarantee shall fail, without a reasonable\ncause, to appear in the office or court to which guarantee is given in\naccordance with the terms and conditions of such guarantee.\nExplanation: For the purpose of this S ection, “guarantee ”\nmeans cash, bank guarantee or personal guarantee.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits the offence referred to in sub-\nsection (1) shall be liable to a sentence of imprisonment for a term\nnot exceeding one year or a fine not excee ding ten tho usand rupees\nor both the sentences.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"Where a person who fails to so appear under this\nSection is convicted of the offence with which he or she has been\ncharged shall be liable to the additional sentence under this Section,\nin addition to the sentence imposable on him or her for such offence.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"Where a person who is released on personal guarantee\nin accordance with law fails to appear in the office or court in\naccordance with such guarantee, the person giving such guarantee\nshall be liable to a sentence of fine not exceeding fifty thousand\nrupees.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"A person who has been sentenced under this Section\nshall not be eligible to become a surety without security until three\nyears.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"101","title":"Prohibition of obstructing apprehension or escaping from","content":"custody: (1) No person for whose apprehension an arrest warrant has\nbeen issued shall knowingly make any obstruction, by using force, in\nthe course of apprehension or to the apprehension of himself or\nherself or to escape from apprehension if already apprehended or no\nperson who is lawfully detained in custody shall escape or attempt to\nescape from such custody.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) shall be liable to a sentence of\nimprisonment for a term not excee ding three years or a fine not\nexceeding thirty thousand rupees or both the sentences.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"102","title":"Prohibition of obstructing apprehension or rescuing from","content":"custody: (1) No person shall intentionally make obstruction in the\ncourse of apprehension of or to the appr ehension of any other person\nfor whose apprehension an arrest warrant has been issued in\naccordance with law or rescue such other person from apprehension\nif already apprehended or intentionally escape or aid in the escape of\na person who is lawfully detained in custody from such custody.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) shall be liable to a sentence of\nimprisonment for a term not exceeding three years or a fine not\nexceeding thirty thousand rupees or both the sentences.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"If any public servant commits or causes to be committed\nthe offence referred to in sub-section (1), he or she shall be liable to\ndouble the sentence specified in sub-section (2).","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"103","title":"Statute of limitation","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"There shall be no statute of limitation for\nmaking a complaint in relation to any of the offences referred to in\nSection 101 or 102.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"No complaint shall lie after the lapse of three months\nfrom the date of commission of the offence under Section 100 and\nfrom the date of knowledge of the commission of any of the other\noffences under this Chapter.","children":[]}]}]},{"tier":1,"nodeType":"chapter","identifier":"Chapter-5","title":null,"content":"Offences against Public Interest, Health, Safety,\nConvenience and Morals","children":[{"tier":2,"nodeType":"rule","identifier":"104","title":"Prohibition of spreading infectious disease","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall do\nany a ct that spreads or is likely to spread any kind of infectious\ndisease which is dangerous to life of any one.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) shall be liable to a sentence of\nimprisonment for a term not exceeding ten years and a fine not\nexceeding one hundred thousand rupees, if the offence has been\ncommitted intentionally or knowingly, to a sentence of imprisonment\nfor a term not exceeding five years and a fine not exceeding fifty\nthousand rupees, if the offence has been committed recklessly, and to\na sentence of imprisonment for a term not exceeding three years and\na fine not exceeding thirty thousand rupees, if the offence has been\ncommitted negligently.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"105","title":"Prohibition of transmitting human immuno-deficiency virus","content":"(HIV positive): (1) No person, knowing that his or her own body or\nany other's body contains human immuno -deficiency virus (HIV\npositive) or the virus of Hepatitis B, shall with intent to transmit such\ndisease to another person, do nate his or her blood to such person or\ncause the donation of such other person's blood or have sexual\nintercourse with any one without taking any kind of precaution or\ntransfuse in any way his or her or such person's blood, semen, saliva,\nsputum or human organ into other's body.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) shall be liable to a sentence of\nimprisonment for a term not exceeding ten years and a fine not\nexceeding one hundred thousand rupees.\nProvided that where such disease has got transmitted with\nnegligence or recklessness, failing any intent to transmit it, the\noffender shall be liable to a sentence of imprisonment for a term not\nexceeding three years and a fine not exceeding thirty thousa nd\nrupees.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"Where the victim himself or herself has solicited and\nestablished sexual intercourse with a person having the human\nimmuno-deficiency virus or the virus of Hepatitis B, the person\nhaving the infection of such virus shall not be considered to have\ncommitted the offence referred to in this Section.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"106","title":"Prohibition of violating law relating to communicable disease","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall violate any rule, directive or order relating to\ncommunicable diseases issued by the Government of Nepal , Sta te\nGovernment or Local Level or the competent authority under law.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) shall be liable to a sentence of\nimprisonment for a term not exceeding six months or a fine n ot\nexceeding five thousand rupees or both the sentences.\nProvided that where any violation of such rule, directive or\norder is likely to cause the death of a person, the offender shall be\nliable to the sentence under Section 104.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"107","title":"Prohibition of adul teration of food","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall produce\nany food or drink to be consumed by the public by mixing into it any\ninjurious substance that is inedible, undrinkable or inconsumable or\nany substance that is edible, drinkable or consumable but\nsubstandard or any injurious chemical substance, or sell or distribute\nit or sell or distribute any food of which expiry date has expired or\nwhich is adulterated or sell, distribute, import or offer for sale or\ndistribution any food of standard falling short of the pres cribed\nstandard or inedible substance.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"Any person who commits, or causes to be committed,\nthe offence referred to in sub-section (1) shall be liable to a sentence\nof imprisonment for a term not exceeding five years and a fine not\nexceeding fifty thousand rupees.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"108","title":"Prohibition of selling, distributing food by misrepresentation","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall sell or distribute any food, lying or misrepresenting\nthat it is a different food or that a food which is of low quality or\ninedible is a food of high qua lity, or mixing any food substance of\nlow standard or inedible food substance into any food substance of\nhigh quality","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) shall be liable to a sentence of\nimprisonment for a term not exceeding five years or a fine not\nexceeding fifty thousand rupees or both the sentences.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"109","title":"Prohibition of selling or distributing goods by misrepresentation","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall sell any low quality good, except food, by\nmisrepresenting that such good is original one or any good by\ncausing to believe that it is a different good or any good so\nadulterated as to degrade its quality or change a label on any good or\nsell any good of which the date of expiry has expired.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) shall be liable to a sentence of\nimprisonment for a term not exceeding three years or a fine not\nexceeding thirty thousand rupees or both the sentences.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"110","title":"Prohibition of hoarding consumable goods intended for sale","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall increase the price of any consumable goods by\ncreating an artificial shortage of such goods in the market or sell, or\ncause to be sold, such goods at higher price or dump, store or hoard\nsuch goods by refraining from selling such goods with the motive of\nmaking undue profit from the sale of such goods.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) shall be liable to a sentence of\nimprisonment for a term not exceeding five years and a fine not\nexceeding fifty thousand rupees.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"111","title":"Prohibition of fouling water","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall foul the water to\nbe consumed by the public or the water of any public spring so as to\nrender it unfit for drinking or fou l the water to be used for any\npurpose other than drinking so as to render it unfit for that purpose.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) shall be liable to the sentence as\nfollows:\n(a) Imprisonment for a term not exceeding three years or a\nfine not exceeding thirty thousand rupees or both the\nsentences, in the case of a person who fouls, or causes\nto be fouled, drinking water or its spring,\n(b) Imprisonment for a term not exceeding six months or a\nfine not exceeding five thousand rupees or both the\nsentences, in the case of a person who fouls, or causes\nto be fouled, water to be used for other purpose.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"112","title":"Prohibition of polluting environment","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall\ngenerate, transmit, release or stockpile wastages in such a manner as\nto cause significant adverse impact on the environment.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"No person shall cause pollution in such a manner as to\ncause injury to public health or danger to body or life of the public,\nor generate, transmit, emit or stockpile, sound, heat or radioactive\nwave or hazardous waste, as the case may be, from a mechanical\ndevice.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) shall be liable to a sentence of\nimprisonment fo r a term not exceeding one year or a fine not\nexceeding ten thousand rupees or both the sentences.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (2) shall be liable to a sentence of\nimprisonment for a term not exceeding five years or a fine not\nexceeding fifty thousand rupees or both the sentences.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"113","title":"Prohibition of causing danger or obstruction in public way, river","content":"or place: (1) No person shall, by doing any act or by omitting to take\norder with or maintain any property of him or her or under his or her\ncontrol or charge, cause danger, obstruction or hindrance to any one\nin any public way, river or other public place.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) shall be liable to a sentence of a\nfine not exceeding twenty-five thousand rupees.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"114","title":"Prohibition of reckless conduct in using toxic or explosive","content":"substance: (1) No person shall do, in the operation or with the use of\nany explosive substance or fire or inflammable substance, explosive\nsubstance or deadly weapon or machine, any act so recklessly as to\nendanger or to be likely to cause injury to human body or life or\nknowingly or recklessly omit to make such arrangement with such\nsubstance of him or her or under his or her possession or charge as is\nnecessary to prevent any probable danger to human life.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) shall be liable to a sentence of\nimprisonment for a term not exceeding one year or a fine not\nexceeding ten thousand rupees or both the sentences.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"115","title":"Prohibition of recklessness conduct with respect to constructing,","content":"demolishing or repairing buildings: (1) No person shall, in\nconstructing, demolishing or repair ing a building, knowingly or\nrecklessly omits to take such arrangement with that building as is\nnecessary to guard against or prevent any probable danger to cause\ndeath of or grievous hurt to any one from such act or from the fall or\ncollapse of that building or any part thereof.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) shall be liable to a sentence of\nimprisonment for a term not exceeding one year or a fine not\nexceeding ten thousand rupees or both the sentences.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"116","title":"Prohibition of reckless conduct with respect to animals and","content":"birds: (1) No person shall, in keeping or caring and cultivating any\nviolent or other animal or bird of him or her or under his or her\ncontrol or custody, knowingly or recklessly omits to take such\nprecautionary measure with that animal or bird as is necessary to\nguard against or prevent any probable danger to cause death of or\ngrievous hurt to any one from such act or from such animal or bird.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes t o be committed, the\noffence referred to in sub-section (1) shall be liable to a sentence of\nimprisonment for a term not exceeding one year or a fine not\nexceeding ten thousand rupees or both the sentences.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"117","title":"Prohibition of setting animal free","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No pe rson shall set any\nanimal or bird of him or her or under his or her custody or control\nfree to other's house or land, public road or way or public place.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) shall be liable to a sentence of\nimprisonment for a term not exceeding one year or a fine not\nexceeding ten thousand rupees or both the sentences.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"118","title":"Prohibition of indecent conduct","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall enter into a\npublic place or any place where he or she ha s no legal right to enter\ninto and behave any one indecently or manhandle or annoy any\nwoman, child or person with physical disability in any public place\nor attempt to do such act.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) shall be liable to a sentence of\nimprisonment for a term not exceeding one year or a fine not\nexceeding ten thousand rupees or both the sentences.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"119","title":"Prohibition of soliciting prostitution","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person sh all solicit\nprostitution.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) shall be liable to a sentence of\nimprisonment for a term not exceeding three years and a fine not\nexceeding thirty thousand rupees.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"120","title":"Prohibition of providin g house, land to be used for prostitution","content":"or sexual intercourse with prostitute: (1) No person shall\nknowingly provide his or her house, land or means of transport for\nthe purpose of prostitution or having sexual intercourse with a\nprostitute.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits the offence referred to in sub-\nsection (1) shall be liable to a sentence of imprisonment for a term\nnot exceeding six months or a fine not exceeding five thousand\nrupees or both the sentences.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"121","title":"Prohibition of producing or selling obscene b ooks, pamphlets","content":"etc: (1) No person shall commit any of the following act s, including\nproducing any obscene book, pamphlet publicly:\n(a) Producing, printing or publishing or circulating through\nelectronic media any obscene book, pamphlet, drawing,\nfilm, pic ture, record or any other item which is\nlascivious (increases physical libido) or appeals to the\nprurient interest or makes characterless,\n(b) Purchasing, selling, distributing or letting to hire or\npublicly exhibiting such obscene item or holding such\nitem with intent to do so,\n(c) Advertising that such obscene item is available from\nany person in this way,\n(d) Exporting or importing or holding such obscene item\nwith intent to sell, distribute it.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits the offence referred to in sub-\nsection (1) shall be liable to a sentence of imprisonment for a term\nnot exceeding one year or a fine not exceeding ten thousand rupees\nor both the sentences.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"Notwithstanding anything contained elsewhere in this\nSection, the provis ion of this Section shal l not apply to any work\nwhich is in the interest of, or which is of importance from the\nperspective of, science, education, art, literature, research or learning\nor which is kept or made for a religious purpose.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"122","title":"Prohibition of showing sexual organ in public place","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No\nperson above ten years of age shall, except for the purpose of\nmedical sciences or treatment, do any obscene act or conduct or\nshow his or her sexual organ or utter or make any obscene words or\ngesture to any one in a public place.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits the offence referred to in sub-\nsection (1) shall be liable to a sentence of imprisonment for a term\nnot exceeding six months or a fine not exceeding five thousand\nrupees or both the sentences.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"123","title":"Prohibition of having sexual interco urse in public place","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No\nperson shall have sexual intercourse with any one or any kind of\nunnatural sexual intercourse in a public place, or in any other place\nin a manner that such intercourse is visible to others.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits the offenc e referred to in sub-\nsection (1) shall be liable to a sentence of imprisonment for a term\nnot exceeding one year or a fine not exceeding ten thousand rupees\nor both the sentences.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"124","title":"Prohibition of committing public nuisance","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"Except as\notherwise provided in a law, no person shall do any act or omit to do\nany act legally required to be done, which causes any kind of harm,\ninjury, danger or annoyance to the public or to the people who dwell\nin the vicinity.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits the offence referred to in sub-\nsection (1) shall be liable to a sentence of fine not exceeding twenty -\nfive thousand rupees.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"125","title":"Prohibition of gambling or betting","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall gamble or\ncause gambling.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits the offence referred to in sub-\nsection (1) shall be liable to the sentence as follows:\n(a) Imprisonment for a term not exceeding three\nmonths or a fine not exceeding thirty thousand\nrupees, in the case of one who gambles or causes\nany one to gamble for the first time,\n(b) Imprisonment for a te rm not exceeding one year\nand a fine not exceeding fifty thousand rupees, in\nthe case of one who gambles or causes any one to\ngamble for the second time, and additional\nsentence of imprisonment for a term not\nexceeding three months and a fine not exceeding\nten thousand rupees for every subsequent offence.\nExplanation: For the purposes of this Act,-","children":[]},{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"\"gambling\" means a game or process of any type\nto be so played by betting as to gain, lose or win\nany kind of movable or immovable property or\nreturn, on the basis of contingency, and this term\nalso includes any betting or waging so made by\none who does not gamble himself or herself as to\ngain or lose any movable, immovable property or\nreturn depending on the win or loss of others.\nProvided that any of the f ollowing games\nor programs shall not be considered to be\ngambling:\n(a) A game so played, with the approval of the\nGovernment of Nepal, for entertainment in\na public ceremony, fair, feast, festival,\nexhibition or event that a small amount of\nmovable property is won or lost,\n(b) A lottery operated with the approval of the\nauthorized authority.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"\"one who causes any one to gamble \" means a\nperson who causes gambling by knowingly\nproviding a house, room, space or vehicle under\nhis or her ownership, possession , use or custody\nor by providing any kind of instrument for\ngambling.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"All instruments used for gambling and movable and\nimmovable properties earned from gambling shall be forfeited.\nProvided that a house, room, place or means of transport\nwhere gambling has taken place shall not be forfeited.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"No person shall bet or cause betting.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"For the purpose s of sub -section (4), a person who so\nbets that he or she will receive or lose any movable, immovable\nproperty or consideration if any particular par ty wins or loses any\ngame or process that can be played, or caused to be played, under\nlaw shall be considered to have committed the offence of betting.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(6)","title":null,"content":"In the event of commission of the offence referred to in\nsub-section (4), the offender shall be li able to a sentence of\nimprisonment for a term not exceeding one year and a fine not\nexceeding ten thousand rupees, along with the forfeiture of the\nclaimed amount used in the offence.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(7)","title":null,"content":"Convictions pronounced by a court shall be taken into\naccount for t he purpose of establishing recidivism in relation to the\noffence referred to in this Section.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"126","title":"Prohibition of soliciting alms (begging) or causing begging","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall solicit alms (begging) in a public place or use a child\nfor the purposes of begging under the pretense of singing, dancing,\nplaying or doing any act or use other person for purposes of begging,\nin return for any kind of money or wages paid by him or her to that\nother person, or abet begging.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits the offence referred to in sub-\nsection (1) shall be liable to the sentence as follows and the claimed\namount of begging shall also be forfeited:\n(a) I mprisonment for a term not exceeding one month or a\nfine not exceeding one thousand rupees, in the case of\nbegging for the first time, and imprisonment for a term\nnot exceeding two months or a fine not exceeding two\nthousand rupees for every instance, from the second\ninstance onwards,\n(b) Imprisonment for a term not exceeding one year or a\nfine not excee ding ten thousand rupees or both the\nsentences, in the case of causing begging for the first\ntime, and imprisonment for a term not exceeding three\nyears or a fine not exceeding thirty thousand rupees or\nboth the sentences for every instance, from the second\ninstance onwards.\nExplanation: For the purposes of this Section,-","children":[]},{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"begging by a sage, saint, hermit or monk visiting\nhome to home as per the tradition practiced from\ntime immemorial or begging in any religious or\ncultural work shall not be considered to be an\noffence under this Section,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"\"public place\" means any road, street, park, motor\nvehicle stop, government office or office\npremises, and this term also includes a means of\ntransport in public use.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"127","title":"Compensation to be paid","content":"Where any harm or loss is caused t o any\none or any property of any one from any of the offences referred to\nin Sections 104, 105, 106, 107, 108, 109, 110, 111, 113, 114, 115,\n116, 117, 118 and 124 of this Chapter, compensation shall be\nordered to be paid by the offender to the person who s o suffers such\nharm or loss.","children":[]},{"tier":2,"nodeType":"rule","identifier":"128","title":"Statute of limitation","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"In the case of any offence under this\nChapter which has caused the death of any one, there shall be no\nstatute of limitation for making a complaint in relation to such\noffence.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"No complaint shall lie after the expiry of three months\nafter the date of commission of any of the offences under Sections\n113,114, 115, 116, 117, 118, 119, 120, 121 and 122 and after the\nexpiry of six months from the date of knowledge of commission of\nany of the other offences under this Chapter.","children":[]}]}]},{"tier":1,"nodeType":"chapter","identifier":"Chapter-6","title":null,"content":"Offences Relating to Arms and Ammunitions","children":[{"tier":2,"nodeType":"rule","identifier":"129","title":"Prohibition of manufacturing arms without obtaining license","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall manufacture or repair arms and ammunition without\nobtaining a license or in a mann er to be contrary to the terms and\nrestrictions specified in the license, even if, obtained.\nExplanation: For the purposes of this Act,-\n(a) \"arms\" means a canon, mortar, tank, machine gun, rifle,\ngun, pistol, revolver or other device of similar nature to\nbe operated by using or not using ammunition , and this\nterm also includes spare parts of and machinery and\nequipment for manufacturing any arms,\n(b) \"machine gun\" means a brain gun, luis gun , stain gun,\nmachine, carbine, toms machine carbine, GMG, short\nmachine gun or automated arms of similar nature, and\nthis term also includes a machine, equipment for\nmanufacturing a machine gun, and spare parts thereof.\n(c) \"ammunition\" means gun powder, cape, bullet , shell ,\ndetonator, cartoos, fuse or other substance of similar\nnature to be placed in arms.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) shall be liable to a sentence of\nimprisonment for a term not exceeding ten years and a fine not\nexceeding one hundred thousand rupees, according to the gravity of\nthe risks of arms or ammunition in question.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"130","title":"Prohibition of transaction of arms without obtaining license","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall transact arms and ammunition without obtaining a\nlicense or in a manner to be contrary to the terms and restrictions\nspecified in the license, even if, obtained.\nExplanation: For the purposes of this Chapter, \"transaction\"\nmeans procurement, sale, transport, obtaining ownership, transfer,\naccumulating, stockpiling or collection, storage, export or import.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) shall be liable to a sentence of\nimprisonment for a term not exceeding seven years and a fine not\nexceeding seventy thousand rupees.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"131","title":"Prohibition of acquisition of specific type of arms","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person\nshall acquire the following arms, by way of procurement, sale,\ndonation, gift , reward, partition, succession or otherwise, retain,\nstockpile or store such arms, or use, transport, export or import such\narms except with the order of the competent authority:\n(a) A tank and ammunition thereof,\n(b) A cannon or mortar and ammunition thereof,\n(c) A machine gun and ammunition thereof,\n(d) Any kind of rifle and ammunition thereof,\n(e) Such other arms and ammunition thereof as specified by\nthe competent authority that such arms and ammunition\nare prohibited from being acquired or held by the\npublic.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who acquires any arms set forth in sub-section","children":[]},{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"shall, within thirty-five days from the date of acquisition thereof,\nsurrender such arms to the concerned District Administration Office.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) shall be liable to a sentence of\nimprisonment for a term n ot exceeding seven years and a fine not\nexceeding seventy thousand rupees.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"Notwithstanding anything contained elsewhere in this\nSection, nothing shall be deemed to bar any officer and personnel of\nthe Nepal Army, Nepal Police, Armed Police Force, Nepal\nconcerned with security work or other security personnel who are\nentitled to use arms lawfully from holding or using such arms in the\ncourse of discharging their respective duties.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"132","title":"Prohibition of retaining or carrying arms without license","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No\nperson shall acquire, retain, stockpile, use or carry such arms as may\nbe allowed by law to be acquired, held, stockpiled, used or car ried,\nwithout obtaining a license or in a manner to be contrary to the terms\nand restrictions specified in the license, even if, obtained.\nProvided that nothing shall bar any officer and personnel of\nthe Nepal Army, Nepal Police, Armed Police Force, Nepal\nconcerned with security work or other security personnel who are\nentitled to use arms lawfully from holding, using or carry ing such\narms in the course of discharging their respective duties.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) shall be liable to a sentence of\nimprisonment for a term not exceeding five years and a fi ne not\nexceeding fifty thousand rupees.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"133","title":"Obligation to maintain records of transaction of arms,","content":"ammunition: (1) A person who carries out transaction of arms or\nammunition by obtaining a license shall maintain separate records of\nthe arms and ammunition transacted by him or her.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"The records maintained pursuant to sub-section (1) shall\nset out, inter alia, the following matters:\n(a) Type, description and quantity of the arms\nprocured or sold, transported, stockpiled,\nexported or imported by him or her,\n(b) In the case of a sale of arms to any one, the\npurchaser’s name, surname, address, citizenship\nor passport number, date and place of issue of\ncitizenship certificate or passport,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"A person who carries out the transaction of arms or\nammunition sh all, when so asked, show the records referred to in\nsub-section (2) to the authority controlling or administering arms and\nammunition, the investigating authority or a court.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"Where any person other than one who carries out the\ncommercial transaction of arms or ammunition by obtaining a license\nintends to carry out the transaction of arms and ammunition, he or\nshe shall obtain approval of the concerned District Administration\nOffice to that effect.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"A person who does, or causes to be done, any act\ncontrary to sub-section (1), (3) or (4) shall be liable to a sentence of\nimprisonment for a term not exceeding two years and a fine not\nexceeding twenty thousand rupees.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"134","title":"Prohibition of production or transaction of nuclear, chemical,","content":"biological (bacteriological) or toxin weapons: (1) No person shall\nmanufacture, produce, procure, sell, acquire, own, transfer, stockpile,\nstore, transport, export or import, invest in or manage any type of\nnuclear, chemical, biological (bacteriological) or toxic weapons o r\ncause any one to do so.\nExplanation: For the purposes of this Section,-\n(a) \"chemical weapon\" means any chemical weapon as\ndefined by the Convention on the Prohibition of the\nDevelopment, Production, Stockpiling and Use of\nChemical Weapons and their Destruct ion, done at Paris\non 13 January 1993.\n(b) \"biological or toxin weapon\" means any biological\n(bacteriological) or toxin weapon as defined by the\nConvention on the Prohibition of the Development,\nProduction and Stockpiling of Bacteriological\n(Biological) and Toxin Weapons and their Destruction,\ndone at London, Moscow and Washington on 10 April,\n1972.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits the offence referred to in sub-\nsection (1) shall be liable to a sentence of imprisonment for a term\nnot exceeding twenty years and a fine not exceeding two hundred\nthousand rupees.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"135","title":"Forfeiture of movable, immovable property related to offence","content":"In\nthe event of the commission of any offence under this Chapter, the\narms and ammunition related to such offence, and machinery,\nequipment, instrument or vehicle producing, manufacturing,\nretaining or transporting such arms and proceeds of the sale and\npurchase of such arms or ammunition and amount accrued or\naccumulated therefrom shall be forfeited.\nProvided that where the owne r of the m eans of transport or\nmotor vehicle proves that he or she did not know the transportation\nof such arms and ammunition, such means of transport or vehicle\nshall not be forfeited.","children":[]},{"tier":2,"nodeType":"rule","identifier":"136","title":"Compensation caused to be paid","content":"Where any harm or loss is\ncaused to any o ne's body or property from the commission by any\nperson of any offence under this Chapter, a reasonable compensation\nfor such harm or loss shall be caused to be paid by the offender to the\nvictim.","children":[]},{"tier":2,"nodeType":"rule","identifier":"137","title":"Statute of limitation","content":"No complaint shall lie, in rela tion to an\noffence under Section 132, after the expiry of three months of the\ncommission of such offence, and in relation to any of the other\noffences under this Chapter, after the expiry of six months from the\ndate of knowledge of the commission of such offence.","children":[]}]},{"tier":1,"nodeType":"chapter","identifier":"Chapter-7","title":null,"content":"Offences Relating to Explosives","children":[{"tier":2,"nodeType":"rule","identifier":"138","title":"Prohibition of production of explosives","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall make,\nprepare or produce any kind of explosives without obtaining a\nlicense or in a manner to be contrary to the terms and restrictions\nspecified in the license, even if, obtained.\nExplanation: For the purposes of this Act:,-\n(a) \"explosives” means I.E.D., T.N.C. Amatol, Barotol,\nPentolite, rapid detonative explosive (RDX), tore fex,\nblastic explosives, dynamite, gun powder, nitroglyceri n,\ngelignite, stemite, selsite, detonator, blastic cap,\nelectronic blastic cap, fuse, fireworks, cracker, gun\ncotton, gun powder, ballistic powder, mercury or\nfullunet made of any other metal, any other explosive\nsubstance of similar nature, which is capa ble of\nexploding and causing loss, or any substance so\nspecified by the Government of Nepal by a notification\nin the Nepal Gazette, and this term also includes a\nbomb.\n(b) \"bomb\" means a grenade so made of any explosive or\nany means, formula, process or me asure as to self -\ndetonate or detonate with the help of other substance, or\nother object containing explosive or substance of similar\nnature.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) shall be liable to the following\nsentence:\n(a) Imprisonment for a term not exceeding ten years\nand a fine not exceeding one hundred thousand\nrupees, in the case of high explosives,\n(b) Imprisonment for a term not exceeding five years\nand a fine not exceeding fifty thousand r upees, in\nthe case of low explosives,\n(c) Imprisonment for a term not exceeding three\nyears and a fine not exceeding thirty thousand\nrupees, in the case of ordinary explosives,\n(d) Imprisonment for a term not exceeding two years\nand a fine not exceeding tw enty thousand rupees,\nin the case of a person who produces, uses,\nretains or otherwise transacts any equipment,\nmachinery or instrument for producing or\nmanufacturing explosives.\nExplanation: For the purposes of this Chapter,-","children":[]},{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"\"high explosives\" means dynam ite, nitroglycerin,\nTNC, gelignite mornqtarlab, mercury fullunet,\nR.D.X. amatol, barotol, pentolite, stemite,\nselsightal, blastic explosive bomb and other\nexplosive of similar nature.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"\"low explosives\" means blastic powder,\ngunpowder, gun cotton, mercury or fullunet made\nof any other metal and other explosive of similar\nnature.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"\"ordinary explosives\" means detonator, blastic\ncap, electronics blastic cap, fuse, firework,\ncracker and other explosives of similar nature.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"139","title":"Prohibition of transaction of explosives","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall\ntransact explosives without obtaining a license or in a manner to be\ncontrary to the terms and restrictions specified in the license, even if,\nobtained.\nExplanation: For the purposes of this Chapter, the term\n\"transaction\" means procurement, sale, retention, use, stockpiling,\nstorage, transport, alteration, mixing, export or import.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits the offence referred to in sub-\nsection (1) shall be liable to the following sentence:\n(a) Imprisonment for a term n ot exceeding ten years and a\nfine not exceeding one hundred thousand rupees, in the\ncase of high explosives,\n(b) Imprisonment for a term not exceeding five years and a\nfine not exceeding fifty thousand rupees, in the case of\nlow explosives,\n(c) Imprisonment for a term not exceeding three years and a\nfine not exceeding thirty thousand rupees, in the case of\nordinary explosives.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"140","title":"Prohibition of making or using artificial explosives","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No\nperson shall alter or modify any ordinary consumable goods to be\nused or consumed by the public or physical or chemical characters of\nsuch goods, through any physical or chemical process, formula,\nmeasure or method or change the form, structure or shape thereof,\nand use or caused to be used, the same as a bomb of any type or any\nother explosives.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits the offence referred to in sub-\nsection (1) shall be liable to a sentence of imprisonment for a term\nnot exceeding three years or a fine not exceeding thirty thousand\nrupees or both the sentences.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"141","title":"Prohibition of making land mines or laying explosives","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No\nperson shall lay or place any explosive, any inflammable substance\nor making an electronic ambush in a public road or way, place,\nbuilding, bridge, tunnel or any other place for the public movemen t\nor cause obstruction to the movement or use of any other public\nutilities by placing such substance or making an ambush.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) shall be liable to a sentence of\nimprisonment for a term not exceeding ten years and a fine not\nexceeding one hundred thousand rupees.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"Where any injury or loss is caused to the body, life or\nproperty of any one from the commission of the offence referred to\nin sub-section (1), the sentence referred to in -sub-section (2) shall be\nadded to the sentence which is imposable by this Act on the offender\nfor such injury or loss.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"142","title":"Obligation to maintain records of production or transaction","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"A person who has obtained a licence for the p roduction or\ntransaction of explosives shall, in producing, manufacturing,\npreparing or transacting such explosives, maintain separate records\nof every production or transaction of every explosive.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"The records referred to in sub-section (1) shall set out,\ninter alia, the following matters:\n(a) Type, description and quantity of the explosives\nproduced, prepared or manufactured,\n(b) In the case of the transaction of explosives, the\npurpose for which such transaction has been made,\n(c) In the case of the sale and distribution of explosives,\nthe purchaser’s name, the purpose, and quantity of,\nsuch sale and distribution.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"A person who carries out the transaction of explosives\nshall, when so asked, show the records referred to in sub-section (1)\nto the competent authority controlling or administering explosives,\nthe investigating or prosecuting authority or the court.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"A person who does, or causes to be done, any act\ncontrary to this Section shall be liable to imprisonment for a term not\nexceeding three months or a fine not exceeding five thousand rupees\nor both the sentences.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"143","title":"Obligation to take care while importing, transporting or","content":"stockpiling explosives: (1) A person who licensed to carry out the\ntransaction of explosives shall, in using, carr ying, transporting or\nstockpiling such explosives, so use such explosives as to ensure\nadequate safety according to the nature of such explosives or carry,\ntransport or stockpile such explosives, having kept them in\nappropriate magazines.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person wh o does, or causes to be done, any act\ncontrary to sub-section (1) shall be liable to a fine not exceeding fifty\nthousand rupees.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"144","title":"Forfeiture of movable or immovable property relat ed to offence","content":"In the event of the commission of any offence referred to in this\nChapter, any explosives related to such offence, goods, equipment,\ninstrument or raw materials used for producing, preparing or\nmanufacturing such explosives, motor vehicle or means of transport\nused in the transportation or carriage of such explos ives and\nproceeds of the production, preparation, manufacturing or transaction\nof such explosives and amount accrued or accumulated therefrom\nshall be forfeited.\nProvided that where the owner of the motor vehicle or means\nof transport proves that he or s he did not know the transportation of\nthe explosives, such vehicle or means of transport shall not be\nforfeited.","children":[]},{"tier":2,"nodeType":"rule","identifier":"145","title":"Order for compensation to be paid","content":"Where any harm or loss is\ncaused to the life, or any property, of any one from the commission\nby a pers on of any of the offences under this Chapter, reasonable\ncompensation for such harm or loss shall be ordered to be paid by the\noffender to the victim.","children":[]},{"tier":2,"nodeType":"rule","identifier":"146","title":"Statute of limitation","content":"No complaint shall lie after the expiry of three\nmonths from the date of com mission of any of the offences under\nSection 143 and after the expiry of six months from the date of\nknowledge of commission of any of the other offences under this\nChapter.","children":[]}]},{"tier":1,"nodeType":"chapter","identifier":"Chapter-8","title":null,"content":"Offences against National and Public Heritages","children":[{"tier":2,"nodeType":"rule","identifier":"147","title":"Prohibition of owning public building, land by individual","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No\nperson shall, without prior approval of the Government of Nepal or\nState Government or Local Level, obtain ownership of the following\nbuilding or land, whether making its registration or not, or otherwise\noccupy, cultivate or encroach, or hinder or obstruct, in any way, the\npossession or use of, such building or land:\n(a) Any government building or land held in the name of\nthe Government of Nepal, State Government or Local\nLevel or a public body under the full o r majority\nownership or control of the Government of Nepal, State\nGovernment or Local Level,\n(b) Any community or public house or land which has been\nunder community or public possession and use from\ntime immemorial.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committed, an\noffence referred to in sub-section (1) shall be liable to imprisonment\nfor a term not exceeding three years or a fine not exceeding thirty\nthousand rupees or both the sentences.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"Where any building, land mentioned in sub -section (1)\nhas already been registered in, or transmitted to, the name of any\nindividual, such registration or transmission also shall, ipso facto, be\nvoid.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"148","title":"Prohibition of owning public heritage by individual","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No\nperson shall obtain the ownership of any public heritage, whether\nmaking its registration or not, or hinder or obstruct, in any way, the\npublic possession or use of, or otherwise occupy, cultivate or\nencroach such heritage, or cause harm, loss or damage to such\nheritage in any way.\nExplanation: For the purposes of this Section, the term\n“public heritage” means any of the following heritages:\n(a) A right of way that has been in public use from\ntime immemorial,\n(b) A road, pasture land, water body, graveyard,\ncrematory, water tap, spout, well, pond, edge of\npond, spring of drinking water, canal, water\nchannel, meadow for animal grazing or exit for\nanimals, that has been in the public use,\n(c) A place where market is held,\n(d) A divine place, shrine, temple, Stupa, monastery,\nmosque or church,\n(e) A public rest house, Pauwa, Sattal, Chautaro,\n(f) A historical statue, monument, cultural\nmonument or memorial,\n(g) A place for organizing religious or cultural\nfunctions or ceremonies,\n(h) A national forest designated by the Government\nof Nepal or forest, or any part thereof, under\nownership of the Government of Nepal, State\nGovernment or Local Level.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) shall be liable to a sentence of\nimprisonment for a term not exceeding five years or a fine not\nexceeding fifty thousand rupees or both the sentences.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"Where any public heritage referred to in sub -section (1)\nhas already been registered in, or transmitted to, the name of any\nindividual, such registration or transmission also shall, ipso facto, be\nvoid.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"149","title":"Prohibition of encroachment of natural heritages","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person\nshall, except in accordance with law, encroach or possess, in any\nway, any natural heritage, or sell or distribute such heritage, or cause\nany harm, loss or damage to its natural structur e or beauty, in any\nway.\nExplanation: For the purposes of this Section, the term\n“natural heritage” means any of the following heritages:\n(a) A national park, wildlife or hunting reserve designated\nby the Government of Nepal for the protection of the\nnatural environment, vegetation and wildlife,\n(b) A conservation area designated by the Government of\nNepal, river, rivulet, stream, lake, wetland or natural\nwater-fall, snow -peak or any part thereof, higher\nmountain peak,\n(c) A wildlife, vegetation or landscape protected by the law\nin force or the Government of Nepal, State Government\nor Local Level,\n(d) A habitat of wildlife protected by the Government of\nNepal, State Government or Local Level, eco-system, or\nany medicinal herb which is prohibited for sale,\ndistribution, export or import.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) shall be liable to a sentence of\nimprisonment for a term not exceeding ten years and a fine equal to\nthe claimed amount if such amount is spe cified and a fine not\nexceeding one million rupees if such amount is not specified or both\nthe sentences.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"150","title":"Prohibition of possession or destruction of public physical","content":"infrastructure in unauthorized manner : (1) No person shall,\nexcept in accordance with law, possess, in an unauthorized manner,\nany public physical infrastructure or prevent any one from using\nsuch infrastructure, or, cause any harm or loss to such infrastructure,\nin any way.\nExplanation: For the purposes of this Section, the term\n“public physical infrastructure” means the following infrastructure to\nbe publicly used:\n(a) A road, way, bridge, tunnel, airport,\n(b) A water reservoir, canal, spring of drinking water, and\npond, power house, electricity transmission center or\nline thereof,\n(c) A ropeway, cab le car, telecommunication equipment,\nradio station, television broadcasting center and tower\nthereof,\n(d) A rail and railway;\n(e) A public bus station, public park, or\n(f) Similar other structure.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) shall be liable to a sentence of\nimprisonment for a term not exceeding ten years and a fine not\nexceeding one hundred thousand rupees.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"151","title":"Prohibition of dishonoring or destroying national anthem, flag","content":"or coat-of-arms: (1) No person shall, with intention to spread hatred\nagainst Nepal or the Government of Nepal, dishonor the national\nanthem of Nepal, burn, or knowingly dishonor, the flag of Nepal, or\nuse such anthem, flag or coat-of-arms of Nepal at such place, on\nsuch object or condition as it is not appropriate for its use in view of\npublic morality, decency or courtesy.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) shall be liable to a sentence of\nimprisonment for a term not excee ding three years or a fine not\nexceeding thirty thousand rupees or both the sentences.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"No person shall, with intent to spread hatred against, or\ndishonor a country with which Nepal has friendly relation, burn or\nknowingly misuse such country's national flag or misuse such flag or\nthe coat-of-arms of such country or use such flag or coat-of-arms at\nsuch place, on such object or condition as it is not appropriate for its\nuse in view of public morality, decency or courtesy.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"No person shall, with in tent to make hatred against or dishonor the\nUnited Nations Organization or any organization associated with, or\nspecialized agency of, the United Nations Organization or any\ninternational or regional organization of which Nepal is a member,\nmisuse in any w ay the flag or emblem of such Organization, or use\nsuch flag or logo, motor vehicle or other object of such Organization\nwithout approval of such Organization.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (3) or (4) shall be liable to a\nsentence of imprisonment for a term not exceeding one year or a fine\nnot exceeding ten thousand rupees or both the sentences.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"152","title":"Not to insult national figures/heroes","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall\nknowingly make hatred against, dishonor or defame, any national\nfigure/hero specified by the Government of Nepal or demolish,\ncause loss or damage to the statue, monument or memorial of such\nfigure/hero.\nProvided that any comment made in good faith in the context\nof a study, research or evaluation of the life of such figure/hero shall\nnot be considered to be an offence referred to in this Section.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) shall be liable to a sentence of\nimprisonment for a term not exceeding six months or a fine not\nexceeding five thousand rupees or both the sentences.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"153","title":"Order for compensation to be paid","content":"Where any harm or loss is\ncaused from the commission of an y offence referred to in Section\n150, reasonable compensation for such harm or loss shall be ordered\nto be paid by the offender.","children":[]},{"tier":2,"nodeType":"rule","identifier":"154","title":"Statute of limitation","content":"There shall be no statute of limitation for\nfiling a complaint in relation to any of the offences under Sections\n147, 148 and 149, and no complaint shall l ie after the expiry of six\nmonths from the date of commission of any of the offences under the\nother Sections of this Chapter.","children":[]}]},{"tier":1,"nodeType":"chapter","identifier":"Chapter-9","title":null,"content":"Offences Relating to Religion","children":[{"tier":2,"nodeType":"rule","identifier":"155","title":"Prohibition of injuring shrines or places held sacred","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No\nperson shall damage or injure or, in any way, defile, destroy or\npollute any place of religious worship, pray or function or place,\nobject held sacred or burial place or place of sepulture or do similar\nother act with intent to outrage or insult the religion or religious\nfeelings of any caste, race, community or class or with the\nknowledge that such outrage or insult is likely to occur.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) shall be liable to a senten ce of\nimprisonment for a term not exceeding three years and a fine not\nexceeding thirty thousand rupees.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"Where a foreigner has committed, or caused to be\ncommitted, the offence referred to in sub-section (1), he or she shall\nbe deported from Nepal wit hin seven days after the date of\ncompletion of the service of imprisonment under sub-section (2).","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"156","title":"Prohibition of outraging religious feelings","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall\noutrage the religious feelings of any caste, race, community or class\nby words, either spoken or written, by visible representation or signs\nor otherwise.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) shall be liable to a sentence of\nimprisonment for a term not exceeding two years and a fine n ot\nexceeding twenty thousand rupees.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"157","title":"Prohibition of causing obstruction to religious rites and rituals","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall knowingly cause obstruction to other's religious\nrites and rituals that are handed down or being followed from the\ntime immemorial.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) shall be liable to a sentence of\nimprisonment for a term not exceeding one year or a fine not\nexceeding ten thousand rupees or both the sentences.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"158","title":"Prohibition of proselytizing","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall convert any one\nfrom one religion to another or make attempt to or abet such conversion.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"No person shall do any act or conduct which\nundermines the religion, opinion or faith of any caste, race,\ncommunity or convert any one into another religion, whether by\ninducement or not, in a manner to so undermine or propagate such\nreligion or opinion with the intention of making such conversion.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"A person who commits, or cause s to be committed, the\noffence referred to in sub-section (1) or (2) shall be liable to a\nsentence of imprisonment for a term not exceeding five years and a\nfine not exceeding fifty thousand rupees.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"If a foreigner commits, or causes to be committed, the\noffence referred to in sub-section (1) or (2), he or she shall be\ndeported from Nepal within seven days after the date of completion\nof the service of imprisonment imposed under this Section.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"159","title":"Statute of limitation","content":"No complaint shall lie after the expiry of six\nmonths from the date of knowledge of commission of the offence\nunder Section 158 and from the date of commission of any of the\nother offences under this Chapter.\nChpater-10\nOffences Relating to Discrimination and Other Degrading Treatment","children":[]},{"tier":2,"nodeType":"rule","identifier":"160","title":"Prohibition of making discriminator y treatment","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"Except as\notherwise provided by laws, no authority who exercises power under\nlaw shall, in the exercise of such power or a general law,\nintentionally make a discriminatory treatment against any citizen on\ngrounds of origin, religion, color, caste, race, sex, physical condition,\ndisability, condition of health, marital status, pregnancy, economic\ncondition, language or region, ideology or on similar other grounds.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) shall be liable to a sentence of\nimprisonment for a term not exceeding three years or a fine not\nexceeding thirty thousand rupees or both the sentences.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"161","title":"Prohibition of purchasing, selling or distributing goods or","content":"service with discrimination: (1) No person, in purchasing, selling or\ndistributing any goods or services, shall purchase, sell or distribute\nsuch goods or services from or to only any person belonging to any\nparticular caste, race or community or omit to provide , sell or\ndistribute such goods or services to any person belonging to any\nparticular caste, race or community.\nProvided that where a person, with the approval of the\ncompetent authority under law, provides, sells or distributes any\nparticular goods or services to only any person belonging to any\nparticular caste, race or community, for the protection of interest and\ndevelopment of a class which is economically, socially or\neducationally backward, such person shall not be considered to have\ncommitted the offence under this Section.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) shall be liable to a sentence of\nimprisonment for a term not exceeding one year or a fine not\nexceeding ten thousand rupees or both the sentences.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"162","title":"Prohibition of forced labour","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall force any one to\nwork against his or her will.\nProvided that this Section shall not be deemed to bar the\nengaging of any one in labor for a public work in accordance with\nlaw.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commit s, or causes to be committed, the\noffence under sub -section (1) shall be liable to a sentence of\nimprisonment for a term not exceeding three months or a fine not\nexceeding five thousand rupees or both the sentences.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"163","title":"Prohibition of slavery","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No pers on shall subject any one to\nslavery or servitude or hold or employ him or her in such status or\nsubject, or cause to be subjected, him or her to any other kind of\ntreatment similar thereto.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) shall be liable to a sentence of\nimprisonment for a term of five to ten years and a fine of fifty\nthousand to one hundred thousand rupees.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"164","title":"Prohibition of serfdom or debt bonded labour","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall\nsubject any one to, or hold any one in, serfdom or debt bonded\nlabour for any kind of consideration or employ any one in the status\nof serfdom or bonded labour, or subject, or cause to be subjected,\nhim or her to any other kind of treatment similar thereto.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person w ho commits, or causes to be committed, the\noffence referred to in sub-section (1) shall be liable to a sentence of\nimprisonment for a term from three to seven years and a fine from\nthirty thousand to one hundred thousand rupees.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"165","title":"Prohibition of undermining social rites and rituals","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person\nshall, by way of misrepresentation or use of force, do, or cause to be\ndone, any act which undermines or results in the undermining of the\nsocial rites and rituals of any one.\nExplanation: For the purposes of this Section, any r ites and\nrituals constituting racial discrimination shall not be considered to be\nsocial rites and rituals.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits the offence referred to in sub-\nsection (1) shall be liable to a sentence of imprisonment for a term\nnot exceeding one year or a fine not exceeding ten thousand rupees\nor both the sentences.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"166","title":"Prohibition of untouchability or discriminatory treatment on","content":"ground of caste: (1) No person shall subject any one to\nuntouchability or any other kind of discriminati on, or prevent any\none from appearing in any public place or entering into any religious\nplace of public nature, or deprive any one of using water or water\npond in public use or of the use of things of any other private or\npublic utility or convenience, on the grounds of custom, tradition,\nreligion, culture, rites or rituals, caste, race, community, profession,\noccupation, physical condition or origin of social community.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) shall be liable to a sentence of\nimprisonment for a term not exceeding three years or a fine not\nexceeding thirty thousand rupees or both the sentences, and if a\npublic servant commits the offence referred to in this Section, he or\nshe shall be l iable to an additional sentence of imprisonment for a\nterm not exceeding three months.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"167","title":"Prohibition of torture","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No authority who is competent under the\nlaw in force to investigate or prosecute any offence, implement law,\ntake any one into control, or hold any one in custody or detention in\naccordance with law shall subject, or cause to be subjected, any one\nto physical or mental torture or to cruel, brutal, inhuman or\ndegrading treatment.\nExplanation: For the purposes of this Section, intentional\ninflicting of physical or mental pain or suffering on any person who\nis arrested, taken into cont rol, held in custody, detention or\nimprisonment or under preventive detention or security or any other\nperson interested in such person or subjecting such person to cruel,\nbrutal, inhuman or degrading treatment or punishment for the\nfollowing purpose shall be considered to constitute torture or cruel,\nbrutal, inhuman or degrading treatment or punishment against or to\nsuch person:\n(a) To get information on any matter,\n(b) To extort confession of any offence,\n(c) To punish for any act,\n(d) To show fear, intimidation or coercion, or\n(e) To do any other act contrary to law.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits the offence referred to in sub-\nsection (1) shall be liable to a sentenc e of imprisonment for a term\nnot exceeding five years or a fine not exceedi ng fifty thousand\nrupees or both the sentences, according to the gravity of the offence.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"A person who orders the commission of the offence\nreferred to in sub-section (1) or an a ccomplice who aids in the\ncommission of the offence referred to in this Section shall be liable\nto the same sentence as is imposable on the principal offender.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"No person who com mits the offence referred to in sub-\nsection (1) shall be allowed to plea th at he or she has committed the\noffence in pursuance of an order by the authority superior to him or\nher; and, on such ground, he or she shall not be exempted from the\nsentence imposable on him or her for the commission of such\noffence.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"168","title":"Prohibition of degrading or inhuman treatment","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person\nshall subject, or cause to be subjected, any one to degrading or\ninhuman treatment.\nExplanation: For the purposes of this Section, the following\nact shall be deemed to constitute a degrading or inhumane treatment:\n(a) To accuse one of being a witch,\n(b) To expel one from his or her place of residence in\naccusation of being a witch,\n(c) To ex-communicate one from the society, or\n(d) To make cruel, inhuman or degrading treatment by\ndoing any other act whatsoever.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits the offence referred to in sub-\nsection (1) shall be liable to a sentence of imprisonment for a term\nnot exceeding five years and a fine not exceeding fifty thousand\nrupees.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"Banishing a woman to a shed ( Chhaupadi) during\nmenstruation or deliver y, or subjecting, causing to be subjected, her\nto similar other discrimination, untouchability or inhuman treatment\nof any kind is prohibited.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"A person who commits the offence referred to in sub-\nsection (3) shall be liable to a sentence of imprison ment for a term\nnot exceeding three months or a fine not exceeding three thousand\nrupees or both the sentences.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"Where a public servant commits the offence referred to\nin this Section, he or she shall be liable to an additional sentence of\nimprisonment for a term not exceeding three months.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"169","title":"Order for compensation to be paid","content":"A reasonable compensation\nfor the injury or pain caused to the victim shall be ordered to be paid\nby the person who has committed the offence referred to in this\nChapter.","children":[]},{"tier":2,"nodeType":"rule","identifier":"170","title":"Statute of limitation","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"There shall be no statute of limitation for\nmaking a complaint in relation to any of the offences referred to in\nSections 163 and 164.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"No complaint shall lie after the expiry of six months\nfrom the date of commission of the offence referred to in Section 167\nor from the date of release of the concerned person from arrest,\ncontrol, custody, detention, imprisonment or preventive detention\nand from the date of knowledge of commission of any of the other\noffences referred to in this Chapter.","children":[]}]}]},{"tier":1,"nodeType":"chapter","identifier":"Chapter-11","title":null,"content":"Offences Relating to Marriage","children":[{"tier":2,"nodeType":"rule","identifier":"171","title":"Prohibition of concluding marriage without consent","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No\nmarriage shall be concluded, or caused to be concluded, without the\nconsent of the persons getting married.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A marriage concluded without the consent referred to in\nsub-section (1) shall be void.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"A person who commits the offence referred to in sub-\nsection (1) shall be liable to a sentence of imprisonment for a term\nnot exceeding two years and a fine not exceeding twenty thousand\nrupees.\nExplanation: For the purposes of this Section, a consent given\nby a person who has not attained the marriageable age under Section\n173 shall not be deemed to be consent.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"172","title":"Prohibition of concluding marriage in prohibited degree of","content":"relationship: (1) E xcept as otherwise customarily practiced, no\nperson shall conclude, or cause to be concluded, marriage with one\nwho is within the prohibited degree of relationship by consanguinity\nor affinity.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"Where a marriage referred to in sub-section (1) has been\nconcluded in ignorance, such marriage shall be void.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"Where a marriage referred to in sub-section (1) has been\nconcluded knowingly, the person concluding such marriage shall be\nliable to the sentence imposable for the offence of incest and a\nperson causing the conclusion of such marriage shall be liable to a\nsentence of imprisonment for a term not exceeding three months or a\nfine not exceeding three thousand rupees or both the sentences, and\nsuch marriage shall, ipso facto, be void.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"173","title":"Prohibition of concluding child marriage","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No marriage shall be\nconcluded or cause to be concluded unless parties to the marriage\nhave attained twenty years of age.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A marriage concluded in contravention of sub -section","children":[]},{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"shall, ipso facto, be void.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"A person who commits the offence referred to in sub-\nsection (1) shall be liable to a sentence of imprisonment for a term\nnot exceeding three years and a fine not exceeding thirty thousand\nrupees.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"174","title":"Prohibition of transacting property in marriage","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No marriage\nshall be concluded, or caused to be concluded, upon having asked\nfor, or on the condition of receiving or giving of, any type of\nmovable or immovable property, dowry or any property from the\nbridegroom or the bride side, except such ordinary gift, donatio n,\nmoney or one set of jewelry worn on the body as has been practiced\nin his or her custom.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits the offence referred to in sub-\nsection (1) shall be liable to a sentence of imprisonment for a term\nnot exceeding three years or a fine no t exceeding thirty thousand\nrupees or both the sentences.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"No person shall, after the conclusion of marriage, ask\nthe bride or her relative for any movable, immovable property or\ndowry referred to in sub -section (1), or make, in any way, any\nannoyance, harassment or inhuman or degrading treatment to the\nbride or her relative for the reason that such movable, immovable\nproperty or dowry has not been given.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"A person who commits the offence referred to in sub-\nsection (3) shall be liable to a sentence of imprisonment for a term\nnot exceeding five years or a fine not exceeding fifty thousand\nrupees or both the sentences.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"Where any property has been taken as mentioned in\nsub-section (1) or (3), such property shall be returned to the\nconcerned person.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"175","title":"Prohibition of bigamy","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No married man shall, during the\ncontinuation of the marital relationship, conclude another marriage.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"No woman shall conclude marriage with a man\nknowingly that he is already married.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"Notwithstanding anything conta ined in sub -section (1)\nor (2), a man or woman may marry again if the husband and wife\nhave got separated upon making partition in accordance with law.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) or (2) shall be liable to a\nsentence of imprisonment for a term of one year to five years and a\nfine of ten thousand to fifty thousand rupees.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"The marriage referred to in sub -section (1) shall, ipso\nfacto, be void.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(6)","title":null,"content":"Notwithstanding anything contained else where in this\nSection, nothing contained in this Section shall be deemed to have\neffect on any marriage concluded in accordance with the law in force\nfor the time being prior to the commencement of this Act.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"176","title":"Statute of limitation","content":"No complaint on any offence under this\nChapter shall lie after the expiry of three months from the date of\nknowledge of the commission of the offence.","children":[]}]},{"tier":1,"nodeType":"chapter","identifier":"Chapter-12","title":null,"content":"Offences Relating to Human Body","children":[{"tier":2,"nodeType":"rule","identifier":"177","title":"Prohibition of doing act with the intention of causing death","content":"(homicide): (1) No person shall intentionally kill, or do, or cause to\nbe done, any act causing the death of, another person.\nExplanation: For the purposes of this S ection, even if a\nperson intentionally causes such serious bodily injury or hurt to\nanother person as is likely to cause the death of that other person but\nthat person does not die immediately but die subsequently in\nconsequence of that injury or hurt, the person shall be considered to\nhave killed that other person.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commit s, or causes to be committed, the\noffence referred to in sub-section (1) shall be liable to the sentence of\nimprisonment for life.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"178","title":"Prohibition of doing act likely to cause death","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall\ndo any act, with the knowledge that, or having reaso n to believe that,\nsuch act is, in an ordinary course, likely to cause the death of another\nperson.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"If a person dies in consequence of any act referred to in\nsub-section (1), t he offender shall be liable to the sentence of\nimprisonment for life.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"179","title":"Prohibition of causing death by grave provocation or in heat of","content":"passion: (1) Notwithstanding anything contained in Section 177 or\n178, a person who causes the death of another person in any of the\nfollowing circumstances shall be liable to a sentence of\nimprisonment for a term of ten to fifteen years and a fine of one\nhundred thousand to one hundred fifty thousand rupees:\n(a) Where the offender, while being deprived of the power\nof self-control by grave and sudden provocation, causes\nthe death of the person who gave such provocation,\nProvided that this clause shall not apply to the\nfollowing circumstance:","children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"Where the offender is provoked by\nanything done in obedience to the law or in\nthe exercise of the right of private defense\nor anything done or intended to be done by\na public servant in the exercise of his or her\nofficial duties,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"Where the offender himself or herself gives\nprovocation to another with intent to do\nharm to any one and anything done by that\nother person upon being so provoked\ncauses the death of any person.\n(b) Where the offender in the exercise in good faith of the\nright of private defence exceeds the limit of such power\nand causes the death of the person against whom he or\nshe is exercising such right of private defence,\n(c) Where dea th is caused instantly in the heat of passion\nupon a sudden quarrel,\nProvided that while doing any act referred to in\nthis clause, the offender must not have taken an undue\nadvantage or acted in a cruel or unusual manner.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"Notwithstanding anything cont ained in clauses\n(b) and (c) of sub -section (1), the provisions contained in these\nclauses shall not be applicable to any case of murder committed with\npremeditation or deliberate afterthought.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"180","title":"Punishment for homicide by causing death of person other than","content":"person whose death was intended: Notwithstanding anything\ncontained in Sections 177, 178 and 179, where a person, by doing\nanything which he or she intends to cause or knows to be likely to\ncause or has reason to believe to be likely to cause death of any one\nother than the one whose death was so intended, he or she shall be\nliable to the sentence set forth in Sections 177, 178 and179, as the\ncase may be.","children":[]},{"tier":2,"nodeType":"rule","identifier":"181","title":"Prohibition of causing death by recklessness","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall\ncause the death of any one by doing a reckless act.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits the offence referred to in sub-\nsection (1) shall, except in the cases referred to in Sections 177, 178\nand 179, be liable to a sentence of imprisonment for a term of three\nto ten years and a fine of thirty thousand to one hundred thousand\nrupees.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"182","title":"Prohibition of causing death by negligence","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"Except in the case\nreferred to in Section 179, no person shall cause the death of any one\nby doing a negligent act.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits the offence referred to in sub-\nsection (1) shall be liable to a sentence of imprisonment for a term\nnot exceeding three years and a fine not exceeding thirty thousand\nrupees.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"Except in the case referred to in sub -section (1), if any\nact done by a person under such circumst ances that such act is less\nlikely to cause death causes the death of any one accidently, that\nperson shall be liable to a sentence of imprisonment for a term of six\nmonths to two years or a fine not exceeding twenty thousand rupees\nor both the sentences.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"183","title":"Prohibition of commi tting attempt to murder","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person\nshall, with the intention of committing murder of anyone, commit an\nattempt to murder.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits , or causes to be committed, the\noffence referred to in sub -section (1) shall be liable to a sentence of\nimprisonment for a term not exceeding ten years and a fine not\nexceeding one hundred thousand rupees.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"184","title":"Prohibition of throwing or abandoning person under one's own","content":"guardianship: (1) A person, being bound to care or maintain an\ninfant, child, disabled patient or elderly person, shall not so throw,\nabandon or desert as to cause danger to the body or life of such\ninfant, child, patient or elderly person.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) shall be liable to a sentence of\nimprisonment for a term not exceeding three years and a fine not\nexceeding thirty thousand rupees.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"If the offence referred to in sub -section (1) causes the\ndeath of such child, disabled patient or eld erly person, the offender\nshall be liable to a sentence of imprisonment for a term not\nexceeding seven years and a fine not exceeding seventy thousand\nrupees.\nProvided that if the throwing, abandonment or neglect causes\nthe death of an infant, the offend er shall be liable to the sentence\nreferred to in Section 177.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"185","title":"Prohibition of abetment of suicide","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall abet the\ncommission of suicide by another, or create, or cause to be created,\nsuch circumstances as likely to lead towards the commi ssion of such\nact.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits the offence referred to in sub-\nsection (1) shall be liable to a sentence of imprisonment for a term\nnot exceeding five years and a fine not exceeding fifty thousand\nrupees.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"186","title":"Order for compensation to be pai d","content":"If any harm, injury or loss is\ncaused to the body, life or property of any person from the\ncommission of any offence referred to in this Chapter, a reasonable\ncompensation for such harm, injury or loss shall be ordered to be\npaid by the offender to the victim and to his or her successor if the\nvictim is unavailable.","children":[]},{"tier":2,"nodeType":"rule","identifier":"187","title":"Statute of limitation","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"There shall be no statute of limitation for\nmaking a complaint in relation to any of the offences under Sections\n177, 178, 179, 180, 181, 182, and proviso to s ub-section (3) of\nSection 184.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"No complaint shall lie after the expiry of six months\nfrom the date of knowledge of the commission of any of the offences\nunder this Chapter other than those set forth in sub-section (1).","children":[]}]}]},{"tier":1,"nodeType":"chapter","identifier":"Chapter-13","title":null,"content":"Offences against Protection of Pregnancy","children":[{"tier":2,"nodeType":"rule","identifier":"188","title":"Prohibition of abortion","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall, except in the case\nreferred to in Section 189, commit abortion, or do any act with intent\nto cause, or with the knowledge that, or having reason to believe that,\nsuch act is likely to cause, abortion.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"No person shall cause a pregnant woman to abort, by\ncoercing, threatening, alluring or inducing her to so abort.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"A person who commits the offence referred to in sub-\nsection (1) or (2) shall be liable to:\n(a) A sentence of imprison ment for a term not exceeding\none year and a fine not exceeding ten thousand rupees in\nthe case of pregnancy of up to twelve weeks,\n(b) A sentence of imprisonment for a term not exceeding\nthree years and a fine not excee ding thirty thousand\nrupees in the case of pregnancy of more tha n twelve\nweeks and up to twenty-five weeks,\n(c) A sentence of imprisonment for a term not exceeding\nfive years and a fine not exceeding fifty thousand rupees\nin the case o f pregnancy of more than twenty -five\nweeks.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"If the pregnancy is not terminated at once by an act of\nabortion and the child born alive but the c hild dies immediately after\nbirth as the consequence of such act, such act shall, for the purposes\nof this Section, be deemed to constitute the offence of abortion.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"If an act done by a person in making attempt to cause\nthe death of a pregnant woman does not cause the death of the\nwoman but causes the termination of her pregnancy of twenty -five\nweeks or more, the offender shall be liable to a sentence of\nimprisonment for a term not exceeding five years, in addition to the\nsentence to be imposed under this Act or other law.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(6)","title":null,"content":"Notwithstanding anything contained elsewhere in this\nSection, if any act done by a person with premeditation against a\npregnant woman causes abortion, that person shall be liable to the\nfollowing sentence despite the fact that he or she has not done such\nact with the intention of causing abortion:\n(a) A sentence of imprisonment for a term not exceeding\none year in the case of pregnancy of up to twelve weeks,\n(b) A sentence of imprisonment for a term not exceeding\nthree years in the case of pregnancy of more than twelve\nweeks and up to twenty-five weeks,\n(c) A sentence of imprisonment for a term not exceeding\nfive years in the case of pregnancy of more than twenty-\nfive weeks.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(7)","title":null,"content":"No person shall, with the intention of causing abortion,\ndo, or cause to be done, any act by which the sex of the foetus is\nidentified, and abort or cause abortion following such sex\nidentification.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(8)","title":null,"content":"A person who commits the offence referred to in sub-\nsection (7) shall be liable to:\n(a) A sentence of imprisonment for a term of three months\nto six months, in the case of the offence of identifying,\nor causing identification of, the sex of the foetus with\nthe intention of causing abortion, and\n(b) A sentence of imprisonment for a term not exceeding\none year, in addition to the sentence specified in sub -\nsection (3), in the case of the offence of aborting or\ncausing abortion after identifying the sex.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"189","title":"When a bortion can be made","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"Notwithstanding anything\ncontained in Section 188, where a health worker causes abortion in\nany of the following circumstances, no offence of abortion under this\nAct shall be deemed to have been committed:\n(a) The pregnancy of up to twelve weeks is terminated with\nthe consent of the pregnant woman,\n(b) The pregnancy is terminated with the consent of the\npregnant woman, upon the opinion of a licensed doctor\nthat her life may be in danger or her physical or mental\nhealth may deteriorate or a handicapped child will born\nif pregnancy is not terminated,\n(c) The pregnancy of up to eighteen weeks conceived from\nrape or incest is terminated with the consen t of the\npregnant woman,\n(d) The pregnancy of a woman with human immune -\ndeficiency virus (HIV) or other incurable disease of\nsimilar nature is terminated with her consent.\nExplanation: For the purposes of this Section, the term\n\"health worker\" means a doctor or health worker who, upon having\nthe specified qualification, has obtained a license for causing\nabortion.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"190","title":"Sta tute of limitation","content":"No complaint shall lie after the expiry of six\nmonths from the date of knowledge of commission of the offence\nunder this Chapter.","children":[]}]},{"tier":1,"nodeType":"chapter","identifier":"Chapter-14","title":null,"content":"Offences Relating to Hurt or Grievous Hurt","children":[{"tier":2,"nodeType":"rule","identifier":"191","title":"Prohibition of causing hurt","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall cause hurt to\nanother person.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who does any of the following acts to another\nperson shall be deemed to cause hurt:\n(a) Any act by which any kind of bodily pain is caused,\n(b) Any act by which a disease is transferred,\n(c) Any other act by which infirmity is caused.\nExplanation: For the purposes of this Section, the term\n\"infirmity\" means the state of any part of the body being incapable of\nfunctioning normally, and this term also includes mental infirmity.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"A person who commits, or c auses to be committed, the\noffence referred to in sub-section (1) shall be liable to a sentence of\nimprisonment for a term not exceeding three years or a fine not\nexceeding thirty thousand rupees or both the sentences.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"192","title":"Prohibition of causing grievous hurt","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall cause\ngrievous hurt to any other person.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"Where any person does any act with the intention of\ncausing hurt to another person, which results in any of the following\nconsequences, that person is deemed to have committed the offen ce\nof causing grievous hurt to that other person:\n(a) Making blind by making privation of the sight of, or by\nbreaking, either eye,\n(b) Privation of smelling power of the nose,\n(c) Privation of hearing power of either ear,\n(d) Privation of speaking power of the tongue,\n(e) Cutting of woman's breast,\n(f) Emasculation of man and woman (making woman\ninfertile or man impotent),\n(g) Privation of the backbone, …, hand, leg or joint of\nsuch organ by breaking, fracturing, dislocating it,\n(h) Any hurt which causes the sufferer to be unable to\nperform his or her professional work.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"Where any act of hurt, though not causing grievous hurt\nimmediately, results subsequently in the consequence referred to in\nsub-section (2), it shall be deemed to have caused grievous hurt.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"A person who commits the offence referred to in sub-\nsection (1) shall be liable to a sentence of imprisonment for a term\nnot exceeding ten years and a fine not exceeding one hundred\nthousand rupees.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"Notwithstanding anything contained in sub -section (4),\nin the case of so ca using grievous hurt to either of the organs\nperforming the same function that it becomes dysfunctional, the\noffender shall be liable to half the sentence specified in that sub -\nsection, and where the wound caused by grievous hurt gets so healed\nas to restor e the organ, the offender shall be liable to a sentence of\nimprisonment for a term not exceeding three years and a fine not\nexceeding thirty thousand rupees.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"193","title":"Prohibition of causing disfigurement by use of acid or other","content":"chemical, biological or toxin su bstance: (1) No person shall cause\nbodily pain to another person by administering acid or similar kind\nof other chemical, biological or toxin substance to, or throwing such\nsubstance on, that other person, or by burning, maiming, strolling the\nbody with or applying to the body such substance or disfigure the\nface or any part of the body of that other person.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits the offence referred to in sub-\nsection (1) shall be liable, according to the nature of the offence, to a\nsentence of imprisonment for a term of five to eight years and a fine\nof one hundred thousand to five hundred thousand rupees in the case\nof disfigurement of the face, and to a sentence of imprisonment for a\nterm of three to five years and a fine of fifty thousand to three\nhundred thousand rupees in the case of disfigurement of any other\norgan of the body or bodily pain.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"The amount of fine collected in accordance with sub -\nsection (2) shall be paid in whole to the victim as compensation.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"194","title":"Sentence for causing hurt or grievous hurt by grave provocation","content":"or in heat of passion : (1) Notwithstanding anything contained in\nSection 191 or 192, a person who causes hurt in any of the following\ncircumstances shall be liable to a sentence of imprisonment for a\nterm not exceeding tw o years or a fine not exceeding twenty\nthousand rupees or both the sentences in the case of a grievous hurt,\nand to a sentence of imprisonment for a term not exceeding one year\nor a fine not exceeding ten thousand rupees or both the sentences in\nthe case of any other kind of hurt:\n(a) Where the offender, while being deprived of the power\nof self-control by grave and sudden provocation, causes\nhurt to the person who gave such provocation or to any\nother person by a mistake of fact or happens to cause\ninjury to another person by accident.\nProvided that this clause shall not apply to the\nfollowing circumstance:","children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"Where the offender causes hurt upon being\nprovoked by anything done in obedience to\nthe law or in the exercise of the right of\nprivate defence or any anything done or\nintended to be done by a public servant in\nthe exercise of his or her official duties,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"Where the offender himself or herself gives\nprovocation to another with intent to cause\nany harm to any one and anything done by\nthat other pers on upon being so provoked\ncauses hurt to any person.\n(b) Where the offender in the exercise in good faith of the\nright of private defence exceeds the limi t of such power\nand causes injury to any person,\n(c) Where hurt is caused to any person instantly in t he heat\nof passion upon a sudden quarrel,\nProvided that while doing any act referred to in\nthis clause, the offender must not have taken an undue\nadvantage or acted in a cruel or unusual manner.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"Notwithstanding anything contained in clauses\n(b) and (c ) of sub -section (1), the provisions contained in these\nclauses shall not be applicable to any case of hurt or grievous hurt\ncaused with premeditation or deliberate afterthought.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"195","title":"Prohibition of causing hurt or grievous hurt by recklessness or","content":"negligence: (1) No person shall cause hurt or grievous hurt or other\ninjury to any one by doing a reckless or negligent act.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits the offence referred to in sub-\nsection (1) shall be liable to the following sentence:\n(a) A sentence of imprisonme nt for a term not exceeding\ntwo years or a fine not exceeding twenty thousand\nrupees or both the sentences, in the case of a grievous\nhurt caused by a reckless act, and a sentence of\nimprisonment for a term not exceeding one year or a\nfine not exceeding te n thousand rupees or both the\nsentences, in the case of any other kind of injury caused\nby a reckless act,\n(b) A sentence of imprisonment for a term not exceeding\nsix months or a fine not exceeding five thousand rupees\nor both the sentences in the case of the commission of\nsuch offence by a negligent act.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"196","title":"Prohibition of using criminal force","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall use\ncriminal force to another person.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person shall be considered to use criminal force to\nanother person if he or she does any of the following acts:\n(a) To use any kind of force to that other person with the\nintention of committing an offence,\n(b) To use force to that other person with the intention of\ncausing, or knowing it to be likely that the use of such\nforce will cause, injury, fear or annoyance to that other\nperson or his or her family or property,\n(c) To terrify that other person to apprehend that force will\nbe used to him or her or to threat or intimidate to use\nforce, or attempt to use force, in any other manner, to\nhim or her.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"Notwithstanding anything contained elsewhere in this\nSection, the use of any force, with one's consent, in the course of\nimparting teaching, instruction or training on the concerned subject,\nconducting acting or treatment of any kind or in a m anner to re nder\nbenefit or the use of force of usual nature in the course of having any\nkind of game shall not be considered to be the use of criminal force.\nProvided that the provision of this sub -section shall not apply\nto any malicious use of force to cause injury to any one.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"A person who uses, or causes to be used, criminal force\nshall be liable to a sentence of imprisonment for a term not\nexceeding three years or a fine not exceeding thirty thousand rupees\nor both the sentences, in the case of using criminal force by carrying\na weapon, and to a sentence of imprisonment for a term not\nexceeding one year or a fine not exceeding ten thousand rupees or\nboth the sentences, in the case of using criminal force without\ncarrying a weapon.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"197","title":"Prohibition of making unc onscious with intent to commit","content":"offence: (1) No person shall, with intent to facilitate the commission\nof any offence, feed or administer, in any other manner, to another\nperson any substance causing unconsciousness, dizziness or\nunhealthiness or make that other person unconscious in any manner\nwhatsoever.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committed, the\noffense referred to in sub-section (1) shall be liable to a sentence of\nimprisonment for a term not exceeding one year and a fine not\nexceeding ten thousand rupees.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"Where any act referred to in sub-section (1) has resulted\nin the commission of such offence, the sentence referred to in this\nSection shall be added to the sentence imposable for such offence.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"198","title":"Compensation","content":"Where any harm, damag e or loss is caused to any\nperson's body, life or property from the commi ssion of the offence\nreferred to in this Chapter, compensation shall be cause d to be paid\nby the offender to the victim.","children":[]},{"tier":2,"nodeType":"rule","identifier":"199","title":"Statute of limitation","content":"No complaint shall lie, in the ca se of the\noffence referred to in Section 196, after the expiry of three months\nfrom the date of its commission, in the case of the offence referred to\nin Section 197, after the expiry of six months from the date on which\nsuch person becomes conscious , and, in the case of any of the other\noffences referred to in this Chapter, after the expiry of one year from\nthe date of its commission.","children":[]}]},{"tier":1,"nodeType":"chapter","identifier":"Chapter-15","title":null,"content":"Offences Relating to Unlawful Detention","children":[{"tier":2,"nodeType":"rule","identifier":"200","title":"Prohibition of unlawful confinement","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall\nmaliciously subject, or cause to be subjected, another person to\ndetention in any other manner except in accordance with law.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who co mmits the offence referred to in sub-\nsection (1) shall be liable to a sentence of imprisonment for a term\nnot exceeding three years and a fine not exceeding thirty thousand\nrupees.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"No one other than the competent authority shall\nobstruct, or cause to be obstructed, the movement of any person.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"A person who commits the offence referred to in sub-\nsection (3) shall be liable to a sentence of imprisonment for a term\nnot exceeding six months or a fine not exceeding five thousand\nrupees or both the sentences.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"201","title":"Prohibition of holding in detention without providing minimum","content":"humane facilities: (1) No authority who is compe tent by law to\nmake detention shall detain, or cause to be detained, any person by\ndepriving him or her of such facilities as required to be provided in\naccordance with law or of such minimum humane facilities as are\navailable in the place of his or her detention.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits the offence referred to in sub-\nsection (1) shall be liable to a sentence of imprisonment for a term\nnot exceeding one and half years and a fine not exceeding fifteen\nthousand rupees.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"202","title":"Prohibition of detaining person for whose release order has been","content":"issued: (1) No person shall keep on detaining any person held in\ndetention in accordance with law after receiving an order issued by a\ncompetent authority under law for the release of such person from\ndetention.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) shall be liable to a sentence of\nimprisonment for a term not exceeding one year and a fine not\nexceeding ten thousand rupees.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"203","title":"Prohibition of detention in secret","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No competent authority shall\nhold any person in detention secretly in such a manner that the\ndetention of such person or the place of such detention may not be\nknown or discovered.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) shall be liable to a sentence of\nimprisonment for a term not exceeding four years and a fine not\nexceeding forty thousand rupees.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"204","title":"Order for compensation to be paid","content":"A reasonable compensation\nshall be ordered to be paid by the offend er who commits, or causes\nto be committed, the offence referred to in this Chapter to the victim.","children":[]},{"tier":2,"nodeType":"rule","identifier":"205","title":"Statute of limitation","content":"No complaint shall lie, in the case of an\noffence under sub-section (3) of Section 200, after the expiry of three\nmonths from the date of commission of such offence, and in the case\nof any of the other offences under this Chapter, after the expiry of\nthree months from the date of release of the detained person from\nsuch detention.","children":[]}]},{"tier":1,"nodeType":"chapter","identifier":"Chapter-16","title":null,"content":"Offences Relating to Enforced Disappearance","children":[{"tier":2,"nodeType":"rule","identifier":"206","title":"Prohibition of enforced appearance","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall subject,\nor cause to be subjected, any one to enforced disappearance.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"For the purposes of sub -section (1), the term \"enforced\ndisappearance” means any of the following acts:\n(a) The arrest, detention or any other form of control of a\nperson by a person or security personnel having\nauthority by law to make arrest, investigation or\nenforcement of law, followed by a failure to produce\nsuch person before the case trying authority within\ntwenty-four hours of the date of such arrest or\ndeprivation of liberty, excluding the time required for\njourney, or a refusal to allow the concerned person to\nmeet such person, and/or by concealment of information\nas to where, how and in what condition such pers on has\nbeen so held,\n(b) The abduction, custody, control or any other form of\ndeprivation of liberty of a person by any person,\norganization or group, whether organized or not,\nfollowed by concealment of information to the\nconcerned person as to the reason for such deprivation\nand where, how and in what condition such person has\nbeen so held,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"A person who orders the commission of enforced\ndisappearance of a person upon arrest, detention or control of such\nperson and a person who implements such order sh all be considered\nto be the principal offender of enforced disappearance.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"Where an act of enforced disappearance is committed in\npursuance of order or direction given by a person holding public\noffice or by the responsible person of an organization or group,\nwhether organized or unorganized, the person giving such order or\ndirection shall be liable as the principal offender of enforced\ndisappearance.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"A superior who, despite knowing that his or her\nsubordinate official, body or group was committing o r about to\ncommit an act of enforced disappearance, disregards such\ninformation or fails to take necessary measures to prevent the\ncommission of such act shall also be considered to have committed\nthe offence under this Section.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(6)","title":null,"content":"Where a person has been subjected to enforced\ndisappearance by two or more persons jointly, every person involved\nin such act shall be equally liable as the offender.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(6)","title":null,"content":"A person who commits the offence referred to in sub-\nsection (1) shall be liable to the following sentence:\n(a) In the case of the principal offender of enforced\ndisappearance, a sentence of imprisonment for a\nterm not exceeding fifteen years and a fine not\nexceeding five hundred thousand rupees, having\nregard to the duration and circumstances of such\nenforced disappearance,\n(b) In the case of a person who is accomplice or\nconspires to the commission of enforced\ndisappearance, the same sentence as is imposable\non the principal offender, and in the case of a\nperson who attempts to or facilitates the\ncommission of e nforced disappearance, half the\nsentence imposable on the principal offender.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(8)","title":null,"content":"A person who does an act constituting the offence\nreferred to in sub-section (1) against a woman or child shall be liable\nto an additional sentence of imprisonment for a term of two years, in\naddition to the sentence to be imposed pursuant to sub-section (7).","children":[]},{"tier":3,"nodeType":"clause","identifier":"(9)","title":null,"content":"Where a person has committed any other offence\npunishable by law against any one who has been subjected to\nenforced disappearance, during such disappearance, he or sh e shall\nbe liable to the additional sentence under this Section, in addition to\nthe sentence imposable by law for such offence.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(10)","title":null,"content":"A person who subjects any one to enforced\ndisappearance by using any government vehicle, building, arms and\nammunition or g oods shall be liable to an additional sentence of\nimprisonment for a term of one year, in addition to the sentence\nimposable under this Section.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"207","title":"Forfeiture of goods related to offence","content":"Any building, land, vehicle,\narms and other goods knowingly allowe d by the owner thereof to be\nused in, or used with the consent of the concerned owner in, the\ncommission of the offence punishable under this Chapter shall be\nforfeited.\nProvided that no governmental building, vehicle, arms and\ngoods shall be forfeited.","children":[]},{"tier":2,"nodeType":"rule","identifier":"208","title":"Entitlement to compensation","content":"Where a person who is subjected to\nenforced disappearance appears or is made public subsequently, he\nor she shall be entitled to get a reasonable compensation from the\nperson who has so subjected him or her to enforced disappearance.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"Where the person subjected to enforced disappearance\nis already dead, the immediate successor to him or her shall be\nentitled to get the compensation referred to in sub-section (1).","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"209","title":"Property to be returned","content":"Where any person, in subjec ting another\nperson to enforced disappearance under this Chapter, has also taken\nany property belonging to that other person, the person who has so\nsubjected to enforced disappearance shall return such property, if\navailable, and pay a reasonable compensat ion for such property, if\nnot available, to the disappeared person or his or her immediate\nrelative.","children":[]},{"tier":2,"nodeType":"rule","identifier":"210","title":"Statute of limitation","content":"No complaint shall be entertained after expiry\nof six months from the date of having knowledge of commission of\nthe offence und er this Chapter or from the date of the disappeared\nperson getting or being made public.\nProvided that if a complaint is filed, accompanied by the\nevidence, with the leave of the court, setting out the reason for not\nbeing in a position to file the complai nt, such complaint may lie at\nany time.","children":[]}]},{"tier":1,"nodeType":"chapter","identifier":"Chapter-17","title":null,"content":"Offences Relating to Kidnapping or Taking of Hostages","children":[{"tier":2,"nodeType":"rule","identifier":"211","title":"Prohibition of kidnapping","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall kidnap, or cause to\nbe kidnapped, another person.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"For the purposes of sub -section (1), a perso n shall be\nconsidered to have committed kidnapping if he or she does any of\nthe following acts:\n(a) To take any person to or compel him or her to go to any\nplace by using force or threats to use force or by\npracticing fraud, deception or intimidation or by\nshowing or not showing arms or by misrepresenting or\nby administering narcotics or alcoholic substance to him\nor her or by seizing or controlling in any way a vehicle\nby which he or she is travelling or exercising control in\nany way over such vehicle, or\n(b) To take by force any person to any place without his or\nher consent or any child or any person who is under\nshelter of any one due to his or her physical incapacity\nor any person of unsound mind due to mental illness\nwithout the consent of his or her f ather, mother or\nguardian or by way of misrepresentation.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"212","title":"Prohibition of hostage -taking","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall take another\nperson hostage.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"For the purposes of sub -section (1), a person shall be\nconsidered to have committed hostage -taking if that person seizes or\ndetains another person without his or her consent or a child or a\nperson of unsound mind without the consent of his or her father,\nmother or guardian, by using force or threats to use force, or by\npracticing fraud, deception, coercion or intimidation or by showing\nor not showing arms or by misrepresenting or by administering\nnarcotics or alcoholic substance to him or her or by seizing or\ncontrolling a vehicle or place where he or she is staying.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"Notwithstanding anything contained in sub-section (2),\nplacing, in good faith, an unsound person under the surveillance or\ncontrol of any one in the course of treatment or for any other\npurpose, for the benefit of the concerned person, with the consent of\nhis or her father, mother or guard ian shall not be deemed to\nconstitute hostage-taking.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"213","title":"Punishment for kidnapping or hostage -taking","content":"A person who\ndoes, or causes to be done, any act referred to in Section 211 or 212\nshall be liable to a sentence of imprisonment for a term of seven to\nten years and a fine of seventy-five thousand to one hundred\nthousand rupees if the person does , or causes to be done , such act\nwith the intention of causing death, causing injury by subjecting to\nhurt, committing rape or unnatu ral sex, trafficking or ens laving, or\nsubjecting to forced labor, engaging into prostitution, subjecting to\ntorture, compelling to do or cause to be done any act, taking ransom\nor compelling to do any other act which constitutes an y offence\nunder the law in force, and to a sentence of imprisonment for a term\nof three to five years and a fine of thirty thousand to fifty thousand\nrupees if the person does, or causes to be done, such act for any other\npurpose.","children":[]},{"tier":2,"nodeType":"rule","identifier":"214","title":"Additional sentence to be imposed","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"A person who takes another\nperson hostage under Section 212 after kidnapping him or her under\nSection 211 shall be liable to a sentence of imprisonment for a term\nof ten to fifteen years and a fine of one hundred thousand to one\nhundred fifty thousand rupees.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who does any o ther act considered to be an\noffence under this Act or under the law in force by committing\nkidnapping or hostage-taking shall be liable to the sentence referred\nto in sub-section (1), in addition to the sentence imposable for such\noffence.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"Where the offence referred to in Sections 211 and 212 is\ncommitted, or cause to be committed, in an organized manner, the\npersons committing such offence shall be liable to an additional\nsentence of imprisonment for a term of two years.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"215","title":"Person who abets or ord ers or attempts or conspires or is","content":"accomplice to be liable to sentence: (1) A person who abets or\norders the commission of any offence referred to in this Chapter shall\nbe liable to the same sentence as is imposable on the principal\noffender.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"Notwithstanding anything contained in sub -section (1),\nthe person who attempts or conspires to commit or is accomplice to\nthe commission of such act shall be liable to half the sentence\nimposable for that offence.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"216","title":"Reduction of sentence if surrendered","content":"Where a person committing\nan offence under this Chapter surrenders before the security\npersonnel at the time of committing the offence or renders assistance\nin arresting the other offenders or members of the gang committing\nthat offence, the court may, having reg ard to the circumstances,\nreduce the sentence for that person.","children":[]},{"tier":2,"nodeType":"rule","identifier":"217","title":"Compensation ordered to be paid","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"A reasonable compensation\nshall be ordered to be paid to the victim by the person who is held to\nhave committed or caused the commission of any offence under this\nChapter.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"The compensation referred to in sub -section (1) shall be\npaid to the immediate successor to the victim if the victim is already\ndead.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"218","title":"Statute of limitation","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"There shall be no statute of limitation for\nmaking a complaint i n the case of any offence under this Chapter\nwhich has caused the death of any one.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"No complaint shall lie after the expiry of two years after\nthe date of commission of any offence under this Chapter other than\nthat set forth in sub -section (1), and a fter the expiry of six months\nafter the date of release of the concerned person from such offence in\nthe case of any of the offences under Sections 211 and 212.","children":[]}]}]},{"tier":1,"nodeType":"chapter","identifier":"Chapter-18","title":null,"content":"Sexual Offences","children":[{"tier":2,"nodeType":"rule","identifier":"219","title":"Prohibition of committing rape","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No one shall commit rape.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"Where a man has sexual intercourse with a woman\nwithout her consent or with a girl child below eighteen years of age\neven with her consent, the man shall be considered to commit rape\non such woman or girl child.\nExplanation: For the purposes of this Chapter,-\n(a) Consent obtained by way of coercion, undue influence,\nintimidation, threat, misrepresentation, or kidnapping or\ntaking of hostage shall not be considered to be consent,\n(b) Consent obtained at the time of being of unsoundness of\nmind shall not be considered to be consent,\n(c) The penetration of penis into anus or mouth, penetration\nof penis, to any extent, into anus, mouth or vagina,\ninsertion of any object other than penis into vagina shall\nalso be considered to be rape.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"A person who commits rape shall be liable to the\nsentence of imprisonment as follows, having regard to the\ncircumstances of such sexual intercourse and the age of woman:\n(a) Imprisonment for a term of sixteen to twenty years, if\nshe is a girl child below ten years of age,\n(b) Imprisonment for a term of fourteen to sixteen years, if\nshe is a girl child who is ten years or above ten years of\nage but below fourteen years of age,\n(c) Imprisonment for a term of twelve to fourteen years, if\nshe is a girl child who is fourtee n or above fourteen\nyears of age but below sixteen years of age,\n(d) Imprisonment for a term of ten to twelve years, if the\nwoman is sixteen or above sixteen years of age but\nbelow eighteen years of age,\n(e) Imprisonment for a term of seven to ten years, i f the\nwoman is eighteen or above eighteen years of age.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"Notwithstanding anything contained in sub -section (3),\nif the husband commits rape on his wife during the existence of\nmarital relationship between them, he shall be liable to a sentence of\nimprisonment for a term not exceeding five years.\nProvided that the following situation shall not be considered as\nthe existence of marital relationship:\n(a) A case of partition has been instituted upon\nmaking separation of board and bread,\n(b) The wife has lived separa te upon taking her\npartition share from the husband,\n(c) A case of divorce from the husband has been\ninstituted.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"In the case of the situation referred to in sub -section (4),\nthe court may, if it is necessary to do so upon a petition by the\nvictim, order the husband to do the following:\n(a) To allow the wife to reside in the same house\nwhere she has resided, to provide her with food\nand clothes, not to hurt her and to behave her\npolitely and decently,\n(b) To get the wife to have required medical\ntreatment or provide reasonable amount for her\ntreatment,\n(c) To arrange a separate residence for the husband if\nit is not appropriate for them to reside in the same\nplace together and make necessary arrangement\nfor the maintenance of the wife while so residing\nseparately,\n(d) To refraining from doing act causing suffering or\nannoyance, in any manner, to the wife and do, or\ncause to be done, necessary and appropriate act\nfor the interest and security of the wife.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(6)","title":null,"content":"Notwithstanding anything contained in sub -section (1),\na man who commits rape in spite of knowing that he has human\nimmune deficiency virus (HIV positive) or a sexually transmitted\ndisease shall be liable to the following additional sentence, in\naddition to the sentence set forth in sub-section (3):\n(a) The sentence referred to in Section 105 in the\nevent of the commission of rape in spite of\nknowing that he has human immune deficiency\nvirus (HIV positive),\n(b) A sentence of imprisonment for a term not\nexceeding three years and a fine not exceeding\nthirty thousand rupees in the event of the\ncommission of rape in spite of knowing that he\nhas any other sexually transmitted disease.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(7)","title":null,"content":"A man who commits rape on a woman in a gang or on a\nwoman having pregnancy of more than six months or on a woman\nwho is infirm or disabled or suffering from physical or mental\nillness, or commits rape showing arms shall be liable to an additional\nsentence of imprisonment for a term not exceeding five years, in\naddition to the sentence set forth in sub-section (3).","children":[]},{"tier":3,"nodeType":"clause","identifier":"(8)","title":null,"content":"A pe rson who commits rape on a woman within the\nprohibited degree of relationship by consanguinity or affinity shall be\nliable to the sentence referred to in this Chapter, in addition to the\nsentence imposable for incest if he is liable to such sentence for\nincest.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"220","title":"Prohibition of incest","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall have sexual intercourse\nwith another person knowingly that such person is one falling within\nthe prohibited degree of relationship by consanguinity or affinity for\nmarriage according to the usage, custo m or tradition being practiced\nin his or her caste or lineage.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits the offence referred to in sub-\nsection (1) in the following relationship shall be liable to the\nfollowing sentence:\n(a) A sentence of imprisonment for life in the cas e of\nsexual intercourse between the natural mother\nand her natural son or between the natural father\nand his natural daughter,\n(b) A sentence of imprisonment for a term of four\nyears to ten years and a fine of forty thousand\nrupees to one hundred thousand rupees in the case\nof sexual intercourse between the step -mother\nand her step -son, between the step father and his\nstep daughter, between the full blood elder sister\nand brother, between full blood elder brother and\nsister, between father -in-law and daught er-in-law\nwithin the same branch, between grand-father and\ngrand-daughter or great -grand-daughter within\nthe same branch, between elder brother-in-law\nand sister -in-law within the same branch or\nbetween younger brother-in-law and sister-in-law\nwithin the same branch,\n(c) A sentence of imprisonment for a term of three to\nsix years and a fine of thirty thousand to sixty\nthousand rupees in the case of sexual intercourse\nbetween grand -mother and her grand -son or\ngreat-grand-son within the three generations of\nthe same branch, between father's elder brother or\nuncle and niece within the same branch, between\nnephew and great mother (wife of own father's\nbrother) or aunty within the same branch,\nbetween father -in-law and brother's daughter -in-\nlaw within the same br anch, between uterine\nmaternal uncle and niece or nephew and maternal\naunty, between mother's elder sister or younger\nsister and nephew or between mother -in-law\n(one's wife side) and son-in-law,\n(d) A sentence of imprisonment for a term of one\nyear to thre e years and a fine of ten thousand to\nthirty thousand rupees, having regard to, inter\nalia, the branch, relationship and generation, in\nthe case of sexual intercourse between persons in\nother relationship within seven generations of\none’s own clan except t hat referred to in clause\n(a), (b) or (c).","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"221","title":"Prohibition of sexual intercourse with detainee","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No\ngovernment employee shall have sexual intercourse with a person\nheld in prison or detention or facilitate or create circumstances for\nthe commission by another person of sexual intercourse with such\nperson.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committed,\nsexual intercourse referred to in sub -section (1) shall be liable to a\nsentence of imprisonment for a term not exceeding three years, and if\nsuch sexual intercourse is an offence under this Act or other law also,\nthe sentence referred to in this Section shall be added to the sentence\nunder such law.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"222","title":"Prohibition of sexual intercourse with person in one's own","content":"protection or security : (1) No person shall have, or aid another\nperson to have, sexual intercourse with any person in his or her\nprotection, security or custody, and no office -bearer or employee of\nany organization providing treatment or rehabilitation services to\npersons of unsound mind or suffering from physical or mental illness\nshall have sexual intercourse with any person held in such\norganization.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits the offence referred to in sub-\nsection (1) shall be liable to a sentence of imprisonment for a term\nnot exceeding thr ee years, and if such sexual intercourse is an\noffence under this Act or other law also, the sentence referred to in\nthis Section shall be added to the sentence under such law.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"223","title":"Prohibition of sexual intercourse with person in office or","content":"receiving profe ssional service: (1) No employee serving in a\ngovernment office or private office or person providing any\nprofessional service or commercial work shall have, or aid another\nperson to have, sexual intercourse with a person serving in such\noffice or a person making contact or being in contact for such service\nor work, while performing functions of such office or providing such\nservice or at the place where such service is provided.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits the offence referred to in sub-\nsection (1) shall be l iable to a sentence of imprisonment for a term\nnot exceeding four years and a fine not exceeding forty thousand\nrupees, and if such sexual intercourse is an offence under this Act or\nother law also, the sentence referred to in this Section shall be added\nto the sentence under such law.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"224","title":"Prohibition of sexual harassment","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall commit, or\ncaused to be committed, sexual harassment to another person.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person shall be considered to commit sexual\nharassment if the person holds or touches or attempts to touch any\nsensitive organ of, or opens or attempts to open undergarments of, or\nobstructs or hinders in any way the wearing or removing of\nundergarments of, or takes to any lonely place in an unusual manner,\nor gets his or her sexual organ to be touched or held by, or uses\nvulgar or similar other words, spoken or written or by gesture or by\nway of electronic medium, or shows any pornography to, or teases or\nannoys with sexual motive, or behaves in an unusual, undesirable or\nindecent manner with , a person who is not his wife or her husband,\nwithout her or his consent, with the motive of having sexual\nintercourse with her or him.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits the offence referred to in sub-\nsection (1) shall be liable to a sentence of imprisonment for a term\nnot exceeding three years and a fine not exceeding thirty thousand\nrupees.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"225","title":"Prohibition of child sexual abuse","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall commit, or\ncause to be committed, child sexual abuse.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person shall be considered to commit child sexual\nabuse if the person takes to any lonely place in an unusual manner,\nor holds or touches any sexual organ of, gets his or her sexual organ\nto be touched or held by, or makes any form of unusual sexual\nbehavior with, a child, with the motive of having sexual int ercourse\nwith the child.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"A person who commits the offence referred to in sub-\nsection (1) shall be liable to a sentence of imprisonment for a term\nnot exceeding three years and a fine not exceeding thirty thousand\nrupees.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"226","title":"Prohibition of unnatural s exual intercourse","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall\nhave, or cause to be had, unnatural sexual intercourse with another\nperson without his or her consent.\nExplanation: For the purposes of this sub -section, consent\ngiven by a child shall not be considered to be consent.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits the offence referred to in sub-\nsection (1) shall be liable to a sentence of imprisonment for a term\nnot exceeding three years and a fine not exceeding thirty thousand\nrupees.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"A person who commits the offence referred to in sub-\nsection (1) against a child shall be liable to the sentence under\nSection 219.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"227","title":"Prohibition of bestiality","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall have, or cause to be\nhad, sexual intercourse with an animal.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits the offence referred to in sub-\nsection (4) shall be liable to a sentence of imprisonment for a term\nnot exceeding two years and a fine not exceeding twenty thousand\nrupees, if the person has committed, or caused to be committed,\nsexual intercourse with a cow, and to a sentence of imprisonmen t for\na term not exceeding one year and a fine not exceeding ten thousand\nrupees, in the case of sexual intercourse with any other animal.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"228","title":"Compensation ordered to be paid","content":"A reasonable compensation\nshall be ordered to be paid to the victim of any offe nce referred to in\nthis Chapter other than the offences under Sections 220 and 226.","children":[]},{"tier":2,"nodeType":"rule","identifier":"229","title":"Statute of limitation","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"There shall be no statute of limitation for\nmaking a complaint in relation to the case of any offence under\nSection 220.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"No complaint shall lie after the expiry of one year from\nthe date of commission of any of the offences under Sections 219,\n221, 222, 223, 224 and 225 and sub -section (3) of Section 226, and\nafter the expiry of three months fr om the date of knowledge of\ncommission of any of the other offences under this Chapter.\nProvided that where the offence is committed against a person\nheld in detention, taken into control, kidnapped or taken hostage, no\ncomplaint shall lie after the expiry of three months from the date of\nrelease from such detention, control, kidnapping or hostage-taking.","children":[]}]}]},{"tier":1,"nodeType":"chapter","identifier":"Chapter-19","title":null,"content":"Offence Relating to Medical Treatment","children":[{"tier":2,"nodeType":"rule","identifier":"230","title":"Prohibition of conducting medical treatment by person who has","content":"not obtained licence: (1) No person, other than a person who has,\nupon having acq uired the specified educational qualification in\nmedicines, obtained from the lawful competent authority a licence\nfor medical treatment, shall provide medical services to, carry out\nsurgery on any organ of human body of, administer or prescribe any\nkind o f drug to, or otherwise conduct medical treatment of, any\nperson.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"Notwithstanding anything contained in sub -section (1),\nnothing shall bar a person who has gained knowledge on medical\ntreatment from a long experience from administering, with due care,\nsuch drug of general nature to a patient suffering from a minor\ndisease as not causing any specific adverse impact on any human\norgan of such patient, or conducting medical treatment by\nconducting operation of a minor wound, ecthyma.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"A person who com mits, or causes to be committed, the\noffence referred to in sub-section (1) shall be liable to a sentence of\nimprisonment for a term not exceeding three years and a fine not\nexceeding thirty thousand rupees.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"The offender shall be liable to the sentence of\nimprisonment for life where any act of providing medical service,\nconducting surgery or administering drug in contravention of sub -\nsection (1) causes the death of any person, and to a sentence of\nimprisonment for a term not exceeding fifteen years wher e such act\ncauses grievous hurt.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"231","title":"Prohibition of conducting medical treatment maliciously","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No\nperson shall, with the intention of causing death of, or grievous hurt\nto, another person, carry out his or her treatment, conduct one type of\nmedical treatment of him or her instead of another type of treatment\nas required, or administer, or prescribe for administration of, any\ndrug to him or her knowingly or having reason to believe that the\nadministration or prescription of such drug may cause death of , or\ngrievous hurt, to him or her or conduct surgery on one organ of\nhuman body of him or her instead of another organ as required or\nmake such organ dysfunctional or separate such organ from the\nhuman body, or cause the commission of any of such acts.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) shall be liable to the following\nsentence:\n(a) The same sentence as imposable for murder, in the case\nof causing the death of any person,\n(a) The same sentence as imp osable for grievous hurt, in\nthe case of causing grievous heart to any person.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"232","title":"Prohibition of conducting medical treatment by recklessness or","content":"negligence: (1) No person authorized under law to conduct medical\ntreatment shall, in conducting medical trea tment of any one, conduct\nsuch treatment, administer any drug or prescribe for the\nadministration of drug to him or her in a reckless or negligent\nmanner, without taking adequate care or precaution.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"Where any act referred to in sub -section (1) causes\ndeath of or grievous hurt to any one, the offender shall be liable to a\nsentence of imprisonment for a term not exceeding five years and a\nfine not exceeding fifty thousand rupees if the death or grievous hurt\nhas been caused from a reckless act and to a se ntence of\nimprisonment for a term not exceeding three years and a fine not\nexceeding thirty thousand rupees if the death or grievous hurt has\nbeen caused from a negligent act.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"233","title":"Prohibition of carrying out experiment on human body without","content":"consent: (1) N o person authorized under law to conduct medical\ntreatment shall, in carrying out an experiment of any method relating\nto medical treatment, surgery or drug on the human body, carry out\nsuch experiment, without obtaining consent of the concerned person ,\nand, in the case of a child or person of unsound mind, without\nobtaining consent of his or her father, mother or guardian, and\nwithout giving information thereof to such person, father, mother or\nguardian.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"Any experiment referred to in sub -section (1) shall be\ncarried out carefully, having regard to, inter alia, the possible effects\nof such method, surgery or drug on human body.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"No person shall carry out physical examination of or\nalter any organ of any one, or cause the commission of such act, with\nintention to get any undue economic benefit or to breach the privacy\nof a woman or with any other intention.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"A person who carries out, or causes to be carried out,\nany experiment in contravention of sub-section (1), (2) or (3) shall be\nliable to a s entence of imprisonment for a term not exceeding three\nyears and a fine not exceeding thirty thousand rupees.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"The offender shall be liable to the same sentence as\nimposable for murder if the offence referred to in sub-section (1), (2)\nor (3) causes th e death of any one and to the same sentence as\nimposable for grievous hurt if such offence causes grievous hurt to\nany one.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"234","title":"Prohibition of selling dangerous drug","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person authorized to\nsell medicines as per law shall, without prescription of th e person\nauthorized under law to carry out treatment as per law, sell or\ndistribute any narcotic, toxic or dangerous drug that may cause\nserious impact on human body.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committed , the\noffence referred to in sub -section (1) shall be liable to a sentence of\nimprisonment for a term not exceeding two years or a fine not\nexceeding twenty thousand rupees or both the sentences.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"235","title":"Prohibition of adulteration of drugs or sale of adulterated drugs","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall knowin gly adulterate any drug in such a manner\nas to void or lessen or change the efficacy of such drug or make it\nnoxious or sell such adulterated drug or any other thing saying that it\nis a drug or issue such drug or thing to any one for treatment or\nadminister, or cause to be administered, such drug to any one.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits the offence referred to in sub-\nsection (1) shall be liable to the following sentence:\n(a) The same sentence as imposable for murder, in\nthe case of death caused from the consu mption of\nsuch drug,\n(b) The same sentence as imposable for attempted\nmurder, in the case of danger or likelihood of\ndanger to cause death caused from the\nconsumption of such drug,\n(c) A sentence of imprisonment for a term not\nexceeding ten years and a fin e not exceeding one\nhundred thousand rupees, in the case of any\ngrievous hurt or deterioration or deprivation of\npower of any organ of the body caused from the\nconsumption of such drug,\n(d) A sentence of imprisonment for a term not\nexceeding five years and a f ine not exceeding\nfifty thousand rupees in cases other than that\nreferred to in clause (a), (b), or (c).","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"236","title":"Prohibition of selling, distributing date-expired drugs or without","content":"taking precaution: (1) No person shall sell any drug required to be\nused within a certain time period after the expiry of such date or sell,\ndistribute any drug without taking any specific precaution if such\nprecaution must be taken in the sale or distribution of such drug.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) shall be liable to a sentence of\nimprisonment for a term not exceeding one year and a fine not\nexceeding ten thousand rupees.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"237","title":"Prohibition of selling, distributing of drug as a different drug","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person authorize d to sell or distribute any drug under law\nshall, while so selling or distributing the drug, sell or distribute a\ndrug of one type as a drug of another type knowingly or having\nreasonable reason to know that such drug is materially a different\ntype of drug.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) shall be liable to a sentence of\nimprisonment for a term not exceeding two years or a fine not\nexceeding twenty thousand rupees or both the sentences.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"238","title":"Prohibition of giving false report","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person licensed under\nlaw to conduct a pathological test of human blood, urine, sputum etc.\nshall give a fake or false report while conducting such test or give a\nreport stating the facts different than that found from the test.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) shall be liable to a sentence of\nimprisonment for a term not exceeding three years and a fine not\nexceeding thirty thousand rupees.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"Where the consumption of any drug prescribed to,\nconduction of a surgery on, or treatment of, a person on the basis of\nthe report referred to in sub -section (1) causes the death of or any\ngrievous hurt to such person, the person giving such report shall be\ndeemed to be the offender.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (3) shall be liable to the same\nsentence as imposable for murder, in the case of causing death of,\nand to the same sentence as imposable for griev ous hurt, in the case\nof causing grievous heart to, any person.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"239","title":"Compensation to be paid","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"Where the death of, or grievous hurt\nto, or other harm, injury or damage to, any person is caused from the\ncommission of an y offence referred to in this Chapt er, reasonable\ncompensation shall be ordered to be paid by the offender to the\nconcerned victim and to his or her successor if the victim is dead.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"240","title":"Statute of limitation","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"There shall be no statute of limitation for\nfiling a complaint if death is ca used from any of the acts referred to\nin sub -section (4) of Section 230, Section 231, Section 232, sub -\nsection (4) of Section 233, Section 235, and sub -section (4) of\nSection 238.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"No complaint shall lie after one year from the date of\nknowledge of commission of the offence under sub -section (1) of\nSection 230, and after six months from the date of commission of\nany of the other offences under this Chapter.","children":[]}]}]},{"tier":1,"nodeType":"chapter","identifier":"Chapter-20","title":null,"content":"Offences Relating to Theft and Robbery","children":[{"tier":2,"nodeType":"rule","identifier":"241","title":"Prohibition of theft","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No perso n shall commit, or cause to be\ncommitted, theft.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"For the purposes of sub -section (1), a person who\ndishonestly takes any property under the ownership, possession,\ncontrol or custody of another person out of such ownership,\npossession, control or custod y or moves such property without that\nother person's consent, with the intention of owning, using or\nenjoying it, shall be considered to commit theft.\nExplanation: For the purposes of this Section,-\n(a) The term \"c onsent\" means the consent given in writing\nor orally or expressed by conduct.\n(b) Consent by a child who has not attained eighteen years\nof age or a person of unsound mind shall not be\nconsidered to be consent.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"242","title":"Punishment for theft","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"A person who commits, or causes to be\ncommitted, theft in any of the following circumstances shall be liable\nto a sentence of imprisonment from a term of two to seven years and\na fine of twenty thousand to seventy thousand rupees:\n(a) In the case of theft of any government or public\nproperty or property of any religious place or temple,\n(b) In the case of theft of any property, upon administering\nliquor or narcotics to, or otherwise making unconscious,\nany person,\n(c) In the case of theft of any property, upon taking\nadvantage of earthquake, fire, flood, riot or similar other\nsituation of crisis or any accident,\n(d) In the case of theft of any property of the office or\nperson whose service one is engaged in,\n(e) In the case of theft on a vehicle used for the conveyance\nof human persons or goods.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committed, theft\nin any circumstance other than that referred to in sub -section (1)\nshall be liable to a sentence of imprisonment for a term not\nexceeding three years and a fine not exceeding thirty thousand\nrupees.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"243","title":"Prohibition of burglary (Nakabajani)","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall commit,\nor cause to be committed, burglary.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"For the purposes of sub -section (1), a person shall be\nconsidered to commit burglary if he or she commits theft in a house\nby entering into the house by bre aking its main gate or by using any\npassage, place, method or means other than the main gate, or after\ncommitting theft, he or she quits, or attempts to quit, by breaking its\nmain gate or by using any passage, place, method or means other\nthan the main gate.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"A person who commits the offence referred to in sub-\nsection (1) shall be liable to a sentence of imprisonment for a term of\nthree to five years and a fine of thirty thousand to fifty thousand\nrupees.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"244","title":"Prohibition of robbery","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall commit, or cause to be\ncommitted, robbery.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person shall be deemed to commit robbery if he or\nshe:\n(a) causes or attempts to cause to any person death or hurt\nor restraint or obstruction or fear or intimidation of\ninstant death or of instant hurt, in order to the\ncommitting of theft or in committing the theft or in\ncarrying away property obtained by the theft or to the\nescaping of arrest after the commission of the theft or\ncommits theft carrying a deadly weapon,\n(b) obtains any money or economic ben efit through\ncriminal extortion by putting any person in fear of\ninstant death or of instant or of instant restraint,\n(c) commits theft by waiting near or on way, road, lonely\nplace or forest or show of fear or intimidation , using or\nthreatening to use a deadly weapon,\n(d) commits theft in a group of three or more persons.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"A person who commits the offence referred to in sub-\nsection (1) shall be liable to the following sentence:\n(a) A sentence of imprisonment for a term of seven to\nfourteen years and a fine of seventy thousand to one\nhundred forty thousand rupees, in the case of the\noffence referred to in clause (a) or (b) of sub-section (2),\n(b) A sentence of imprisonment for a term of five to ten\nyears and a fine of fifty thousand to one hundred\nthousand rupees, in the case of the offence referred to in\nclause (c) or (d) of sub-section (2).","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"245","title":"Prohibition of movement carrying tools to be used in commission","content":"of theft: (1) No person shall, with the intention of committing theft\nor robbery, move around or enter into or attempt to enter into the\nhouse of any person carrying instruments such as any tool, object ,\narms, duplicate key, gloves and ladder that may be used in the\ncommission of theft or robbery.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who so moves, enters into or attempts to enter\ninto as referred to in sub -section (1) shall, unless otherwise proved,\nbe considered to have moved, entered into or attempted to enter into,\nwith the intention of committing theft.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) shall be liable to a sentence of\nimprisonment for a term not exceeding one year or a fine not\nexceeding ten thousand rupees or both the sentences.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"246","title":"Prohibition of pickpocketing","content":"( 1) No person shall commit, or\ncause to be committed, pickpocketing.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"For the purposes of sub -section (1), a person who steals\ncash or property from the pocket of another person who is walking\non foot, traveling on a vehicle or staying in a public place or from his\nor her accompanying purse, bag or means of any other kind, with or\nwithout notice of such other person, shall be considered to commit\npickpocketing.\nProvided that where a person pick -pockets a cash amount of\nmore than ten thousand rupees or property valued at more than ten\nthousand rupees, the person shall be considered to commit the\noffence referred to in Section 241.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"A person who commits the offence referred to in sub-\nsection (1) shall be liable to the following sentence:\n(a) A sentence of imprisonment for a term not exceedi ng\none month or a fine equal to the claimed amount or both\nthe sentences, in the case of the commission of\npickpocketing for the first time,\n(b) A sentence of imprisonment for a term not exceeding\ntwo months or a fine equal to the claimed amount or\nboth the sentences, for each instance from the second\ntime onwards.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"247","title":"Claimed a mount to be recovered","content":"The claimed amount, if any,\ninvolved in the offence referred to in this Chapter shall be forfeited\nfrom the offender of such offence and paid to the owner of that\nproperty. If the offender has already spent the property formed of the\nclaimed amount, property equal to the value of claimed amount shall\nbe ordered to be paid to the owner.","children":[]},{"tier":2,"nodeType":"rule","identifier":"248","title":"Statute of limitation","content":"No complaint shall lie after the expiry of three\nmonths from the date of commission of the offence in the case of any\nof the offences under Sections 245 and 246 and after six months\nfrom the date of knowledge of commission of the offence in the case\nof any of the other offences under this Chapter.","children":[]}]},{"tier":1,"nodeType":"chapter","identifier":"Chapter-21","title":null,"content":"Offences Relating to Cheating, Criminal Breach of Trust and\nExtortion","children":[{"tier":2,"nodeType":"rule","identifier":"249","title":"Prohibition of cheating","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall commit, or cause to be\ncommitted, cheating.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"For the purposes of sub -section (1), a person who\ndishonestly causes any kind of loss, damage or injury to another\nperson whom he or she makes believe in some matter or to any other\nperson or obtains any benefit for him or her or any one else by\nomitting to do as per such belief or by inducement, fraudulent,\ndishonest or otherwise deceptive act or preventing such other person\nfrom doing any act shall be considered to commit cheating.\nExplanation: Where the victim of cheating has got a deed\nexecuted by the cheater, the deed shall apply to that matter.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"A person who commits the off ence referred to in sub-\nsection (1) shall be liable to the following sentence:\n(a) A sentence of imprisonment for a term not exceeding\nten years and a fine not exceeding one hundred\nthousand rupees, in the case of cheating the Government\nof Nepal or any bo dy under full or majority ownership\nor control of the Government of Nepal, except in cases\nof corruption,\n(b) A sentence of imprisonment for a term not exceeding\nfive years and a fine not exceeding fifty thousand\nrupees, in the case of cheating by lying on e's name,\ndesignation, title, qualification,\n(c) A sentence of imprisonment for a term not exceeding\nseven years and a fine not exceeding seventy thousand\nrupees in the cases of any kind of cheating other than\nthat referred to in clause (a) or (b).","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"A sentence of imprisonment for a term not exceeding\none year, in addition to the sentence set forth in sub-section (3), shall\nbe imposed in the case of cheating a child, person of unsound mind,\nhelpless, illiterate or person above seventy-five years of age.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"250","title":"Prohibition of causing difference in bid or contract","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No\nperson who has undertaken the responsibility of carrying out any\nconstruction related work or other work or other person who acts on\nhis or her behalf shall, with dishonest intent, carry out, or cause to be\ncarried out, the construction or other work, by not using the materials\nof the specified standards or quality or by altering the quantity of the\nmaterials to be used or otherwise using materials not conforming to\nthe specified quality.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits the offence referred to in sub-\nsection (3) shall be liable to a sentence of imprisonment for a term\nnot exceeding ten years and a fine not exceeding one hundred\nthousand rupees.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"No person who has undertaken the responsibility of\nsupplying any materials, goods or services or other person who acts\non his or her behalf shall, with dishonest intent, supply materials,\ngoods or services falling short of the quality or quantity or otherwise\nprovide materials, goods or services not confor ming to the specified\nquality.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (3) shall be liable to a sentence of\nimprisonment for a term not exceeding five years and a fine not\nexceeding fifty thousand rupees.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"251","title":"Prohibition of criminal misappropriation of property","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No\nperson shall make, or cause to be made, criminal misappropriation of\nproperty.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"For the purposes of sub -section (1), a person who does\nany of the following acts shall be considered to commit criminal\nmisappropriation of property:\n(a) To dishonestly possess and use, cause loss and damage\nto or misappropriate a property belonging to another\nperson or rent, sell or dispose it witho ut consent of that\nother person.\nProvided that if the real owner of an adjoining\nland uses the property belonging to another person, by\nmistakenly making normal encroachment of the\nboundary, he or she shall not be considered to commit\nthe offence referred to in this clause.\n(b) To dishonestly appropriate or otherwise co nvert any\nproperty not in the possession of any other person to his\nor her own use, knowing or having the means of\ndiscovering the owner of such property, or without\nreturning such property to such owner within a\nreasonable time, or without giving notice to the owner to\nclaim the property or without waiting the owner of such\nproperty until a reasonable time.\nProvided that where the finder in good faith\nappropriates a property to his or her own use when the\nowner of the property is not discovered despite\nreasonable efforts or the owner does not claim the\nproperty within a reasonable time after the giving of\nnotice, he or she shall not be considered to commit the\noffence referred to in this Section.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"A person who commits , or causes to be committed, the\noffence referred to in sub section (1) shall be liable to the following\nsentence:\n(a) A sentence of imprisonment for a term not exceeding\nthree years or a fine not exceeding thirty t housand\nrupees or both the sentences, in the case of criminal\nmisappropriation of property which was in the\npossession of a deceased person at the time of that\nperson's demise and has not since been in the possession\nof his or her legal successor , or criminal\nmisappropriation of property belonging t o a child, a\nperson of unsound mind due to mental or physical\nillness, or a person above seventy-five years of age,\n(b) A sentence of imprisonment for a term not exceeding\none year or a fine not exceeding ten t housand rupees or\nboth the sentences, in the case of criminal\nmisappropriation of property in cases other than that set\nforth in clause (a).","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"If any property subjected to criminal misappropriation\nunder this Section is in a returnable condition, the person who so\nmisappropriates shall return the property to the concerned owner o r\nto his or her immediate successor if the owner is dead.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"252","title":"Prohibition of criminal breach of trust","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall\ncommit, or cause to be committed, criminal breach of trust.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"For the purposes of sub -section (1), a person who does\nany of the following acts shall be considered to commit, or cause the\ncommission of, criminal breach of trust:\n(a) To dishonestly appropriate or otherwise convert to his\nor her own use other's property which is under his or her\ncustody or protection or to dishonestly a ppropriate such\nproperty in his or her own use, or allow such property to\nbe used by, or dispose, or cause the disposal, of such\nproperty to, another person, in violation of any contract,\ndeed of conditions or law concerning the use of such\nproperty,\n(b) To cause any loss, damage or injury by a person, who is\nentrusted with responsibility or has lawful duty of doing\nany work or transaction of another person or who acts as\nan agent of another in relation to any work or\ntransaction, to that other person by do ing any act in\nviolation of his or her duty with the intention of causing\nbenefit to himself or herself or any one else.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) shall be liable to the following\nsentence:\n(a) A sentence of imprisonment for a term not exceeding\nfive years and a fine not exceeding fifty thousand\nrupees, in the case of the commission of criminal breach\nof trust by a person in the capacity of manager, director,\nemployee or agent of any or ganization or by a person\nentrusted with the responsibility of carrying a property\nfrom one place to another or keeping it safely in a\nwarehouse or any other place or with a legal duty to do\nso,\n(b) A sentence of imprisonment for a term not exceeding\nthree years or a fine not exceedin g thirty thousand\nrupees or both the sentences, in the case of the\ncommission of criminal breach of trust by any person\nother than that set forth in clause (a).","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"253","title":"Prohibition of extortion","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall commit, or cause to be\ncommitted, extortion.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"For the purposes of sub -section (1), a person who puts\nany person in fear or terror of any injury to that person or to any\nother person and dishonestly takes any benefit from that person for\nhimself or herself or any other person or induces that person to do, or\nprevents that person from doing, any act with the intention of taking\nsuch benefit shall be considered to commit extortion.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"A person who commits the offence referred to in sub-\nsection (1) shall be liable to the following sentence:\n(a) A sentence of imprisonment for a term not exceeding\nseven years and a fine not exceeding seventy thousand\nrupees, in the case of putting a person in fear or terror of\ndeath, grievous hurt or serious injury, with the intention\nof committing extortion,\n(b) A sentence of imprisonment for a term not exceeding\nthree years and a fine not exceeding thirty thousand\nrupees, in the case of commission of extortion by\nshowing fear or terror with the intention of causing any\ndamage to any other person's business or making a false\naccusation in respect of such person's character,\n(c) A sentence of imprisonment for a term not exceeding\none year or a fine not exceeding ten thousand rupees or\nboth the sentences, in the case of the commission of\nextortion in cases other than that set forth in clause (a)\nor (b).","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"254","title":"Compensation","content":"Where any injury or damage is caused to any\nperson from the commission of the offence referred to in this\nChapter, the claimed amount, if set out, and a reasonable\ncompensation, if the claimed amount is not set out, shall be ordered\nto be paid by the offender to the victim.","children":[]},{"tier":2,"nodeType":"rule","identifier":"255","title":"Statute of limitation","content":"No complaint shall lie after the expiry of one\nyear from the date of knowledge of commission of any offence under\nthis Chapter.","children":[]}]},{"tier":1,"nodeType":"chapter","identifier":"Chapter-22","title":null,"content":"Offences Relating to Currency","children":[{"tier":2,"nodeType":"rule","identifier":"256","title":"Prohibition of counterfeiting currency","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall\ncounterfeit, or attempt to counterfeit, any currency.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) shall be liable to a sentence of\nimprisonment for a term of five to ten years and a fine of fifty\nthousand to one hundred thousand rupees, having regard to the\nquantity and value of the currency counterfeited.\nExplanation: For the purpose of this Chapter,-\n(a) “currency” means any kind of currency note, postal\norder, postal note, money order, cheque, draft, traveler's\ncheque, letter of credit, letter of exchange, bond and\ncredit card , and this term also includes such other\nsimilar kind of monetary instrument as specified by the\nBank, as required, by publishing and circulating a\npublic notice.\n(b) \"counterfeit currency\" means a currency which is so\nforged in an unauthorized manner or counterfeit as\nresembling or having reason to believe it to be a\ncurrency issued by the Government of Nepal or Nepal\nRastra Bank or foreign government or competent\nforeign body.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"257","title":"Prohibition of using counterfeit currency","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall,\nwith the intention of using as genuine, purchase, sell, export, import,\ntransact, or use as genuine, any counterfeit currency or attempt to do\nsuch act or possess such currency.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits the offence referred to in sub-\nsection (1) shall be liable to a sentence of imprisonment for a term\nnot exceeding seven years and a fine not exceeding seventy thousand\nrupees.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"258","title":"Prohibition of making, possessing or repairing instruments for","content":"counterfeiting currency: (1) No person shall make, repair,\npurchase, sell, give, take, export, import or possess any instrument or\nother material knowing that or having a reasonable reason to believe\nthat it is intended to be used in or for forging or counterfeiting\ncurrency.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) shall be liable to a sentence of\nimprisonment for a term not exceeding seven years and a fine not\nexceeding seventy thousand rupees.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"259","title":"Prohibition of making currency contrary to standards","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No\nauthority or person entrusted by the law in force to make currency\nshall know ingly make currency in contravention of the standards\nspecified by law, make currency in violation of the terms and\nrestrictions applicable to the making of currency, make currency in\nexcess of the quantity specified or do any act with the intention of\nmaking currency with such deviation or cause benefit to himself or\nherself or any other person from such act or facilitate such act.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) shall be liable to a sentence of\nimprisonment for a term not exceeding seven years and a fine not\nexceeding seventy thousand rupees.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"260","title":"Prohibition of taking outside currency making instruments","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall, except with the order of the competent authority\nunder law, take any currency making machinery, equipment or other\ninstrument out of the place where currency is made.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) shall be liable to a sentence of\nimprisonment for a term not exceeding five years and a fine not\nexceeding fifty thousand rupees.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"261","title":"Prohibition of diminishing weight or altering form of currency","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall diminish the weight of metallic currency or alter\nthe composition of metallic element or export, i mport or possess\ncurrency, by causing the currency of one type to appear like the\ncurrency of another type, with the intention of using it as genuine or\nknowing that it may be used as genuine.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) shall be liable to a sentence of\nimprisonment for a term not exceeding five years and a fine not\nexceeding fifty thousand rupees.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"262","title":"Prohibition of bringing prohibited currency into use","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No\nperson shall bring into use, exchange or possess a currency in use but\ncirculation of which has been banned by order of the competent\nauthority under law, in violation of such order.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) shall be liable to a sentence of\nimprisonment for a term not exceeding one year or a fine not\nexceeding ten thousand rupees or both the sentences, and the\ncurrency so brought into use, exchanged or possessed shall also be\nforfeited.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"263","title":"Prohibition of burning , tearing, melting bank notes or coins or","content":"writing on bank notes: (1) No person shall, except with the order of\nthe competent authority, burn a coin or bank note tendered as\ncurrency or so melt or tear it that it is incapable of being used.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"No person shall write on or cross off bank notes.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) or (2) shall be liable to a\nsentence of imprisonment for a term not exceeding three months and\na fine not exceeding five thousand rupees.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"264","title":"Prohibition of misusing torn bank notes","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person who is\nentrusted by order of the competent authority under law with a duty\nof burning or disposing off the torn notes held to be burnt or\ndisposed of because such bank notes tender ed as currency are worn\nand torn or letters, signs or sizes are unrecognizable or such notes\ncannot be brought in to use for any other reason shall bring in to use\nsuch bank notes or refrain from burning or disposing of such notes or\ngive them to another person dishonestly intending to obtain any kind\nof benefit therefrom.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) shall be liable to a sentence of\nimprisonment for a term not exceeding three years and a fin e not\nexceeding thirty thousand rupees.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"265","title":"Forfeiture","content":"The currency, machine, equipment or tools used in, and\nmaterials related to, the commission of any offence under this\nChapter shall be forfeited","children":[]},{"tier":2,"nodeType":"rule","identifier":"266","title":"Statute of limitation","content":"No complaint shall lie af ter the expiry of one\nyear from the date of knowledge of commission of any offence under\nthis Chapter.","children":[]}]},{"tier":1,"nodeType":"chapter","identifier":"Chapter-23","title":null,"content":"Offences Relating to Stamps","children":[{"tier":2,"nodeType":"rule","identifier":"267","title":"Prohibition of counterfeiting stamps or using counterfeit stamps","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall, with the intention of using as genuine,\ncounterfeit, attempt to counterfeit a stamp, purchase, sell, exchange,\nexport or import a counterfeit stamp, or use or attempt to use as\ngenuine, or possess, such stamp.\nExplanation: For the purposes of this Chapter,-\n(a) \"stamp\" means a postal stamp or other revenue stamp\nto be affixed to a document , and this term also includes\nthe sign of a stamp affixed to or printed on an envelope,\npost letter or any other object or a sticker to be used for\nthe purpose of stamp.\n(b) \"counterfeit stam p\" means a forged stamp made in an\nunauthorized manner so that it resembles a stamp\nreferred to in clause (a) , and this term also includes a\nstamp that has once been used.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) shall be liable to a sentence of\nimprisonment for a term not exceeding five years and a fine not\nexceeding fifty thousand rupees.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"268","title":"Prohibition of purchasing, selling, repairing instruments for","content":"counterfeiting stamps: (1) No person shall make , repair, purchase,\nsell, exchange, possess any machinery or other instrument knowing\nor having reasonable ground to believe that it is intended to be used\nfor the purpose of counterfeiting any stamp.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) shall be liable to a sentence of\nimprisonment for a term not exceeding five years and a fine not\nexceeding fifty thousand rupees.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"269","title":"Prohibition of re -using stamp used before","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person,\nknowing that any stamp is a stamp already used before, shall re -use\nas genuine such stamp or erase, efface or remove any seal or mark\nput or impressed upon any stamp with the intention of using it as\ngenuine or attempt to do so.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committ ed, the\noffence referred to in sub-section (1) shall be liable to a sentence of\nimprisonment for a term not exceeding one year or a fine not\nexceeding ten thousand rupees or both the sentences.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"270","title":"Prohibition of removing from public document stamp used f or","content":"it: (1) No person shall remove, or attempt to remove, from a public\ndocument a stamp which has been used for it.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) shall be liable to a sentence of\nimprisonment for a term not exceeding six months or a fine not\nexceeding five thousand rupees or both the sentences.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"271","title":"Forfeiture","content":"Any stamp, t ool, instrument or other material related to\nthe commission of any offence referred to in this Chapter shall be\nforfeited.","children":[]},{"tier":2,"nodeType":"rule","identifier":"272","title":"Statute of limitation","content":"No complaint shall lie after the expiry of one\nyear from the date of knowledge of commission of any offence under\nthis Chapter.","children":[]}]},{"tier":1,"nodeType":"chapter","identifier":"Chapter-24","title":null,"content":"Offences Relating to Weights and Measures","children":[{"tier":2,"nodeType":"rule","identifier":"273","title":"Prohibition of making or using fals e instrument for weighing","content":"and measuring: (1) No person shall make, or cause to be made, any\ninstrument for weighing, measuring or determining quality standards\nin a manner that it does not conform to the specified standards or\nknowingly use as genuine any instrument so made for weighing,\nmeasuring or determining quality standards or possess or sell such\ninstrument which is intended to be so used or make false seal or\nmark to be affixed to such instrument or tamper the seal or mark\naffixed to the instrument for weigh ing, measuring or determining\nquality standards or manipulate, with the help of any other\ninstrument, the weighing, measuring or quality determining ability of\nsuch instrument or affix a false seal or mark to such instrument or,\nby way of any othe r means, make any weight or measure different\nfrom the prevalent one.\nExplanation: For the purposes of this Section, the term\n\"instrument for weigh ing, measuring or determining quality\nstandards\" means an instrument in use under the law to measure or\ndetermine the unit, quality or quantity of any good or service or\npurity or standards of such good or service or unit of any thing.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) shall be liable to a sentence of\nimprisonment for a term not exceeding three years and a fine not\nexceeding thirty thousand rupees.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"Any instrument made or brought into use under sub -\nsection (1) and tool for maki ng or repairing such instrument shall\nalso be forfeited.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"274","title":"Prohibition of fraudulent use of instrument for weigh ing,","content":"measuring or determining quality standards: (1) In using the\ninstrument for weighing, measuring or determining quality standards\nin the course of any business, transaction or trade, no person shall\nfraudulently use such instrument in a manner to be different from the\nweight, measure or standard specified for use or, with the help of any\nother instrument or means, cause adverse effect to the weighing,\nmeasuring or quality determination by such instrument as per t he\nprevailing weights and measures.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) shall be liable to a sentence of\nimprisonment for a term not exceeding three years and a fine not\nexceeding thirty thousand rupees.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"275","title":"Statute of limitation","content":"No complaint shall lie in relation to any\noffence under this Chapter after the expiry of three months from the\ndate of knowledge of commission of such offence.","children":[]}]},{"tier":1,"nodeType":"chapter","identifier":"Chapter-25","title":null,"content":"Offences Relating to Documents","children":[{"tier":2,"nodeType":"rule","identifier":"276","title":"Prohibition of forgery","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall commit, or cause to be\ncommitted, forgery.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"For the purposes of sub-section (1), a person who makes\na false document or false electronic record or a part or portion of a\ndocument or electronic record, with intent to caus e any harm, injury\nor damage to the public or to any person or to render any benefit to\nthe person himself or herself or to any person shall be considered to\ncommit forgery.\nExplanation: For the purposes of this Section,-\n(a) \"document\" means signature, th umb impression,\nseal affixed on any document and the figure,\nword, date or any other content set forth in any\ndocument.\n(b) \"making a false document\" means any of the\nfollowing acts:","children":[]},{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"to dishonestly prepare a document or part\nof a document, make or tran smit an\nelectronic record, archive digitals in an\nelectronic record, with the intention of\ncausing it to be believed that such\ndocument was made, written, signed or\nsealed by the person or authority who has\nnot actually made, written, signed or sealed\nthe document,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"to, without lawful authority or dishonestly,\nadd or delete any content to or from, strike\nout, change or otherwise alter or make\nunclear any content of a document or\nelectronic record,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"to cause any person to make, sign, seal, or\nalter any content of, a document knowing\nthat such person by reason of being of\nunsound mind due to mental illness or\nintoxication of liquors or narcotics or by\nreason of deception practiced on him or her\ncannot know the meaning of any contents\nset down in the document,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"to prepare or use any envelope, paper\nsigned and delivered or any seal delivered\nfor a work or purpose other than that for\nwhich such envelope, paper or seal was\nsigned, and delivered.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"A person who commits the offence referred to in\nsub-section (1) shall be liable to the following sentence:\n(a) A sentence of imprisonment for a term not\nexceeding ten years and a fine not exceeding one\nhundred thousand rupees, in the case of forgery of\na document authenticated by the President,\n(b) A sentence of imprisonment for a term not\nexceeding eight years and a fine not exceeding\neighty thousand rupees, in the case of forgery of a\njudgment or order of a court,\n(c) A sentence of imprisonment for a term not\nexceeding seven years and a fine not exceeding\nseventy thousand rupees, in the case of forgery of\na government or public document other than that\nreferred to in clauses (a) and (b),\n(d) A sentence of imprisonment for a term not\nexceeding five years and a fine not exceeding\nfifty thousand rupees, in the c ase of forgery of a\ndocument other than that referred to in clauses\n(a), (b) and (c).","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"A person who has already disposed of property which\nhe or she has obtained by committing forgery shall be liable to an\nadditional fine equal to the claimed amount, i n addition to the\nsentence referred in sub-section (3).","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"Where a person obtains any property by committing\nforgery, the person shall return such property to the concerned\nowner; and in the event that such property has already been disposed\nof, the claimed amount of such property shall be caused to be\nrecovered to the owner from any other property of the offender.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"277","title":"Prohibition of possessing or using as genuine a forged document","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall, knowingly or having a reasonable reason to\nbelieve that a document is a forged one, possess such document, with\nintent to dishonestly use such document as genuine.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) shall be liable to a sentence of\nimprisonment for a term not exceeding three years and a fine not\nexceeding thirty thousand rupees.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"A person who uses as genuine any document which he\nor she knows or has a reasonable reason to believe to be a forged\ndocument shall be liable to the sentence in th e same manner as if he\nor she had forged such document.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"278","title":"Prohibition of making instrument for making forged document","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall make, repair, purchase, exchange or possess any\nseal or other instrument for making a forged document, with the\nintention of using it in establishing or making a forged document, or\nknowingly or having a reasonable reason to believe that it may be\nused in such act.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) shall be liable to a sentence of\nimprisonment for a term not exceeding four years and a fine not\nexceeding forty thousand rupees.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"279","title":"Prohibition of committing fraud","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall commit, or\ncause to be committed, fraud.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"For the purposes of sub -section (1), a person who, with\nintent to disentitle any one, expire the statute of limitation or\nappointed date for presence of, or cause, in any manner, loss,\ndamage, injury or benefit to, any one, knowingly does an act stating\nthat any thing has happened or been done which has not happened or\nbeen done in fact or makes or signs a document containing a false\ndate, figure or content or causes another person to sign such\ndocument or showing that he or she has entitlement in any thing in\nwhich he or she has no such entitlement in fact, which does not\nconstitute the offence of forgery, shall be considered to commit the\noffence of fraud.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub -section (1) shall be liable to a sentence of\nimprisonment for a term not exceeding three years or a fine not\nexceeding thirty thousand rupees or both the sentences.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"A person who has already disposed of property which\nhe or she has obtained by committing fraud shall be liable to an\nadditional fine e qual to the claimed amount, in addition to the\nsentence referred in sub-section (3).","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"Where a person obtains any property by committing\nfraud, the person shall return such property to the concerned owner;\nand in the event that such property has alread y been disposed of, the\nclaimed amount of such property shall be caused to be recovered to\nthe owner from any other property of the offender.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"280","title":"Prohibition of using as genuine a fraudulent document","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No\nperson shall, knowingly or having a reason to believe that a\ndocument is a fraudulent one, use such document as genuine.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) shall be liable to the sentence in\nthe same manner as if he or she had committed fraud.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"281","title":"Liable to punishment as accomplice","content":"A person who becomes a\nwitness to, or writes, a document knowing that the document is a\nforged one shall be considered as an accomplice of the offence of\nforgery.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"An accomplice referred to in sub -section (1 ) shall be\nliable to half the sentence set forth in sub-section (3) of Section 273.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"282","title":"Compensation ordered to be paid","content":"Where any loss or damage is\ncaused to any person from the commission of an y offence referred to\nin this Chapter, a reasonable compens ation shall be ordered to be\npaid by the offender to such person who has suffered such loss or\ndamage.","children":[]},{"tier":2,"nodeType":"rule","identifier":"283","title":"Statute of limitation","content":"No complaint shall lie , in relation to the\noffence of forgery of a public document after the expiry of two years\nfrom the dat e of knowledge of commission of such offence, and in\nrelation to any of the other offences under this Chapter, after the\nexpiry of six months from the date of knowledge of commission of\nsuch offence.","children":[]}]},{"tier":1,"nodeType":"chapter","identifier":"Chapter-26","title":null,"content":"Offences Relating to Criminal Trespass and Criminal Mischief","children":[{"tier":2,"nodeType":"rule","identifier":"284","title":"Prohibition of committing criminal trespass","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall\ncommit, or cause to be committed, criminal trespass into the property\nof another person.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"For the purposes of sub -section (1), a person who, with\nintent to do the following act, enters, in an unauthorized manner, and\nwhether doing manhandling or not, into a property owned or\npossessed by another person without obtaining such other person’s\npermission or enters into such property with such permission but\nremains in, or continues to occupy or use, that property with intent\nthereby to do any of such acts shall be considered to commit criminal\ntrespass:\n(a) Committing any offence, or\n(b) Intimidating, insulting or annoying the owner or\npossessor of the property.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"A person commits the offence referred to in sub-section","children":[]},{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"shall be liable to the following sentence:\n(a) In the case of a person who commits criminal trespass\nfor the purpose referred to in clause (a) of sub -section","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":", a sentence equal to the sente nce imposable for\nattempt to such offence,\n(b) In the case of criminal trespass into a government office\nor human dwelling house for the purpose referred to in\nclause (b) of sub -section (2), a sentence of\nimprisonment for a term not exceeding six months or a\nfine not exceeding five thousand rupees or both the\nsentences.\nExplanation: For the purposes of this Section,-","children":[]},{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"A place of temporary residence shall also be\nconsidered to be a house.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"Entry into, or use of, a way, passage, water\ncollection center, irrigation canal, graveyard,\ntemple that have been in public use for time\nimmemorial shall not be considered to be\ncriminal trespass.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"285","title":"Prohibition of committing criminal mischief","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall\ncommit, or cause to be committed, criminal mischief.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"For the purposes of sub -section (1), a person who does\nany of the following acts shall be considered to commit criminal\nmischief:\n(a) Destroying, or doing such act as to diminish the value,\nimportance or utility of, any government, public or\nprivate property, with the intention of causing any harm,\nloss or damage to the Government of Nepal, State\nGovernment or Local Level, any body corporate under\nfull or majority ownership or control of the Government\nof Nepal, State Government or Local Level or publ ic or\nany person, or knowing or having a reasonable reason to\nbelieve that such damage is likely to be caused, or\ncausing such damage by a negligent or reckless act,\n(b) Causing loss, damage or wrongful injury to, or doing\nany act that causes injury to, or knowingly causing any\nkind of obstruction, loss, damage or wrongful injury to\nthe utility of, any public or private sewerage, water\ncanal, drinking water pond, road, bridge or any means\nof communications or transportation and the like,\n(c) Destroying, removing, erasing or tampering any mark or\nsign fixed for public convenience, except for any act\ndone in pursuance of an order of the competent\nauthority, by spreading rumors or using any means of\ndeception,\n(e) Concealing, or dishonestly causing delay in the delivery\nof, any correspondence, notice, parcel or other object of\nanother person.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) shall be liable to the following\nsentence:\n(a) The sentence of imprisonmen t for life and a fine equal\nto the claimed amount, in the case of setting fire to, or\nusing explosives, in any national park or reserve or\nprotected zone, with the objective of destroying the\nexistence of species of any wildlife or flora or fauna\nprotected by the Government of Nepal or protected\npursuant to law, any historical or archeological\nmonument or statue included in the world heritage list,\nany site or museum in which objects of historical or\narcheological importance are kept, or any achieve where\nhistorical documents are kept, any military or para -\nmilitary house or place in which arms and ammunition\nof the army or police are stored, security press, mint,\nfactory, Nepal Rastra Bank's warehouse for bank note\nprinting or storing,\n(b) A sentence of imprisonment for a term of five to twelve\nyears and a fine equal to the claimed amount, in the case\nof criminal mischief committed by setting fire to, or\nusing explosives in, any historical, archeological or\nreligious monument or statue other than that referre d to\nin clause (a), any building containing documents of\npublic or governmental importance, any court\ncontaining money ( Tahabil), any constitutional body,\nany office of the Government of Nepal, State\nGovernment or Local Level or body under full or\nmajority ownership or control of the Government of\nNepal, State Government, or Local Level, or any office\nof foreign diplomatic mission or international or inter -\ngovernmental organization,\n(c) A sentence of imprisonment for a term not exceeding\nfour years and a f ine not exceeding forty thousand\nrupees, in the case of criminal mischief committed by\ndoing any act other than that referred to in clause (a) or\n(b), thereby causing injury to any public property,\n(d) A sentence of imprisonment for a term of two to five\nyears and a fine of twenty thousand to fifty thousand\nrupees, in the case of criminal mischief committed by\nsetting fire to or using explosives in any house, office or\nproperty of any person,\n(e) A sentence of imprisonment for a term not exceeding\nthree years and a fine not exceeding thirty thousand\nrupees in the case of criminal mischief committed by\ndoing any act other than that referred to in clause (a),\n(b), (c) or (d), thereby causing any loss, damage to any\nperson.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"Where any loss, damage is cau sed to any person by\nreason of the commission of the offence referred to in this Section, a\ncompensation equal to the claimed amount of such loss or damage so\ncaused shall be ordered to be paid by the offender to the victim of the\noffence.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"286","title":"Prohibition of committing larceny (looting)","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall\ncommit, or cause to be committed, larceny.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"For the purposes of sub -section (1), a person who does\nany act, other than an act that constitutes theft or cheating, by which\nhe or she otherwise snatches , whether forcibly or not, takes, whether\nby manhandling or fighting or giving threat thereof, or causes loss,\ndamage to any property which he or she has no right in or which is\nunder ownership, custody or control of another person, with the\nintention of s natching, taking, or causing loss, damage to, such\nproperty shall be considered to commit larceny.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"A person who commits the offence referred to in sub-\nsection (1) shall be liable to a sentence of imprisonment for a term\nnot exceeding three months or a fine not exceeding twenty -five\npercent of the claimed amount subjected to larceny or both the\nsentences, and the claimed amount subjected to larceny shall be\nordered to be paid by the offender to the victim.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"287","title":"Prohibition of acquiring property obtaine d by committing","content":"offence: (1) No person shall acquire, hold, purchase or sell any\nproperty knowing or having a reasonable reason to believe that such\nproperty has been obtained by committing an offence.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) shall be liable to a sentence of\nimprisonment for a term not exceeding five years or a fine not\nexceeding fifty thousand rupees or both the sentences.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"The property acquired, held, purchased or sold as set\nforth in sub -section (1) shall be returned to the owner of such\nproperty.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"288","title":"Statute of limitation","content":"A complaint in relation to an offence under\nSection 284 or 285 shall not be entertained after the expiry of six\nmonths from the date of commission of such offence, in relation to\nthe offence under Section 286, after the expiry of three months from\nthe date of commission of such offence, and in relation to any of\nother offences under this Chapter, after the expiry of three month s\nfrom the date of having kn owledge of the commission of such\noffence.","children":[]}]},{"tier":1,"nodeType":"chapter","identifier":"Chapter-27","title":null,"content":"Offences Relating to Animals and Birds","children":[{"tier":2,"nodeType":"rule","identifier":"289","title":"Prohibition of killing or beating cows or oxen","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall\ndo, or cause to be done, any act with the intention of killing, or\ncausing hurt to, any cow or ox.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"Where any act referred to in sub -section (1) causes the\ndeath of any cow or ox, the offender of such offence shall be liable to\na sentence of imprisonment for a term not exceeding three years.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"A person shall be liable to a sentence of impris onment\nfor a term not exceeding six months, if he or she causes grievous hurt\nto a cow or ox, and to a sentence of a fine not exceeding fifty\nthousand rupees if other hurt is caused.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"Notwithstanding anything contained in sub -section (1),\nif a person does any act necessary to protect from any injury likely to\nbe caused by any cow or ox to the body or life of the person or\nanother person and such act causes the death of, or any harm to, such\ncow or ox, the person shall not be considered to commit any of fence\nunder this Section.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"290","title":"Prohibition of cruel treatment to animals and birds","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No\nperson shall subject any animal or bird to torture by beating or\nhitting it, or by causing it to carry a load beyond its capacity or by\ncausing it to walk or run bey ond its ability or by engaging it in work\nif it is unable to work because of illness, wound or Khatira, or any\nother cause, or by feeding it harmful substance or in any other\nmanner whatsoever or leave publicly any animal or bird which he or\nshe has grown up because of its being ill or aged or otherwise treat it\ncruelly or mercilessly.\nProvided that nothing shall bar the using of minimum force in\norder to make any animal or bird do any work or carry a load\naccording to its physical capacity or make it run , with the objective\nto teach or train it to do any wok or make it efficient on its work.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits the offence referred to in sub-\nsection (1) shall be liable to a sentence of imprisonment for a term\nnot exceeding three months or a fine not exceeding five thousand\nrupees or both the sentences.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"291","title":"Prohibition of killing animals or birds in public places","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"Except\nas otherwise provided in this Act, no person shall kill any animal or\nbird in any public place other than a religious place wher e there is a\ntradition to offer sacrifice of an animal or bird.\nProvided that nothing shall bar the killing of any animal or\nbird in a fair, feast, exhibition or event or place where there is a\ntradition of slaughtering animals or birds being practiced f rom time\nimmemorial.\nExplanation: For the purposes of this Section, the term\n“public place” means a way, road, bridge, meadow or place for\nmovement of human beings.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"In making sacrifice of an animal or bird under sub -\nsection (1), no sacrifice of such an imal or bird shall be executed in\nany public place or religious place other than a religious place where\nthe sacrifice of animals or birds has been in practice from time\nimmemorial.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"In making sacrifice of an animal or bird under sub -\nsection (1), any a lternative measure, if any available, to such\nsacrificing shall be adopted.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"Where it is necessary to make sacrifice of an animal or\nbird being it not possible to adopt the measure under sub -section (3),\nsuch sacrifice shall be made at such place and in accordance with\nsuch method as determined by the manager of the concerned\nreligious place.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in this Section shall be liable to a sentence of\nimprisonment for a term not exceeding one month or a fine not\nexceeding five thousand rupees or both the sentences.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"292","title":"Statute of limitation","content":"No complaint shall lie in relation to any of the\noffences under Section 290, after the expiry of three months from the\ndate of commission of such off ence, and in relation to any of the\nother offences under this Chapter, after the expiry of three months\nfrom the date of knowledge of commission of such act.\nPart-3\nOffences against Individual Privacy and Prestige","children":[]}]},{"tier":1,"nodeType":"chapter","identifier":"Chapter-1","title":null,"content":"Offences against Privacy","children":[{"tier":2,"nodeType":"rule","identifier":"293","title":"Prohibition of listening to or recording other's conversation","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall, by using a mechanical device, listen to, or record,\nany conversation held between two or more persons, without\npermission of the competent authority or consent of such pers ons\nholding conversation.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) shall be liable to a sentence of\nimprisonment for a term not exceeding two years or a fine not\nexceeding twenty thousand rupees or both the sentences.\nProvided that this Section shall not apply to any speech or\nstatement made publicly.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"294","title":"Prohibition of divulging confidential matter","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall\ndivulge another person's confidential matter, which he or she comes\nto know from su ch person in the course of his or her professional\nwork, except where such divulgence is compelled by law or\npermitted by such person.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits the offence referred to in sub-\nsection (1) shall be liable to a sentence of imprisonment for a t erm\nnot exceeding one year or a fine not exceeding ten thousand rupees\nor both the sentences.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"295","title":"Prohibition of taking or disfiguring photograph of any person","content":"without his or her consent: (1) No person shall, without consent of\nanother person, take a phot ograph of that other person or make\nanother photograph by mixing other's photograph with the\nphotograph of that other person.\nProvided that a person who, while taking a photograph of any\npublic place, happens to take also a photograph of any person\nremaining in such place shal l not be considered to commit the\noffence under this Section.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) shall be liable to a sentence of\nimprisonment for a term not exceeding one year or a fine not\nexceeding ten thousand rupees or both the sentences.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"No person shall make a disfigured photograph by\nmixing some part of one's photograph with another part of other's\nphotograph or in any other manner or publish such disfigured\nphotograph.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (3) shall be liable to a sentence of\nimprisonment for a term not exceeding two years or a fine not\nexceeding twenty thousand rupees or both the sentences.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"296","title":"Prohibition of giving or selling one’s photograph to another","content":"without consent: (1) No person shall give or sell one's photograph\nwithout his or her consent to another person, or publish, publicize,\npurchase or sell such photograph, with the intention of annoying,\ndisturbing or troubling him or her or taking any undue benefit from\nhim or her or taking benefit by making commercial use of such\nphotograph.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) shall b e liable to a sentence of\nimprisonment for a term not exceeding three years or a fine not\nexceeding thirty thousand rupees or both the sentences.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"297","title":"Prohibition of opening letters or tapping telephone conversation","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall open a person's let ter or tap or record a person’s\ntelephone conversation by using any mechanical device, without\npermission of the competent authority or the concerned person.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committed, an\noffence under sub -section (1) shall be li able to a sentence of\nimprisonment for a term not exceeding two years or a fine not\nexceeding twenty thousand rupees or both the sentences.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"298","title":"Prohibition of breaching privacy through electronic means","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall obtain, in an unauthorized manne r, a notice,\ninformation and correspondence lying in or to be transmitted from\nany electronic means or breach privacy thereof, or transfer, or cause\nto be transferred, the same to another person in an unauthorized\nmanner.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or cause s to be committed, the\noffence referred to in sub-section (1) shall be liable to a sentence of\nimprisonment for a term not exceeding two years or a fine not\nexceeding twenty thousand rupees or both the sentences.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"299","title":"Prohibition of deceitfully making tele phone calls or transmitting","content":"messages: (1) No person shall deceitfully make, or cause to be made,\nany telephone call or transmit any message, whether giving his or her\nidentity or not, with the intention of avoiding, deceiving, annoying or\ntroubling another person.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits the offence referred to in sub-\nsection (1) shall be liable to a sentence of imprisonment for a term\nnot exceeding two years or a fine not exceeding twenty thousand\nrupees or both the sentences.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"300","title":"Prohibition of writing letters with dishonest intention of causing","content":"annoyance: (1) No person shall, with the dishonest intention of\ncausing fear, terror or pain to, or annoying, insulting or defaming\nanother person, threat, annoy, tease that other person by writing or\ncausing to be written any letter, pamphlet or document of any other\ntype or through electronic means or otherwise behave such person\nimproperly.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) shall be liable to a sente nce of\nimprisonment for a term not exceeding one year or a fine not\nexceeding ten thousand rupees or both the sentences.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"301","title":"Prohibition search other's body","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person, except the\ncompetent authority, or with the order of the competent authority, or\na person deputed for security purpose, with the permission of the\ncompetent authority, shall search, or cause to be searched, another\nperson's body, vehicle or personal belongings without consent of that\nother person.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits, or causes t o be committed, the\noffence referred to in sub-section (1) shall be liable to a sentence of\nimprisonment for a term not exceeding one year or a fine not\nexceeding ten thousand rupees or both the sentences.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"302","title":"Prohibition of unauthorized entry into other' s residence","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No\nperson, except the competent authority or with the order of such\nauthority under law, shall authoritatively enter into another person's\nhouse, breach the privacy of the house owner or his or her family or\nsearch, or cause to be searched , such house, without the consent of\nthe concerned house owner.\nExplanation: For the purposes of this Section, the term\n\"house\" means a house, residence, housing, room where a person is\ndwelling, and this term also includes a hotel room, camp and tent\nwhere such person is staying to spend a night.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person who commits the offence referred to in sub-\nsection (1) shall be liable to a sentence of imprisonment for a term\nnot exceeding three years or a fine not exceeding thirty thousand\nrupees or both the sentences.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"303","title":"Compensation to be paid","content":"Where a person derives any benefit or\ncauses any kind of damage, loss, annoyance or injury to another\nperson by committing the offence referred to in this Chapter, a\ncompensation for such damage, loss, annoyance or inj ury shall also\nbe ordered to be paid by the offender to the victim.","children":[]},{"tier":2,"nodeType":"rule","identifier":"304","title":"Statute of limitation","content":"No complaint shall lie after the expiry of three\nmonths from the date of commission of any offence under this\nChapter.","children":[]}]},{"tier":1,"nodeType":"chapter","identifier":"Chapter-2","title":null,"content":"Offence Relating to Defamation","children":[{"tier":2,"nodeType":"rule","identifier":"305","title":"Prohibition of committing slander","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall slander\nanother person.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"For the purposes of sub -section (1), a person who uses\ndegrading words, spoken or said, with the intention of lowering the\nreputation of another person shall be deemed to commit slander.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"A person who commits, or causes to be committed, the\noffence referred to in sub-section (1) shall be liable to a sentence of\nimprisonment for a term not exceeding one year or a fine not\nexceeding ten thousand rupees or both the sentences.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"306","title":"Prohibition of committing libel","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall defame\nanother person.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"For the purposes of sub -section (1), a person who\ncommits any of the following acts shall be deemed to commit\ndefamation:\n(a) By words in writing, by conduct or by signs or by\nvisible representation or by publicity or by other means,\ndamaging the character of another person by making\nimputation that, directly or indirectly, in the estimation\nof others, lowers the personal or moral character,\nconduct or reputati on of that other person, or making\nimputation that causes it to be believed that the body of\nthat other person is in a state generally considered as\ndisgraceful or disseminating or publishing such\nimputation, with the intention of harming, or knowing,\nor h aving a reasonable reason to believe that, such\nimputation will harm, the reputation of that other\nperson, or knowingly selling or distribution any thing\nwhich is used as a means of libeling any one,\n(b) Making any imputation against a deceased pers on if the\nimputation would harm the reputation of that person if\nliving, and is intended to be hurtful to the feelings of his\nor her family or other near relatives,\n(c) Making or expressing an imputation in the form of an\nalternative or ironically.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"Notwithstanding anything contained elsewhere in sub -\nsection (2), none of the following acts shall be considered to be libel:\n(a) Publishing or broadcasting any thing which is true\nconcerning any person, along with the evidence and\nbasis, for public good,\n(b) Publishing in good faith and decently any thing\nrespecting the conduct of any public servant in the\ndischarge of his or her public functions or respecting his\nor her character only so far as his or her character\nappears in that conduct,\n(c) Expressing in good fai th any opinion respecting the\nconduct of public office or position of any person and\nrespecting his or her character only so far as his or her\ncharacter appears in that conduct,\n(d) Expressing in good faith and decently any opinion\nrespecting the merits of any performance which its\nauthor has submitted to the public for opinion or\nrespecting the character of the author only so far as his\nor her character appears in such performance,\n(e) Passing in good faith any censure on the conduct of a\nperson who has ov er another person any authority,\neither conferred by law or arising out of a contract made\nwith that other person in matters to which such authority\nrelates.\n(f) Investigating into any offence in accordance with law or\npreferring accusation against him or her on that basis in\naccordance with law,\n(g) Cautioning a person against other person, for his or her\nbenefit or for the benefit of a person having his or her\ninterest or for the benefit of the public.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"307","title":"Punishment for libel","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"A person who commits, or causes to be\ncommitted, libel shall be liable to a sentence of imprisonment for a\nterm not exceeding two years or a fine not exceeding twenty\nthousand rupees or both the sentences.\nProvided that if libel is committed or, caused to be committed,\nby means of electronic or other means of mass communication, there\nshall be imposed an additional sentence of imprisonment for a term\nnot exceeding one year or a fine not exceeding ten thousand rupees\nin addition to such punishment.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"If a person is convicted of libeling another person or\ncausing such libel, a reasonable compensation to be set having regard\nto, inter alia , the gravity of the offence, effect caused to the\nreputation of such person and the commission of libel by means of\nelectronic or other means of mass communication, shall be ordered\nto be paid by the offender to th e libeled person, and litigation costs\nshall also be ordered to be paid by the offender to the libeled person.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"If a person is convicted of libeling a deceased under this\nChapter, such compensation and litigation costs shall be ordered to\nbe paid by the offender to the near successor to the deceased whose\nfeeling was hurt.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"308","title":"Statute of limitation","content":"No complaint shall lie after the expiry of three\nmonths from the date of knowledge of commission of any offence\nunder this Chapter.","children":[]}]}]}$LEGAL_83f35e1ef362eb$::jsonb
)
